            continue
        print('='*80)
        print(f'{method.upper()} {path}  [{op.get("operationId")}]')
        print('security:', op.get('security'))
        params = op.get('parameters', [])
        if params:
            print('params:', json.dumps(params, indent=2))
        rb = op.get('requestBody')
        if rb:
            schema = rb.get('content', {}).get('application/json', {}).get('schema', {})
            print('REQUEST:')
            print(json.dumps(schema, indent=2))
        responses = op.get('responses', {})
        for code, resp in responses.items():
            content = resp.get('content', {}).get('application/json', {}).get('schema', {})
            if code.startswith('2'):
                print(f'SUCCESS {code}:')
                print(json.dumps(content, indent=2)[:4000])
            else:
                # just extract error codes
                err_enum = content.get('properties', {}).get('code', {}).get('enum', [])
                if err_enum:
                    print(f'ERROR {code}: {err_enum}')
        print()
