// Materialize MongoDB collections and indexes for the lab logistics app.
// Idempotent: drop + recreate.

const dbName = (typeof process !== 'undefined' && process.env && process.env.MONGO_DB)
  ? process.env.MONGO_DB
  : 'arena';

// When invoked via mongosh URI the current db is already selected.
const target = db;

const collections = ['audit_entries', 'audit_details'];

collections.forEach((name) => {
  try { target[name].drop(); } catch (e) { /* ignore */ }
});

target.createCollection('audit_entries');
target.audit_entries.createIndex({ auditId: 1 }, { unique: true, name: 'uniq_audit_id' });
target.audit_entries.createIndex({ actorId: 1, occurredAt: -1 }, { name: 'actor_time' });
target.audit_entries.createIndex({ entityType: 1, entityId: 1, occurredAt: -1 }, { name: 'entity_time' });
target.audit_entries.createIndex({ action: 1, occurredAt: -1 }, { name: 'action_time' });
target.audit_entries.createIndex({ role: 1, occurredAt: -1 }, { name: 'role_time' });
target.audit_entries.createIndex({ success: 1, occurredAt: -1 }, { name: 'success_time' });
target.audit_entries.createIndex({ occurredAt: -1 }, { name: 'occurred_at' });
target.audit_entries.createIndex(
  { action: 'text', entityType: 'text', entityId: 'text', role: 'text' },
  { name: 'audit_text', default_language: 'english' }
);

print('mongo collections materialized');

