package main

import (
	"time"

	"github.com/google/uuid"
)

const (
	RoleAdministrator = "administrator"
	RoleDispatcher    = "dispatcher"
	RoleRequester     = "requester"
	RoleCollection    = "collection_professional"
	RoleDelivery      = "delivery_partner"
	RoleNode          = "node_handler"
	RoleLab           = "laboratory_team"
)

var allRoles = []string{
	RoleAdministrator, RoleDispatcher, RoleRequester,
	RoleCollection, RoleDelivery, RoleNode, RoleLab,
}

func validRole(r string) bool {
	for _, x := range allRoles {
		if x == r {
			return true
		}
	}
	return false
}

func isAdminOrDispatcher(role string) bool {
	return role == RoleAdministrator || role == RoleDispatcher
}

const (
	OriginHome   = "home"
	OriginClinic = "clinic"
	OriginNode   = "node"
)

const (
	FnCollection = "collection_point"
	FnTransfer   = "transfer_point"
	FnHub        = "hub"
	FnLaboratory = "laboratory"
)

const (
	KindCollection = "collection"
	KindTransport  = "transport"
	KindNode       = "node"
	KindLaboratory = "laboratory"
)

const (
	AssignOffered    = "offered"
	AssignAccepted   = "accepted"
	AssignPending    = "pending"
	AssignInProgress = "in_progress"
	AssignCompleted  = "completed"
	AssignCancelled  = "cancelled"
	AssignAtPickup   = "at_pickup"
	AssignPickedUp   = "picked_up"
	AssignInTransit  = "in_transit"
	AssignArrived    = "arrived"
	AssignDelivered  = "delivered"
)

const (
	SampleRequested     = "requested"
	SampleAssigned      = "assigned"
	SampleCollecting    = "collecting"
	SampleSealed        = "sealed"
	SampleInTransit     = "in_transit"
	SampleAtNode        = "at_node"
	SampleAtLab         = "at_laboratory"
	SampleReceived      = "received"
	SampleException     = "exception"
	SampleExpired       = "expired"
	SampleCancelled     = "cancelled"
	SampleUnserviceable = "unserviceable"
)

const (
	JourneyPlanned    = "planned"
	JourneyActive     = "active"
	JourneyCompleted  = "completed"
	JourneyCancelled  = "cancelled"
	JourneyReplaced   = "replaced"
	JourneyException  = "exception"
	JourneyExpired    = "expired"
)

const (
	TypeAmberID  = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1"
	TypeIndigoID = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2"
	TypeFrostID  = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3"
	TypePulseID  = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa4"
)

const locationStaleAfter = 15 * time.Minute
const offerTTL = 10 * time.Minute
const noWorkerWait = 30 * time.Minute

type Coordinate struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

func validCoord(c Coordinate) bool {
	return c.Latitude >= -90 && c.Latitude <= 90 && c.Longitude >= -180 && c.Longitude <= 180
}

type Certification struct {
	Code      string  `json:"code"`
	Active    bool    `json:"active"`
	ExpiresAt *string `json:"expiresAt,omitempty"`
}

type LocationFunctions struct {
	CollectionPoint bool `json:"collection_point"`
	TransferPoint   bool `json:"transfer_point"`
	Hub             bool `json:"hub"`
	Laboratory      bool `json:"laboratory"`
}

type Capacity struct {
	CapacityUnits        int `json:"capacityUnits"`
	ReservedUnits        int `json:"reservedUnits"`
	AvailableUnits       int `json:"availableUnits"`
	CooledCapacityUnits  int `json:"cooledCapacityUnits"`
	CooledReservedUnits  int `json:"cooledReservedUnits"`
	CooledAvailableUnits int `json:"cooledAvailableUnits"`
}

func (c Capacity) fillAvail() Capacity {
	c.AvailableUnits = c.CapacityUnits - c.ReservedUnits
	c.CooledAvailableUnits = c.CooledCapacityUnits - c.CooledReservedUnits
	if c.AvailableUnits < 0 {
		c.AvailableUnits = 0
	}
	if c.CooledAvailableUnits < 0 {
		c.CooledAvailableUnits = 0
	}
	return c
}

type TimelineEntry struct {
	EventID    int64          `json:"eventId"`
	Action     string         `json:"action"`
	ActorID    string         `json:"actorId"`
	Role       string         `json:"role"`
	EntityType string         `json:"entityType"`
	EntityID   string         `json:"entityId"`
	Success    bool           `json:"success"`
	OccurredAt string         `json:"occurredAt"`
	Details    map[string]any `json:"details"`
}

func newUUID() string { return uuid.NewString() }

func ptrStr(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

func formatTime(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

func isLocationStale(recordedAt *time.Time, now time.Time) bool {
	if recordedAt == nil || recordedAt.IsZero() {
		return true
	}
	return now.Sub(*recordedAt) > locationStaleAfter
}

