package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"net/http"
	"strings"
	"time"
)

func (st *Store) handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	ctx := r.Context()
	var userID, hash string
	var active bool
	err := st.PG.QueryRowContext(ctx, `SELECT user_id, password_hash, active FROM users WHERE username = $1`, req.Username).
		Scan(&userID, &hash, &active)
	if err == sql.ErrNoRows || !checkPassword(hash, req.Password) || !active {
		st.writeAudit(ctx, "", "", "authenticate_user", "user", req.Username, false, map[string]any{"reason": "invalid_credentials"})
		writeErr(w, http.StatusUnauthorized, "invalid_credentials", "invalid credentials")
		return
	}
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	roles, err := st.loadRoles(ctx, userID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	token := newToken()
	activeRole := ""
	if len(roles) == 1 {
		activeRole = roles[0]
	}
	_, err = st.PG.ExecContext(ctx, `INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,$3)`, token, userID, activeRole)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	st.writeAudit(ctx, userID, activeRole, "authenticate_user", "user", userID, true, map[string]any{"username": req.Username})
	_, _ = st.writeTimeline(ctx, nil, "", "", "", "authenticate_user", userID, activeRole, "user", userID, true, map[string]any{"username": req.Username})
	writeData(w, http.StatusOK, map[string]any{
		"sessionToken": token,
		"userId":       userID,
		"roles":        roles,
		"activeRole":   activeRole,
	})
}

func (st *Store) handleSelectRole(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	var req struct {
		Role string `json:"role"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if !validRole(req.Role) {
		writeErr(w, http.StatusBadRequest, "invalid_role", "invalid role")
		return
	}
	if !sess.hasRole(req.Role) {
		writeErr(w, http.StatusForbidden, "role_not_held", "role not held")
		return
	}
	_, err := st.PG.ExecContext(r.Context(), `UPDATE sessions SET active_role = $1 WHERE token = $2`, req.Role, sess.Token)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	st.audit(r.Context(), sess, "select_active_role", "session", sess.UserID, true, map[string]any{"role": req.Role})
	writeData(w, http.StatusOK, map[string]any{
		"activeRole": req.Role,
		"roles":      sess.Roles,
	})
}

func (st *Store) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		Username           string          `json:"username"`
		InitialPassword    string          `json:"initialPassword"`
		Email              string          `json:"email"`
		FullName           string          `json:"fullName"`
		Phone              string          `json:"phone"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             bool            `json:"active"`
		AssignedLocationID string          `json:"assignedLocationId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if strings.TrimSpace(req.Username) == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
		writeErr(w, http.StatusBadRequest, "invalid_user", "invalid user")
		return
	}
	for _, role := range req.Roles {
		if !validRole(role) {
			writeErr(w, http.StatusBadRequest, "invalid_user", "invalid role")
			return
		}
	}
	for _, c := range req.Certifications {
		if strings.TrimSpace(c.Code) == "" {
			writeErr(w, http.StatusBadRequest, "invalid_certification", "invalid certification")
			return
		}
	}
	var exists int
	_ = st.PG.QueryRowContext(r.Context(), `SELECT COUNT(*) FROM users WHERE username = $1`, req.Username).Scan(&exists)
	if exists > 0 {
		writeErr(w, http.StatusConflict, "username_exists", "username exists")
		return
	}
	hash, err := hashPassword(req.InitialPassword)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	id := newUUID()
	ctx := r.Context()
	err = st.tx(ctx, func(tx *sql.Tx) error {
		var loc any
		if req.AssignedLocationID != "" {
			loc = req.AssignedLocationID
		}
		if _, err := tx.ExecContext(ctx, `
			INSERT INTO users (user_id, username, password_hash, email, full_name, phone, active, assigned_location_id)
			VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
			id, req.Username, hash, req.Email, req.FullName, req.Phone, req.Active, loc); err != nil {
			return err
		}
		for _, role := range uniqStrings(req.Roles) {
			if _, err := tx.ExecContext(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1,$2)`, id, role); err != nil {
				return err
			}
		}
		for _, q := range uniqStrings(req.Qualifications) {
			if _, err := tx.ExecContext(ctx, `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2)`, id, q); err != nil {
				return err
			}
		}
		for _, c := range req.Certifications {
			var exp any
			if c.ExpiresAt != nil && *c.ExpiresAt != "" {
				t, err := parseTime(*c.ExpiresAt, "invalid_certification")
				if err != nil {
					return err
				}
				exp = t
			}
			if _, err := tx.ExecContext(ctx, `
				INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`,
				id, c.Code, c.Active, exp); err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		if e, ok := err.(*apiError); ok {
			writeAPIError(w, e)
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	data, _ := st.userPayload(ctx, id)
	st.audit(ctx, sess, "create_user", "user", id, true, map[string]any{"username": req.Username})
	writeData(w, http.StatusCreated, data)
}

func (st *Store) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		UserID             string          `json:"userId"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             bool            `json:"active"`
		AssignedLocationID string          `json:"assignedLocationId"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	for _, role := range req.Roles {
		if !validRole(role) {
			writeErr(w, http.StatusBadRequest, "invalid_json", "invalid role")
			return
		}
	}
	for _, c := range req.Certifications {
		if strings.TrimSpace(c.Code) == "" {
			writeErr(w, http.StatusBadRequest, "invalid_certification", "invalid certification")
			return
		}
	}
	ctx := r.Context()
	var exists int
	_ = st.PG.QueryRowContext(ctx, `SELECT COUNT(*) FROM users WHERE user_id = $1`, req.UserID).Scan(&exists)
	if exists == 0 {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	err := st.tx(ctx, func(tx *sql.Tx) error {
		var loc any
		if req.AssignedLocationID != "" {
			loc = req.AssignedLocationID
		}
		if _, err := tx.ExecContext(ctx, `UPDATE users SET active = $1, assigned_location_id = $2 WHERE user_id = $3`, req.Active, loc, req.UserID); err != nil {
			return err
		}
		if _, err := tx.ExecContext(ctx, `DELETE FROM user_roles WHERE user_id = $1`, req.UserID); err != nil {
			return err
		}
		for _, role := range uniqStrings(req.Roles) {
			if _, err := tx.ExecContext(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1,$2)`, req.UserID, role); err != nil {
				return err
			}
		}
		if req.Qualifications != nil {
			if _, err := tx.ExecContext(ctx, `DELETE FROM user_qualifications WHERE user_id = $1`, req.UserID); err != nil {
				return err
			}
			for _, q := range uniqStrings(req.Qualifications) {
				if _, err := tx.ExecContext(ctx, `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2)`, req.UserID, q); err != nil {
					return err
				}
			}
		}
		if req.Certifications != nil {
			if _, err := tx.ExecContext(ctx, `DELETE FROM user_certifications WHERE user_id = $1`, req.UserID); err != nil {
				return err
			}
			for _, c := range req.Certifications {
				var exp any
				if c.ExpiresAt != nil && *c.ExpiresAt != "" {
					t, err := parseTime(*c.ExpiresAt, "invalid_certification")
					if err != nil {
						return err
					}
					exp = t
				}
				if _, err := tx.ExecContext(ctx, `
					INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`,
					req.UserID, c.Code, c.Active, exp); err != nil {
					return err
				}
			}
		}
		return nil
	})
	if err != nil {
		if e, ok := err.(*apiError); ok {
			writeAPIError(w, e)
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	data, _ := st.userPayload(ctx, req.UserID)
	st.audit(ctx, sess, "update_user_access", "user", req.UserID, true, nil)
	writeData(w, http.StatusCreated, data)
}

func (st *Store) handleReadUser(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	userID := r.PathValue("userId")
	if sess.UserID != userID {
		if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
			writeAPIError(w, err)
			return
		}
	}
	data, err := st.userPayload(r.Context(), userID)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	writeData(w, http.StatusOK, data)
}

func (st *Store) userPayload(ctx context.Context, userID string) (map[string]any, error) {
	var username, email, fullName, phone string
	var active bool
	err := st.PG.QueryRowContext(ctx, `
		SELECT username, email, full_name, phone, active FROM users WHERE user_id = $1`, userID).
		Scan(&username, &email, &fullName, &phone, &active)
	if err != nil {
		return nil, err
	}
	roles, _ := st.loadRoles(ctx, userID)
	quals := []string{}
	rows, err := st.PG.QueryContext(ctx, `SELECT qualification FROM user_qualifications WHERE user_id = $1`, userID)
	if err == nil {
		quals, _ = scanStrings(rows)
	}
	certs := []Certification{}
	crows, err := st.PG.QueryContext(ctx, `SELECT code, active, expires_at FROM user_certifications WHERE user_id = $1`, userID)
	if err == nil {
		defer crows.Close()
		for crows.Next() {
			var c Certification
			var exp sql.NullTime
			if err := crows.Scan(&c.Code, &c.Active, &exp); err == nil {
				if exp.Valid {
					s := formatTime(exp.Time)
					c.ExpiresAt = &s
				}
				certs = append(certs, c)
			}
		}
	}
	return map[string]any{
		"userId":         userID,
		"username":       username,
		"email":          email,
		"fullName":       fullName,
		"phone":          phone,
		"roles":          roles,
		"qualifications": quals,
		"certifications": certs,
		"active":         active,
	}, nil
}

func (st *Store) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits int    `json:"capacityUnits"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if req.CapacityUnits < 0 {
		writeErr(w, http.StatusBadRequest, "invalid_capacity", "invalid capacity")
		return
	}
	ctx := r.Context()
	res, err := st.PG.ExecContext(ctx, `UPDATE users SET available = $1, capacity_units = $2 WHERE user_id = $3`,
		req.Available, req.CapacityUnits, req.WorkerID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	n, _ := res.RowsAffected()
	if n == 0 {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	st.audit(ctx, sess, "set_worker_availability", "worker", req.WorkerID, true, map[string]any{"available": req.Available})
	writeData(w, http.StatusOK, map[string]any{
		"workerId":      req.WorkerID,
		"available":     req.Available,
		"capacityUnits": req.CapacityUnits,
	})
}

func (st *Store) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleCollection, RoleDelivery, RoleNode, RoleLab, RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		AssignmentID string     `json:"assignmentId"`
		Coordinate   Coordinate `json:"coordinate"`
		Sequence     int        `json:"sequence"`
		RecordedAt   string     `json:"recordedAt"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if !validCoord(req.Coordinate) {
		writeErr(w, http.StatusBadRequest, "invalid_coordinate", "invalid coordinate")
		return
	}
	if req.Sequence < 1 {
		writeErr(w, http.StatusBadRequest, "invalid_sequence", "invalid sequence")
		return
	}
	recordedAt, err := parseTime(req.RecordedAt, "invalid_time")
	if err != nil {
		writeAPIError(w, err)
		return
	}
	ctx := r.Context()
	var exists int
	_ = st.PG.QueryRowContext(ctx, `SELECT COUNT(*) FROM assignments WHERE assignment_id = $1`, req.AssignmentID).Scan(&exists)
	if exists == 0 {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	var curSeq int
	_ = st.PG.QueryRowContext(ctx, `SELECT location_sequence FROM users WHERE user_id = $1`, sess.UserID).Scan(&curSeq)
	if req.Sequence <= curSeq {
		writeErr(w, http.StatusConflict, "stale_location", "stale location")
		return
	}
	_, err = st.PG.ExecContext(ctx, `
		INSERT INTO worker_locations (worker_id, assignment_id, latitude, longitude, sequence, recorded_at)
		VALUES ($1,$2,$3,$4,$5,$6)`,
		sess.UserID, req.AssignmentID, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, recordedAt)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	_, _ = st.PG.ExecContext(ctx, `
		UPDATE users SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3, location_sequence = $4
		WHERE user_id = $5`,
		req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, req.Sequence, sess.UserID)
	// propagate to samples currently held by this worker
	_, _ = st.PG.ExecContext(ctx, `
		UPDATE samples SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3
		WHERE current_holder_id = $4`,
		req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, sess.UserID)
	st.audit(ctx, sess, "record_worker_location", "assignment", req.AssignmentID, true, map[string]any{
		"coordinate": req.Coordinate, "sequence": req.Sequence,
	})
	st.emitEvent(ctx, "worker_location", "worker", sess.UserID, map[string]any{
		"assignmentId": req.AssignmentID, "coordinate": req.Coordinate,
	}, "")
	writeData(w, http.StatusCreated, map[string]any{
		"assignmentId": req.AssignmentID,
		"coordinate":   req.Coordinate,
		"sequence":     req.Sequence,
		"recordedAt":   formatTime(recordedAt),
	})
}

func (st *Store) handleReady(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 3*time.Second)
	defer cancel()
	if err := st.ping(ctx); err != nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "not_ready"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"status": "ready"})
}

func (st *Store) handleBootstrap(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	now := time.Now().UTC()
	user := map[string]any{
		"userId":                 sess.UserID,
		"username":               sess.Username,
		"fullName":               sess.FullName,
		"roles":                  sess.Roles,
		"activeRole":             sess.ActiveRole,
		"roleSelectionRequired":  sess.ActiveRole == "" && len(sess.Roles) > 1,
	}
	data := map[string]any{
		"user":       user,
		"serverTime": formatTime(now),
	}
	if sess.ActiveRole == RoleRequester || containsStr(sess.Roles, RoleRequester) {
		samples, _ := st.listRequesterSamples(r.Context(), sess.UserID)
		data["requesterSamples"] = samples
	}
	if isAdminOrDispatcher(sess.ActiveRole) {
		ops, _ := st.buildOperationsState(r.Context(), "")
		data["operations"] = ops
	}
	writeData(w, http.StatusOK, data)
}

func (st *Store) listRequesterSamples(ctx context.Context, requesterID string) ([]map[string]any, error) {
	rows, err := st.PG.QueryContext(ctx, `
		SELECT s.sample_id, s.request_id, s.status, s.serviceability, s.target_laboratory_id,
		       r.requested_at, r.delivery_deadline
		FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
		WHERE s.requester_id = $1
		ORDER BY r.created_at DESC`, requesterID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var sampleID, requestID, status, svc string
		var lab sql.NullString
		var requested, deadline time.Time
		if err := rows.Scan(&sampleID, &requestID, &status, &svc, &lab, &requested, &deadline); err != nil {
			continue
		}
		out = append(out, map[string]any{
			"sampleId":            sampleID,
			"requestId":           requestID,
			"status":              status,
			"serviceability":      svc,
			"targetLaboratoryId":  nullStr(lab),
			"requestedAt":         formatTime(requested),
			"deliveryDeadline":    formatTime(deadline),
		})
	}
	return out, nil
}

func (st *Store) handleEvents(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	since := int64(0)
	if q := r.URL.Query().Get("since"); q != "" {
		var n int64
		if _, err := parseInt64(q, &n); err == nil {
			since = n
		}
	}
	upgrade := strings.Contains(strings.ToLower(r.Header.Get("Upgrade")), "websocket")
	if upgrade {
		st.handleWSEvents(w, r, sess, since)
		return
	}
	ctx := r.Context()
	rows, err := st.PG.QueryContext(ctx, `
		SELECT id, type, entity_type, entity_id, payload, created_at, audience_role
		FROM realtime_events
		WHERE id > $1
		  AND (audience_role IS NULL OR audience_role = $2)
		ORDER BY id ASC
		LIMIT 500`, since, sess.ActiveRole)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	defer rows.Close()
	events := []map[string]any{}
	var cursor int64 = since
	for rows.Next() {
		var id int64
		var typ, et, eid string
		var payload []byte
		var created time.Time
		var aud sql.NullString
		if err := rows.Scan(&id, &typ, &et, &eid, &payload, &created, &aud); err != nil {
			continue
		}
		var p map[string]any
		_ = json.Unmarshal(payload, &p)
		if p == nil {
			p = map[string]any{}
		}
		events = append(events, map[string]any{
			"id":         id,
			"type":       typ,
			"entityType": et,
			"entityId":   eid,
			"payload":    p,
			"createdAt":  formatTime(created),
		})
		cursor = id
	}
	writeData(w, http.StatusOK, map[string]any{"events": events, "cursor": cursor})
}

func parseInt64(s string, dest *int64) (int, error) {
	var n int64
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, errJSON("invalid_json", "invalid", 400)
		}
		n = n*10 + int64(c-'0')
	}
	*dest = n
	return 0, nil
}

