package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"net/http"
	"time"
)

func funcsFromList(list []string) (LocationFunctions, error) {
	var f LocationFunctions
	if len(list) == 0 {
		return f, errJSON("invalid_location_function", "invalid location function", http.StatusBadRequest)
	}
	for _, x := range list {
		switch x {
		case FnCollection:
			f.CollectionPoint = true
		case FnTransfer:
			f.TransferPoint = true
		case FnHub:
			f.Hub = true
		case FnLaboratory:
			f.Laboratory = true
		default:
			return f, errJSON("invalid_location_function", "invalid location function", http.StatusBadRequest)
		}
	}
	return f, nil
}

func locationPayload(id, name string, lat, lng, cov float64, handling int, active bool, f LocationFunctions) map[string]any {
	return map[string]any{
		"locationId":      id,
		"name":            name,
		"coordinate":      Coordinate{Latitude: lat, Longitude: lng},
		"coverageKm":      cov,
		"handlingMinutes": handling,
		"active":          active,
		"functions":       f,
	}
}

func (st *Store) bumpNetwork(ctx context.Context, tx *sql.Tx) {
	q := `UPDATE app_meta SET value = (value::int + 1)::text WHERE key = 'network_revision'`
	if tx != nil {
		_, _ = tx.ExecContext(ctx, q)
	} else {
		_, _ = st.PG.ExecContext(ctx, q)
	}
	st.recomputeServiceability(ctx)
}

func (st *Store) handleCreateLocation(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		Name            string     `json:"name"`
		Coordinate      Coordinate `json:"coordinate"`
		CoverageKm      *float64   `json:"coverageKm"`
		HandlingMinutes *int       `json:"handlingMinutes"`
		Active          bool       `json:"active"`
		Functions       []string   `json:"functions"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if !validCoord(req.Coordinate) {
		writeErr(w, http.StatusBadRequest, "invalid_coordinate", "invalid coordinate")
		return
	}
	cov := 5.0
	if req.CoverageKm != nil {
		cov = *req.CoverageKm
	}
	if cov <= 0 || cov > 5 {
		writeErr(w, http.StatusBadRequest, "invalid_node_coverage", "invalid node coverage")
		return
	}
	handling := 0
	if req.HandlingMinutes != nil {
		handling = *req.HandlingMinutes
	}
	if handling < 0 || handling > 1440 {
		writeErr(w, http.StatusBadRequest, "invalid_handling_time", "invalid handling time")
		return
	}
	f, err := funcsFromList(req.Functions)
	if err != nil {
		writeAPIError(w, err)
		return
	}
	id := newUUID()
	ctx := r.Context()
	_, err = st.PG.ExecContext(ctx, `
		INSERT INTO locations (location_id, name, latitude, longitude, coverage_km, handling_minutes, active,
		                       fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory)
