func (st *Store) handleUpdateLocation(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		LocationID      string      `json:"locationId"`
		Name            string      `json:"name"`
		Coordinate      Coordinate  `json:"coordinate"`
		CoverageKm      *float64    `json:"coverageKm"`
		HandlingMinutes *int        `json:"handlingMinutes"`
		Functions       []string    `json:"functions"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if !validCoord(req.Coordinate) {
		writeErr(w, http.StatusBadRequest, "invalid_coordinate", "invalid coordinate")
		return
	}
	ctx := r.Context()
	var name string
	var lat, lng, cov float64
	var handling int
	var active bool
	var f LocationFunctions
	err := st.PG.QueryRowContext(ctx, `
		SELECT name, latitude, longitude, coverage_km, handling_minutes, active,
		       fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory
		FROM locations WHERE location_id = $1`, req.LocationID).
		Scan(&name, &lat, &lng, &cov, &handling, &active, &f.CollectionPoint, &f.TransferPoint, &f.Hub, &f.Laboratory)
	if err == sql.ErrNoRows {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
		return
	}
	if req.CoverageKm != nil {
		if *req.CoverageKm <= 0 || *req.CoverageKm > 5 {
			writeErr(w, http.StatusBadRequest, "invalid_node_coverage", "invalid node coverage")
			return
		}
		cov = *req.CoverageKm
	}
	if req.HandlingMinutes != nil {
		if *req.HandlingMinutes < 0 || *req.HandlingMinutes > 1440 {
			writeErr(w, http.StatusBadRequest, "invalid_handling_time", "invalid handling time")
			return
		}
		handling = *req.HandlingMinutes
	}
	if req.Functions != nil {
		nf, err := funcsFromList(req.Functions)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		f = nf
	}
	_, err = st.PG.ExecContext(ctx, `
		UPDATE locations SET name=$1, latitude=$2, longitude=$3, coverage_km=$4, handling_minutes=$5,
		  fn_collection_point=$6, fn_transfer_point=$7, fn_hub=$8, fn_laboratory=$9
		WHERE location_id=$10`,
		req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, cov, handling,
		f.CollectionPoint, f.TransferPoint, f.Hub, f.Laboratory, req.LocationID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	st.bumpNetwork(ctx, nil)
	st.audit(ctx, sess, "update_location", "location", req.LocationID, true, nil)
	writeData(w, http.StatusCreated, locationPayload(req.LocationID, req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, cov, handling, active, f))
}

