		Active         bool     `json:"active"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if req.FromLocationID == "" || req.ToLocationID == "" || req.FromLocationID == req.ToLocationID || req.TravelMinutes < 1 || req.CostUnits < 0 {
