	}
	ctx := r.Context()
	var name string
	var qreq bool
	var qual string
	var cooled, batch bool
	err := st.PG.QueryRowContext(ctx, `
		SELECT name, qualified_collector_required, required_qualification, requires_cooled_route, batching_allowed
		FROM sample_types WHERE sample_type_id = $1`, req.SampleTypeID).
		Scan(&name, &qreq, &qual, &cooled, &batch)
	if err == sql.ErrNoRows {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
