	}
	if req.ContainerType == "" || req.TemperatureMinC > req.TemperatureMaxC {
		writeErr(w, http.StatusBadRequest, "invalid_handling_rule", "invalid handling rule")
		return
	}
	ctx := r.Context()
	var name string
	var qreq bool
	var qual string
	var cooled, batch bool
	err := st.PG.QueryRowContext(ctx, `
