		return
	}
	var req struct {
		FromLocationID string   `json:"fromLocationId"`
		ToLocationID   string   `json:"toLocationId"`
		TravelMinutes  int      `json:"travelMinutes"`
		CostUnits      float64  `json:"costUnits"`
		Cooled         *bool    `json:"cooled"`
		Active         bool     `json:"active"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if req.FromLocationID == "" || req.ToLocationID == "" || req.FromLocationID == req.ToLocationID || req.TravelMinutes < 1 || req.CostUnits < 0 {
		writeErr(w, http.StatusBadRequest, "invalid_connection", "invalid connection")
		return
	}
	cooled := false
	if req.Cooled != nil {
		cooled = *req.Cooled
	}
	ctx := r.Context()
	var n int
	_ = st.PG.QueryRowContext(ctx, `SELECT COUNT(*) FROM locations WHERE location_id IN ($1,$2)`, req.FromLocationID, req.ToLocationID).Scan(&n)
	if n < 2 {
		writeErr(w, http.StatusBadRequest, "invalid_connection", "invalid connection")
		return
	}
	id := newUUID()
	_, err := st.PG.ExecContext(ctx, `
		INSERT INTO connections (connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active)
		VALUES ($1,$2,$3,$4,$5,$6,$7)`,
		id, req.FromLocationID, req.ToLocationID, req.TravelMinutes, req.CostUnits, cooled, req.Active)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	_, _ = st.PG.ExecContext(ctx, `
		INSERT INTO capacity_pools (resource_id, resource_kind, capacity_units, cooled_capacity_units)
		VALUES ($1, 'connection', 0, 0) ON CONFLICT DO NOTHING`, id)
	st.bumpNetwork(ctx, nil)
	st.audit(ctx, sess, "create_connection", "connection", id, true, nil)
	writeData(w, http.StatusCreated, map[string]any{
