		RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
		BatchingAllowed            *bool    `json:"batchingAllowed"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if req.Name == "" || req.ContainerType == "" || req.TemperatureMinC > req.TemperatureMaxC {
		writeErr(w, http.StatusBadRequest, "invalid_handling_rule", "invalid handling rule")
		return
	}
	qreq := true
	if req.QualifiedCollectorRequired != nil {
		qreq = *req.QualifiedCollectorRequired
	}
	cooled := false
	if req.RequiresCooledRoute != nil {
		cooled = *req.RequiresCooledRoute
	}
	batch := true
	if req.BatchingAllowed != nil {
		batch = *req.BatchingAllowed
	}
	id := newUUID()
	ctx := r.Context()
	_, err := st.PG.ExecContext(ctx, `
		INSERT INTO sample_types (sample_type_id, name, qualified_collector_required, required_qualification,
		  container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		id, req.Name, qreq, req.RequiredQualification, req.ContainerType, req.TemperatureMinC, req.TemperatureMaxC, cooled, batch)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_handling_rule", "invalid handling rule")
		return
	}
	for _, other := range req.IncompatibleSampleTypes {
		_, _ = st.PG.ExecContext(ctx, `INSERT INTO sample_type_incompatibilities VALUES ($1,$2) ON CONFLICT DO NOTHING`, id, other)
	}
	if req.IncompatibleSampleTypes == nil {
		req.IncompatibleSampleTypes = []string{}
	}
	st.audit(ctx, sess, "create_sample_type", "sample_type", id, true, map[string]any{"name": req.Name})
	writeData(w, http.StatusCreated, map[string]any{
		"sampleTypeId":               id,
		"name":                       req.Name,
		"qualifiedCollectorRequired": qreq,
		"requiredQualification":      req.RequiredQualification,
		"containerType":              req.ContainerType,
		"temperatureMinC":            req.TemperatureMinC,
		"temperatureMaxC":            req.TemperatureMaxC,
		"incompatibleSampleTypes":    req.IncompatibleSampleTypes,
		"requiresCooledRoute":        cooled,
		"batchingAllowed":            batch,
