		LaboratoryID   string `json:"laboratoryId"`
		Reason         string `json:"reason"`
		ObservedAt     string `json:"observedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if req.Reason == "" {
		writeErr(w, http.StatusBadRequest, "invalid_reason", "invalid reason")
		return
	}
	observedAt, err := parseTime(req.ObservedAt, "invalid_time")
	if err != nil {
		writeAPIError(w, err)
		return
	}
	ctx := r.Context()
	if req.IdempotencyKey != "" {
