			writeAPIError(w, err)
			return
		}
		if hit {
			replayIdempotent(w, status, body)
			return
		}
	}
	var exists int
	_ = st.PG.QueryRowContext(ctx, `SELECT COUNT(*) FROM samples WHERE sample_id = $1`, req.SampleID).Scan(&exists)
	if exists == 0 {
		writeErr(w, http.StatusNotFound, "not_found", "not found")
