func (st *Store) expectPlanVersion(ctx context.Context, journeyID string, expected int) (int, error) {
	var current int
	err := st.PG.QueryRowContext(ctx, `SELECT plan_version FROM journeys WHERE journey_id = $1`, journeyID).Scan(&current)
	if err == sql.ErrNoRows {
		return 0, errJSON("not_found", "not found", http.StatusNotFound)
	}
	if err != nil {
		return 0, err
	}
	if current != expected {
		return current, errJSON("plan_version_conflict", "plan version conflict", http.StatusConflict)
	}
	return current, nil
}

func (st *Store) bumpPlan(ctx context.Context, tx *sql.Tx, journeyID string) (int, error) {
	var v int
	err := tx.QueryRowContext(ctx, `
		UPDATE journeys SET plan_version = plan_version + 1 WHERE journey_id = $1 RETURNING plan_version`, journeyID).Scan(&v)
	return v, err
}

func (st *Store) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		JourneyID            string         `json:"journeyId"`
		ExpectedPlanVersion  int            `json:"expectedPlanVersion"`
		ChangeType           string         `json:"changeType"`
		Changes              map[string]any `json:"changes"`
		IdempotencyKey       string         `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	allowed := map[string]bool{"reroute": true, "reassign": true, "reschedule": true, "split": true, "merge": true, "cancel": true}
	if !allowed[req.ChangeType] {
		writeErr(w, http.StatusBadRequest, "invalid_change_type", "invalid change type")
		return
	}
	ctx := r.Context()
	if req.IdempotencyKey != "" {
		hash := hashRequest("edit", req.JourneyID, req.ChangeType, itoa(req.ExpectedPlanVersion))
		hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "edit", hash)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		if hit {
			replayIdempotent(w, status, body)
			return
		}
	}
	if _, err := st.expectPlanVersion(ctx, req.JourneyID, req.ExpectedPlanVersion); err != nil {
		writeAPIError(w, err)
		return
	}
	var newVersion int
	err := st.tx(ctx, func(tx *sql.Tx) error {
		v, err := st.bumpPlan(ctx, tx, req.JourneyID)
		if err != nil {
			return err
		}
		newVersion = v
		// apply limited changes without rewriting completed work
		if req.ChangeType == "cancel" {
			_, _ = tx.ExecContext(ctx, `
				UPDATE assignments SET status = 'cancelled'
				WHERE journey_id = $1 AND status NOT IN ('completed','delivered','cancelled')`, req.JourneyID)
			_, _ = tx.ExecContext(ctx, `UPDATE journeys SET status = 'cancelled' WHERE journey_id = $1`, req.JourneyID)
			st.releaseJourneyCapacity(ctx, tx, req.JourneyID)
		}
		if req.ChangeType == "reassign" {
			if asg, ok := req.Changes["assignmentId"].(string); ok {
				if worker, ok := req.Changes["workerId"].(string); ok {
					var status string
					_ = tx.QueryRowContext(ctx, `SELECT status FROM assignments WHERE assignment_id = $1`, asg).Scan(&status)
					if status == AssignCompleted || status == AssignDelivered || status == AssignCancelled {
						return errJSON("completed_work_immutable", "completed work cannot be rewritten", http.StatusConflict)
					}
					_, _ = tx.ExecContext(ctx, `
						UPDATE assignments SET worker_id = $1, offered_worker_id = $1, status = 'offered',
						  offer_expires_at = $2 WHERE assignment_id = $3`, worker, time.Now().Add(offerTTL), asg)
				}
			}
		}
		return nil
	})
	if err != nil {
		writeAPIError(w, err)
		return
	}
	st.audit(ctx, sess, "edit_active_plan", "journey", req.JourneyID, true, map[string]any{"changeType": req.ChangeType, "planVersion": newVersion})
	_, _ = st.writeTimeline(ctx, nil, "", req.JourneyID, "", "edit_active_plan", sess.UserID, sess.ActiveRole, "journey", req.JourneyID, true, map[string]any{"changeType": req.ChangeType})
	out := map[string]any{"journeyId": req.JourneyID, "planVersion": newVersion, "status": "updated"}
	if req.IdempotencyKey != "" {
		st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "edit", hashRequest("edit", req.JourneyID, req.ChangeType, itoa(req.ExpectedPlanVersion)), http.StatusOK, out)
	}
	writeData(w, http.StatusOK, out)
}

func (st *Store) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if len(req.SampleIDs) == 0 {
		writeErr(w, http.StatusBadRequest, "invalid_split", "invalid split")
		return
	}
	ctx := r.Context()
	if req.IdempotencyKey != "" {
		hash := hashRequest("split", req.JourneyID, itoa(req.ExpectedPlanVersion))
		hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "split", hash)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		if hit {
			replayIdempotent(w, status, body)
			return
		}
	}
	if _, err := st.expectPlanVersion(ctx, req.JourneyID, req.ExpectedPlanVersion); err != nil {
		writeAPIError(w, err)
		return
	}
	newJourneyID := newUUID()
	var newVersion int
	err := st.tx(ctx, func(tx *sql.Tx) error {
		v, err := st.bumpPlan(ctx, tx, req.JourneyID)
		if err != nil {
			return err
		}
		newVersion = v
		var mode, status string
		var eta sql.NullTime
		var cost float64
		_ = tx.QueryRowContext(ctx, `SELECT route_mode, status, estimated_delivery_at, total_cost_units FROM journeys WHERE journey_id = $1`, req.JourneyID).
			Scan(&mode, &status, &eta, &cost)
		if _, err := tx.ExecContext(ctx, `
			INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, valid, active)
			VALUES ($1,$2,1,$3,$4,$5,$6,TRUE,TRUE)`, newJourneyID, req.JourneyID, mode, status, eta, cost); err != nil {
			return err
		}
		for _, sid := range req.SampleIDs {
			if _, err := tx.ExecContext(ctx, `DELETE FROM journey_samples WHERE journey_id = $1 AND sample_id = $2`, req.JourneyID, sid); err != nil {
				return err
			}
			if _, err := tx.ExecContext(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2)`, newJourneyID, sid); err != nil {
				return err
			}
			// copy unfinished assignments
			if _, err := tx.ExecContext(ctx, `
				UPDATE assignments SET journey_id = $1
				WHERE journey_id = $2 AND sample_id = $3 AND status NOT IN ('completed','delivered','cancelled')`,
				newJourneyID, req.JourneyID, sid); err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		writeAPIError(w, err)
		return
	}
	st.audit(ctx, sess, "split_journey", "journey", req.JourneyID, true, map[string]any{"newJourneyId": newJourneyID})
	out := map[string]any{
		"journeyId":    req.JourneyID,
		"planVersion":  newVersion,
		"newJourneyId": newJourneyID,
	}
	if req.IdempotencyKey != "" {
		st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "split", hashRequest("split", req.JourneyID, itoa(req.ExpectedPlanVersion)), http.StatusOK, out)
	}
	writeData(w, http.StatusOK, out)
}

func (st *Store) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	var req struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeAPIError(w, err)
		return
	}
	if len(req.SourceJourneyIDs) == 0 {
		writeErr(w, http.StatusBadRequest, "invalid_merge", "invalid merge")
		return
	}
	ctx := r.Context()
	if req.IdempotencyKey != "" {
		hash := hashRequest("merge", req.TargetJourneyID, itoa(req.ExpectedPlanVersion))
		hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "merge", hash)
		if err != nil {
			writeAPIError(w, err)
			return
		}
		if hit {
			replayIdempotent(w, status, body)
			return
		}
	}
	if _, err := st.expectPlanVersion(ctx, req.TargetJourneyID, req.ExpectedPlanVersion); err != nil {
		writeAPIError(w, err)
		return
	}
	// validate compatibility of samples
	if err := st.validateMerge(ctx, req.TargetJourneyID, req.SourceJourneyIDs); err != nil {
		writeAPIError(w, err)
		return
	}
	var newVersion int
	err := st.tx(ctx, func(tx *sql.Tx) error {
		v, err := st.bumpPlan(ctx, tx, req.TargetJourneyID)
		if err != nil {
			return err
		}
		newVersion = v
		for _, src := range req.SourceJourneyIDs {
			sids, _ := st.journeySampleIDs(ctx, src)
			for _, sid := range sids {
				_, _ = tx.ExecContext(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.TargetJourneyID, sid)
				_, _ = tx.ExecContext(ctx, `
					UPDATE assignments SET journey_id = $1
					WHERE journey_id = $2 AND sample_id = $3 AND status NOT IN ('completed','delivered','cancelled')`,
					req.TargetJourneyID, src, sid)
			}
			_, _ = tx.ExecContext(ctx, `UPDATE journeys SET active = FALSE, status = 'replaced' WHERE journey_id = $1`, src)
		}
		_, _ = tx.ExecContext(ctx, `UPDATE journeys SET route_mode = 'batched' WHERE journey_id = $1`, req.TargetJourneyID)
		return nil
	})
	if err != nil {
		writeAPIError(w, err)
		return
	}
	st.audit(ctx, sess, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]any{"sources": req.SourceJourneyIDs})
	out := map[string]any{"journeyId": req.TargetJourneyID, "planVersion": newVersion}
	if req.IdempotencyKey != "" {
		st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "merge", hashRequest("merge", req.TargetJourneyID, itoa(req.ExpectedPlanVersion)), http.StatusOK, out)
	}
	writeData(w, http.StatusOK, out)
}

func (st *Store) validateMerge(ctx context.Context, target string, sources []string) error {
	type meta struct {
		typeID, container string
		cooled, batch     bool
		incompat          []string
	}
	load := func(jid string) []meta {
		rows, err := st.PG.QueryContext(ctx, `
			SELECT s.sample_type_id, st.container_type, st.requires_cooled_route, st.batching_allowed
			FROM journey_samples js
			JOIN samples s ON s.sample_id = js.sample_id
			JOIN sample_types st ON st.sample_type_id = s.sample_type_id
			WHERE js.journey_id = $1`, jid)
		if err != nil {
			return nil
		}
		defer rows.Close()
		var out []meta
		for rows.Next() {
			var m meta
			if err := rows.Scan(&m.typeID, &m.container, &m.cooled, &m.batch); err == nil {
				m.incompat, _ = st.loadIncompat(ctx, m.typeID)
				out = append(out, m)
			}
		}
		return out
	}
	all := load(target)
	for _, s := range sources {
		all = append(all, load(s)...)
	}
	for i := 0; i < len(all); i++ {
		if !all[i].batch {
			return errJSON("incompatible_batch", "incompatible batch", http.StatusConflict)
		}
		for j := i + 1; j < len(all); j++ {
			if all[i].container != all[j].container {
				return errJSON("incompatible_container", "incompatible container", http.StatusConflict)
			}
			if all[i].cooled != all[j].cooled {
				return errJSON("incompatible_temperature", "incompatible temperature", http.StatusConflict)
			}
			if containsStr(all[i].incompat, all[j].typeID) || containsStr(all[j].incompat, all[i].typeID) {
				return errJSON("incompatible_sample_types", "incompatible sample types", http.StatusConflict)
			}
		}
	}
	return nil
}

