func (st *Store) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireActiveRole(); err != nil {
		writeAPIError(w, err)
		return
	}
	role := sess.ActiveRole
	statusFilter := ""
	if r.Method == http.MethodPost && r.ContentLength > 0 {
		var body struct {
			Role   string `json:"role"`
			Status string `json:"status"`
		}
		if err := decodeJSON(r, &body); err != nil {
			writeAPIError(w, err)
			return
		}
		if body.Role != "" {
			if !sess.hasRole(body.Role) && !isAdminOrDispatcher(sess.ActiveRole) {
				writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
				return
			}
			if !validRole(body.Role) {
				writeErr(w, http.StatusBadRequest, "invalid_role", "invalid role")
				return
			}
			role = body.Role
		}
		statusFilter = body.Status
	}
	if q := r.URL.Query().Get("role"); q != "" {
		role = q
	}
	if q := r.URL.Query().Get("status"); q != "" {
		statusFilter = q
	}
	st.expireOffers(r.Context())
	items, err := st.listWork(r.Context(), sess, role, statusFilter)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	writeData(w, http.StatusOK, map[string]any{
		"role":  role,
		"items": items,
	})
}

func (st *Store) listWork(ctx context.Context, sess *Session, role, statusFilter string) ([]map[string]any, error) {
	now := time.Now().UTC()
	items := []map[string]any{}

	if role == RoleRequester {
		rows, err := st.PG.QueryContext(ctx, `
			SELECT s.sample_id, s.request_id, s.status, s.serviceability, s.target_laboratory_id,
			       r.requested_at, r.delivery_deadline, r.origin_lat, r.origin_lng
			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
			WHERE s.requester_id = $1
			ORDER BY r.created_at DESC`, sess.UserID)
		if err != nil {
			return nil, err
		}
		defer rows.Close()
		for rows.Next() {
			var sid, rid, status, svc string
			var lab sql.NullString
			var requested, deadline time.Time
			var lat, lng float64
			if err := rows.Scan(&sid, &rid, &status, &svc, &lab, &requested, &deadline, &lat, &lng); err != nil {
				continue
			}
			if !matchStatus(statusFilter, status, isTerminal(status)) {
				continue
			}
			tl, _ := st.loadTimelineForSample(ctx, sid)
			items = append(items, map[string]any{
				"kind":             "request",
				"sampleId":         sid,
				"requestId":        rid,
				"status":           status,
				"serviceability":   svc,
				"targetLaboratoryId": nullStr(lab),
				"requestedAt":      formatTime(requested),
				"deliveryDeadline": formatTime(deadline),
				"origin":           Coordinate{Latitude: lat, Longitude: lng},
				"timeline":         tl,
				"current":          !isTerminal(status),
			})
		}
		return items, nil
	}

	if isAdminOrDispatcher(role) {
		rows, err := st.PG.QueryContext(ctx, `
			SELECT a.assignment_id, a.sample_id, a.journey_id, a.kind, a.status, a.from_location_id, a.to_location_id,
			       a.worker_id, a.offered_worker_id, a.sequence, s.status
			FROM assignments a JOIN samples s ON s.sample_id = a.sample_id
			ORDER BY a.created_at DESC LIMIT 500`)
		if err != nil {
			return nil, err
		}
		defer rows.Close()
		for rows.Next() {
			item, ok := scanWorkItem(rows, statusFilter)
			if ok {
				sid, _ := item["sampleId"].(string)
				tl, _ := st.loadTimelineForSample(ctx, sid)
				item["timeline"] = tl
				items = append(items, item)
			}
		}
		return items, nil
	}

	rows, err := st.PG.QueryContext(ctx, `
		SELECT a.assignment_id, a.sample_id, a.journey_id, a.kind, a.status, a.from_location_id, a.to_location_id,
		       a.worker_id, a.offered_worker_id, a.sequence, s.status
		FROM assignments a JOIN samples s ON s.sample_id = a.sample_id
		WHERE a.worker_id = $1 OR a.offered_worker_id = $1
		ORDER BY a.created_at DESC`, sess.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		item, ok := scanWorkItem(rows, statusFilter)
		if !ok {
			continue
		}
		// collection professionals only see collection work they are qualified for
		if role == RoleCollection {
			kind, _ := item["kind"].(string)
			if kind != KindCollection && kind != KindNode {
				// they can also see handoff-related transport they hold
				if kind != KindTransport {
					continue
				}
			}
		}
		if role == RoleDelivery {
			kind, _ := item["kind"].(string)
			if kind != KindTransport {
				continue
			}
		}
		if role == RoleNode {
			kind, _ := item["kind"].(string)
			if kind != KindNode && kind != KindTransport && kind != KindCollection {
				continue
			}
		}
		if role == RoleLab {
			kind, _ := item["kind"].(string)
			if kind != KindLaboratory {
				continue
			}
		}
		sid, _ := item["sampleId"].(string)
		tl, _ := st.loadTimelineForSample(ctx, sid)
		item["timeline"] = tl
		_ = now
		items = append(items, item)
	}
	return items, nil
}

func scanWorkItem(rows *sql.Rows, statusFilter string) (map[string]any, bool) {
	var aid, sid, jid, kind, astatus, sstatus string
	var from, to, worker, offered sql.NullString
	var seq int
	if err := rows.Scan(&aid, &sid, &jid, &kind, &astatus, &from, &to, &worker, &offered, &seq, &sstatus); err != nil {
		return nil, false
	}
	terminal := astatus == AssignCompleted || astatus == AssignCancelled || astatus == AssignDelivered
	if !matchStatus(statusFilter, astatus, terminal) {
		return nil, false
	}
	item := map[string]any{
		"kind":         kind,
		"assignmentId": aid,
		"sampleId":     sid,
		"journeyId":    jid,
		"status":       astatus,
		"sequence":     seq,
		"sampleStatus": sstatus,
		"current":      !terminal,
	}
	if from.Valid {
		item["fromLocationId"] = from.String
	}
	if to.Valid {
		item["toLocationId"] = to.String
	}
	if worker.Valid {
		item["workerId"] = worker.String
	} else if offered.Valid {
		item["offeredWorkerId"] = offered.String
	}
	return item, true
}

func matchStatus(filter, status string, terminal bool) bool {
	if filter == "" {
		return true
	}
	switch filter {
	case "current":
		return !terminal
	case "past", "completed":
		return terminal
	default:
		return status == filter
	}
}

func isTerminal(status string) bool {
	switch status {
	case SampleReceived, SampleCancelled, SampleExpired:
		return true
	}
	return false
}

func (st *Store) handleReadOperations(w http.ResponseWriter, r *http.Request) {
	sess := sessionFrom(r.Context())
	if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
		writeAPIError(w, err)
		return
	}
	filters := ""
	if r.Method == http.MethodPost && r.ContentLength > 0 {
		var body struct {
			Filters string `json:"filters"`
		}
		if err := decodeJSON(r, &body); err != nil {
			writeAPIError(w, err)
			return
		}
		filters = body.Filters
	}
	data, err := st.buildOperationsState(r.Context(), filters)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
		return
	}
	writeData(w, http.StatusOK, data)
}

func (st *Store) buildOperationsState(ctx context.Context, filters string) (map[string]any, error) {
	now := time.Now().UTC()
	st.expireOffers(ctx)

	samples := []map[string]any{}
	srows, err := st.PG.QueryContext(ctx, `
		SELECT s.sample_id, s.request_id, s.status, s.current_holder_id, s.latest_lat, s.latest_lng,
		       s.location_recorded_at, s.sealed, s.serviceability, s.target_laboratory_id, s.exception,
		       st.name
		FROM samples s JOIN sample_types st ON st.sample_type_id = s.sample_type_id
		ORDER BY s.created_at DESC LIMIT 500`)
	if err != nil {
		return nil, err
	}
	for srows.Next() {
		var sid, rid, status, svc, typeName string
		var holder, target sql.NullString
		var lat, lng sql.NullFloat64
		var locAt sql.NullTime
		var sealed bool
		var exc []byte
		if err := srows.Scan(&sid, &rid, &status, &holder, &lat, &lng, &locAt, &sealed, &svc, &target, &exc, &typeName); err != nil {
			continue
		}
		var rec *time.Time
		if locAt.Valid {
			rec = &locAt.Time
		}
		var coord any
		if lat.Valid && lng.Valid {
			coord = Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
		}
		samples = append(samples, map[string]any{
			"sampleId":           sid,
			"requestId":          rid,
			"status":             status,
			"currentHolderId":    nullStr(holder),
			"latestCoordinate":   coord,
			"locationRecordedAt": formatTimePtr(rec),
			"locationStale":      isLocationStale(rec, now),
			"sealed":             sealed,
			"serviceability":     svc,
			"targetLaboratoryId": nullStr(target),
			"sampleTypeName":     typeName,
		})
	}
	srows.Close()

	workers := []map[string]any{}
	wrows, err := st.PG.QueryContext(ctx, `
		SELECT u.user_id, u.username, u.full_name, u.available, u.capacity_units,
		       u.latest_lat, u.latest_lng, u.location_recorded_at, u.assigned_location_id
		FROM users u
		WHERE EXISTS (
		  SELECT 1 FROM user_roles ur WHERE ur.user_id = u.user_id
		    AND ur.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team')
		)`)
	if err == nil {
		defer wrows.Close()
		for wrows.Next() {
			var uid, uname, fname string
			var avail bool
			var cap int
			var lat, lng sql.NullFloat64
			var locAt sql.NullTime
			var assigned sql.NullString
			if err := wrows.Scan(&uid, &uname, &fname, &avail, &cap, &lat, &lng, &locAt, &assigned); err != nil {
				continue
			}
			roles, _ := st.loadRoles(ctx, uid)
			var rec *time.Time
			if locAt.Valid {
				rec = &locAt.Time
			}
			var coord any
			if lat.Valid && lng.Valid {
				coord = Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
			}
			open := 0
			_ = st.PG.QueryRowContext(ctx, `
				SELECT COUNT(*) FROM assignments
				WHERE (worker_id = $1 OR offered_worker_id = $1)
				  AND status IN ('offered','accepted','in_progress','pending','at_pickup','picked_up','in_transit','arrived')`, uid).Scan(&open)
			workers = append(workers, map[string]any{
				"userId":             uid,
				"username":           uname,
				"fullName":           fname,
				"roles":              roles,
				"available":          avail,
				"capacityUnits":      cap,
				"openAssignments":    open,
				"latestCoordinate":   coord,
				"locationRecordedAt": formatTimePtr(rec),
				"locationStale":      isLocationStale(rec, now),
				"assignedLocationId": nullStr(assigned),
			})
		}
	}

	locations := []map[string]any{}
	lrows, err := st.PG.QueryContext(ctx, `
		SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active,
		       fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory
		FROM locations`)
	if err == nil {
		defer lrows.Close()
		for lrows.Next() {
			var id, name string
			var lat, lng, cov float64
			var handling int
			var active bool
			var f LocationFunctions
			if err := lrows.Scan(&id, &name, &lat, &lng, &cov, &handling, &active, &f.CollectionPoint, &f.TransferPoint, &f.Hub, &f.Laboratory); err != nil {
				continue
			}
			cap := st.getCapacity(ctx, id)
			locations = append(locations, map[string]any{
				"locationId":      id,
				"name":            name,
				"coordinate":      Coordinate{Latitude: lat, Longitude: lng},
				"coverageKm":      cov,
				"handlingMinutes": handling,
				"active":          active,
				"functions":       f,
				"capacity":        cap,
			})
		}
	}

	connections := []map[string]any{}
	crows, err := st.PG.QueryContext(ctx, `
		SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active
		FROM connections`)
	if err == nil {
		defer crows.Close()
		for crows.Next() {
			var id, from, to string
			var minutes int
			var cost float64
			var cooled, active bool
			if err := crows.Scan(&id, &from, &to, &minutes, &cost, &cooled, &active); err != nil {
				continue
			}
			cap := st.getCapacity(ctx, id)
			connections = append(connections, map[string]any{
				"connectionId":   id,
				"fromLocationId": from,
				"toLocationId":   to,
				"travelMinutes":  minutes,
				"costUnits":      cost,
				"cooled":         cooled,
				"active":         active,
				"capacity":       cap,
			})
		}
	}

	exceptions := []map[string]any{}
	erows, err := st.PG.QueryContext(ctx, `
		SELECT sample_id, status, exception FROM samples
		WHERE status IN ('exception','expired','unserviceable') OR exception IS NOT NULL
		ORDER BY created_at DESC LIMIT 200`)
	if err == nil {
		defer erows.Close()
		for erows.Next() {
			var sid, status string
			var exc []byte
			if err := erows.Scan(&sid, &status, &exc); err != nil {
				continue
			}
			item := map[string]any{"sampleId": sid, "status": status}
			if len(exc) > 0 {
				item["exception"] = jsonRaw(exc)
			}
			exceptions = append(exceptions, item)
		}
	}

	journeys := []map[string]any{}
	jrows, err := st.PG.QueryContext(ctx, `
		SELECT journey_id, plan_version, route_mode, status, estimated_delivery_at, valid, replan_status
		FROM journeys WHERE active = TRUE ORDER BY created_at DESC LIMIT 200`)
	if err == nil {
		defer jrows.Close()
		for jrows.Next() {
			var jid, mode, status string
			var version int
			var eta sql.NullTime
			var valid bool
			var replan sql.NullString
			if err := jrows.Scan(&jid, &version, &mode, &status, &eta, &valid, &replan); err != nil {
				continue
			}
			sids, _ := st.journeySampleIDs(ctx, jid)
			item := map[string]any{
				"journeyId":   jid,
				"planVersion": version,
				"routeMode":   mode,
				"status":      status,
				"valid":       valid,
				"sampleIds":   sids,
			}
			if eta.Valid {
				item["estimatedDeliveryAt"] = formatTime(eta.Time)
			}
			if replan.Valid && replan.String != "" {
				item["replanStatus"] = replan.String
			}
			journeys = append(journeys, item)
		}
	}

	return map[string]any{
		"samples":     samples,
		"workers":     workers,
		"locations":   locations,
		"connections": connections,
		"exceptions":  exceptions,
		"journeys":    journeys,
		"filters":     filters,
		"generatedAt": formatTime(now),
	}, nil
}

func jsonRaw(b []byte) any {
	if len(b) == 0 || string(b) == "null" {
		return nil
	}
	var v any
	if err := json.Unmarshal(b, &v); err != nil {
		return string(b)
	}
	return v
}

