:root {
  color-scheme: light;
  --bg: #f4f1ea;
  --panel: #fffdf8;
  --ink: #1c2430;
  --muted: #5c6775;
  --line: #d7d0c3;
  --accent: #0b6e4f;
  --accent-ink: #fff;
  --warn: #9a3412;
  --danger: #9f1239;
  --ok: #166534;
  --stale: #b45309;
  font-family: "Source Sans 3", "Segoe UI", system-ui, sans-serif;
}

* { box-sizing: border-box; }
html, body, #root { margin: 0; min-height: 100%; background: var(--bg); color: var(--ink); }

button, input, select, textarea {
  font: inherit;
}

h1, h2, h3 { font-weight: 650; letter-spacing: -0.02em; }

.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  padding: 0.85rem 1.25rem;
  background: #16302b;
  color: #f4f1ea;
}
.app-header h1 { margin: 0; font-size: 1.15rem; }
.app-header nav { display: flex; flex-wrap: wrap; gap: 0.4rem; }
.app-header nav button,
.ghost {
  background: transparent;
  color: inherit;
  border: 1px solid #3d5c54;
  border-radius: 999px;
  padding: 0.3rem 0.75rem;
  cursor: pointer;
}
.app-header nav button.active,
.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
  border-radius: 999px;
  padding: 0.4rem 0.9rem;
  cursor: pointer;
}
.danger { background: var(--danger); color: white; border: 0; border-radius: 8px; padding: 0.4rem 0.8rem; cursor: pointer; }

.layout { display: grid; grid-template-columns: minmax(0, 1fr); gap: 1rem; padding: 1rem; }
@media (min-width: 960px) {
  .split { display: grid; grid-template-columns: 1.1fr 0.9fr; gap: 1rem; }
}

.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 1rem 1.1rem;
  box-shadow: 0 1px 0 rgba(0,0,0,0.04);
}
.card h2 { margin: 0 0 0.75rem; font-size: 1.05rem; }

.form-grid { display: grid; gap: 0.65rem; }
label { display: grid; gap: 0.2rem; font-size: 0.92rem; }
label span { color: var(--muted); }
input, select, textarea {
