     8		"time"
     9	)
    10	
    11	type apiError struct {
    12		status int
    13		code   string
    14		msg    string
    15	}
    16	
    17	func (e *apiError) Error() string { return e.code + ": " + e.msg }
    18	
    19	func errJSON(code, msg string, status int) *apiError {
    20		return &apiError{status: status, code: code, msg: msg}
    21	}
    22	
    23	func writeJSON(w http.ResponseWriter, status int, v any) {
    24		w.Header().Set("Content-Type", "application/json")
    25		w.WriteHeader(status)
    26		_ = json.NewEncoder(w).Encode(v)
    27	}
    28	
    29	func writeData(w http.ResponseWriter, status int, data any) {
    30		writeJSON(w, status, map[string]any{"data": data})
    31	}
    32	
    33	func writeErr(w http.ResponseWriter, status int, code, msg string) {
    34		writeJSON(w, status, map[string]string{"error": msg, "code": code})
    35	}
    36	
    37	func writeAPIError(w http.ResponseWriter, err error) {
    38		if e, ok := err.(*apiError); ok {
    39			writeErr(w, e.status, e.code, e.msg)
    40			return
    41		}
    42		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
    43	}
    44	
    45	func decodeJSON(r *http.Request, dest any) error {
    46		body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
    47		if err != nil {
    48			return errJSON("invalid_json", "invalid json", http.StatusBadRequest)
    49		}
    50		if len(strings.TrimSpace(string(body))) == 0 {
    51			return errJSON("invalid_json", "invalid json", http.StatusBadRequest)
    52		}
    53		if err := json.Unmarshal(body, dest); err != nil {
    54			return errJSON("invalid_json", "invalid json", http.StatusBadRequest)
    55		}
    56		return nil
    57	}
    58	
    59	func parseTime(s string, code string) (time.Time, error) {
    60		if s == "" {
    61			return time.Time{}, errJSON(code, "invalid time", http.StatusBadRequest)
    62		}
    63		formats := []string{
    64			time.RFC3339Nano,
    65			time.RFC3339,
    66			"2006-01-02T15:04:05Z07:00",
    67			"2006-01-02T15:04:05.000Z07:00",
    68		}
    69		for _, f := range formats {
    70			if t, err := time.Parse(f, s); err == nil {
    71				return t, nil
    72			}
    73		}
    74		return time.Time{}, errJSON(code, "invalid time", http.StatusBadRequest)
    75	}
