    13		"golang.org/x/crypto/bcrypt"
    14	)
    15	
    16	type Session struct {
    17		Token      string
    18		UserID     string
    19		Username   string
    20		FullName   string
    21		ActiveRole string
    22		Roles      []string
    23		Active     bool
    24		AssignedLoc sql.NullString
    25	}
    26	
    27	type ctxKey int
    28	
    29	const sessionKey ctxKey = 1
    30	
    31	func sessionFrom(ctx context.Context) *Session {
    32		s, _ := ctx.Value(sessionKey).(*Session)
    33		return s
    34	}
    35	
    36	func hashPassword(pw string) (string, error) {
    37		b, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
    38		return string(b), err
    39	}
    40	
    41	func checkPassword(hash, pw string) bool {
    42		return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
    43	}
    44	
    45	func newToken() string {
    46		b := make([]byte, 32)
    47		_, _ = rand.Read(b)
    48		return hex.EncodeToString(b)
    49	}
    50	
    51	func hashIdem(s string) string {
    52		sum := sha256.Sum256([]byte(s))
    53		return hex.EncodeToString(sum[:])
    54	}
    55	
    56	func (st *Store) loadRoles(ctx context.Context, userID string) ([]string, error) {
    57		rows, err := st.PG.QueryContext(ctx, `SELECT role FROM user_roles WHERE user_id = $1 ORDER BY role`, userID)
    58		if err != nil {
    59			return nil, err
    60		}
    61		return scanStrings(rows)
    62	}
    63	
    64	func (st *Store) loadSession(ctx context.Context, token string) (*Session, error) {
    65		var s Session
    66		s.Token = token
    67		err := st.PG.QueryRowContext(ctx, `
    68			SELECT u.user_id, u.username, u.full_name, u.active, s.active_role, u.assigned_location_id
    69			FROM sessions s JOIN users u ON u.user_id = s.user_id
    70			WHERE s.token = $1`, token).Scan(&s.UserID, &s.Username, &s.FullName, &s.Active, &s.ActiveRole, &s.AssignedLoc)
    71		if err == sql.ErrNoRows {
    72			return nil, errJSON("unauthorized", "unauthorized", http.StatusUnauthorized)
