    89	func (st *Store) authMiddleware(next http.Handler) http.Handler {
    90		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    91			header := r.Header.Get("Authorization")
    92			token := ""
    93			if strings.HasPrefix(strings.ToLower(header), "bearer ") {
