 'record_worker_location','update_assignment_progress','initiate_handoff','confirm_handoff',
 'record_handling_checkpoint','confirm_laboratory_receipt','record_laboratory_exception',
 'set_worker_availability','read_journey_plan','edit_active_plan','split_journey','merge_journeys',
 'cancel_journey','reroute_journey','report_disruption','read_operations_state','search_audit_trail',
 'read_ui_bootstrap','stream_realtime_events','system_readiness'
]
ops = {}
for path, methods in spec['paths'].items():
    for m, op in methods.items():
        if m.startswith('x-'): continue
        oid = op.get('operationId')
        ops[oid] = (m, path, op)

def summarize_schema(s, indent=0):
    if not s: return ''
    if '$ref' in s: return s['$ref'].split('/')[-1]
    t = s.get('type')
    if t=='object':
        props = s.get('properties',{})
        req = set(s.get('required',[]))
        parts=[]
        for k,v in props.items():
            mark='*' if k in req else ''
            parts.append(f"{k}{mark}:{summarize_schema(v)}")
        addl = s.get('additionalProperties')
        if addl is True:
            parts.append('...open')
        elif isinstance(addl, dict):
            parts.append('...'+summarize_schema(addl))
        return '{'+', '.join(parts)+'}'
    if t=='array':
        return '['+summarize_schema(s.get('items',{}))+']'
    if 'enum' in s:
        return '|'.join(str(x) for x in s['enum'])
    if t: return t
    if 'allOf' in s:
        return '+'.join(summarize_schema(x) for x in s['allOf'])
    if 'oneOf' in s:
        return 'oneOf('+','.join(summarize_schema(x) for x in s['oneOf'])+')'
    return '?'

for oid in keys:
    if oid not in ops:
        print('MISSING', oid)
        continue
    m, path, op = ops[oid]
    rb = op.get('requestBody',{})
    content = rb.get('content',{}).get('application/json',{})
    schema = content.get('schema')
    print(f'\n=== {oid} {m.upper()} {path} ===')
    if schema:
        print('  REQ', summarize_schema(schema)[:800])
    for code, resp in op.get('responses',{}).items():
        if not str(code).startswith('2'): continue
        c = resp.get('content',{}).get('application/json',{})
        print(f'  {code}', summarize_schema(c.get('schema'))[:800] if c.get('schema') else resp.get('description','')[:80])
    params = op.get('parameters')
    if params:
        print('  PARAMS', [(p.get('name'), p.get('in'), p.get('required')) for p in params])

print('\n\n=== SCHEMAS ===')
for name, sch in spec['components']['schemas'].items():
    print(f'\n{name}: {summarize_schema(sch)[:900]}')
