   171	func bearerFromWS(r *http.Request, protocols []string) string {
   172		if h := r.Header.Get("Authorization"); strings.HasPrefix(strings.ToLower(h), "bearer ") {
   173			return strings.TrimSpace(h[7:])
   174		}
   175		for _, p := range protocols {
   176			if strings.HasPrefix(p, "bearer.") {
   177				// base64url-encoded bearer.<token> — the token after the prefix may itself be the session token
   178				// Spec: "A bearer [REDACTED] is sent as a base64url-encoded bearer.<token> WebSocket subprotocol."
   179				rest := strings.TrimPrefix(p, "bearer.")
   180				if decoded, err := decodeB64URL(rest); err == nil && decoded != "" {
   181					return decoded
   182				}
   183				return rest
   184			}
   185		}
   186		if q := r.URL.Query().Get("token"); q != "" {
   187			return q
   188		}
   189		return ""
   190	}
   191	
   192	func decodeB64URL(s string) (string, error) {
   193		s = strings.TrimSpace(s)
   194		if m := len(s) % 4; m != 0 {
   195			s += strings.Repeat("=", 4-m)
   196		}
   197		b, err := b64URLDecode(s)
   198		if err != nil {
   199			return "", err
   200		}
   201		return string(b), nil
   202	}
