   478			eta := time.Now().Add(time.Duration(route.TotalMinutes) * time.Minute)
   479			_, _ = tx.ExecContext(ctx, `
   480				UPDATE journeys SET estimated_delivery_at = $1, total_cost_units = $2, replan_status = 'completed', valid = TRUE, status = 'active'
