    61			if err != nil {
    62				writeAPIError(w, err)
    63				return
    64			}
    65			if hit {
    66				replayIdempotent(w, status, body)
    67				return
    68			}
    69		}
    70		if !validCoord(req.Origin) {
    71			writeErr(w, http.StatusBadRequest, "invalid_origin", "invalid origin")
    72			return
    73		}
    74		if req.OriginType == "" {
    75			if presealed {
    76				req.OriginType = OriginClinic
    77			} else {
    78				req.OriginType = OriginHome
    79			}
    80		}
    81		if req.OriginType != OriginHome && req.OriginType != OriginClinic && req.OriginType != OriginNode {
    82			writeErr(w, http.StatusBadRequest, "invalid_origin_type", "invalid origin type")
    83			return
    84		}
    85		if presealed && req.OriginType == OriginHome {
    86			writeErr(w, http.StatusBadRequest, "invalid_origin_type", "pre-sealed samples cannot originate at a home")
    87			return
    88		}
    89		requestedAt, err := parseTime(req.RequestedAt, "invalid_time")
    90		if err != nil {
    91			writeAPIError(w, err)
    92			return
    93		}
    94		deadline, err := parseTime(req.DeliveryDeadline, "invalid_deadline")
    95		if err != nil {
    96			writeAPIError(w, err)
    97			return
    98		}
    99		if !deadline.After(requestedAt) {
   100			writeErr(w, http.StatusBadRequest, "invalid_deadline", "invalid deadline")
   101			return
   102		}
   103		earliest := requestedAt
   104		if req.EarliestCollectionAt != "" {
   105			earliest, err = parseTime(req.EarliestCollectionAt, "invalid_collection_window")
   106			if err != nil {
