   376	func (st *Store) listRequesterSamples(ctx context.Context, requesterID string) ([]map[string]any, error) {
   377		rows, err := st.PG.QueryContext(ctx, `
   378			SELECT s.sample_id, s.request_id, s.status, s.serviceability, s.target_laboratory_id,
   379			       r.requested_at, r.delivery_deadline
   380			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
   381			WHERE s.requester_id = $1
   382			ORDER BY r.created_at DESC`, requesterID)
   383		if err != nil {
   384			return nil, err
   385		}
   386		defer rows.Close()
   387		out := []map[string]any{}
   388		for rows.Next() {
   389			var sampleID, requestID, status, svc string
   390			var lab sql.NullString
   391			var requested, deadline time.Time
   392			if err := rows.Scan(&sampleID, &requestID, &status, &svc, &lab, &requested, &deadline); err != nil {
   393				continue
   394			}
   395			out = append(out, map[string]any{
   396				"sampleId":            sampleID,
   397				"requestId":           requestID,
   398				"status":              status,
   399				"serviceability":      svc,
   400				"targetLaboratoryId":  nullStr(lab),
   401				"requestedAt":         formatTime(requested),
   402				"deliveryDeadline":    formatTime(deadline),
   403			})
   404		}
   405		return out, nil
   406	}
