   306	func (st *Store) userPayload(ctx context.Context, userID string) (map[string]any, error) {
   307		var username, email, fullName, phone string
   308		var active bool
   309		err := st.PG.QueryRowContext(ctx, `
   310			SELECT username, email, full_name, phone, active FROM users WHERE user_id = $1`, userID).
   311			Scan(&username, &email, &fullName, &phone, &active)
   312		if err != nil {
   313			return nil, err
   314		}
   315		roles, _ := st.loadRoles(ctx, userID)
   316		quals := []string{}
   317		rows, err := st.PG.QueryContext(ctx, `SELECT qualification FROM user_qualifications WHERE user_id = $1`, userID)
   318		if err == nil {
   319			quals, _ = scanStrings(rows)
   320		}
   321		certs := []Certification{}
   322		crows, err := st.PG.QueryContext(ctx, `SELECT code, active, expires_at FROM user_certifications WHERE user_id = $1`, userID)
   323		if err == nil {
   324			defer crows.Close()
   325			for crows.Next() {
   326				var c Certification
   327				var exp sql.NullTime
   328				if err := crows.Scan(&c.Code, &c.Active, &exp); err == nil {
   329					if exp.Valid {
   330						s := formatTime(exp.Time)
   331						c.ExpiresAt = &s
   332					}
   333					certs = append(certs, c)
   334				}
   335			}
   336		}
   337		return map[string]any{
   338			"userId":         userID,
   339			"username":       username,
   340			"email":          email,
   341			"fullName":       fullName,
   342			"phone":          phone,
   343			"roles":          roles,
   344			"qualifications": quals,
   345			"certifications": certs,
   346			"active":         active,
   347		}, nil
   348	}
