   371	func (st *Store) canSeeSample(ctx context.Context, sess *Session, sampleID string) bool {
   372		if isAdminOrDispatcher(sess.ActiveRole) {
   373			return true
   374		}
   375		var requester, holder sql.NullString
   376		err := st.PG.QueryRowContext(ctx, `SELECT requester_id, current_holder_id FROM samples WHERE sample_id = $1`, sampleID).Scan(&requester, &holder)
   377		if err != nil {
   378			return false
   379		}
   380		if sess.ActiveRole == RoleRequester && requester.Valid && requester.String == sess.UserID {
   381			return true
   382		}
   383		if holder.Valid && holder.String == sess.UserID {
   384			return true
   385		}
   386		var n int
   387		_ = st.PG.QueryRowContext(ctx, `
   388			SELECT COUNT(*) FROM assignments
   389			WHERE sample_id = $1 AND (worker_id = $2 OR offered_worker_id = $2)`, sampleID, sess.UserID).Scan(&n)
   390		return n > 0
   391	}
