   403			       latest_lat, latest_lng, location_recorded_at, exception
   404			FROM samples WHERE sample_id = $1`, sampleID).
   405			Scan(&requestID, &requesterID, &typeID, &status, &sealed, &sealedAt, &holder, &target, &recvLab, &recvAt,
   406				&svc, &svcReason, &lat, &lng, &locAt, &exc)
   407		if err == sql.ErrNoRows {
