   157	func (st *Store) handleSearchAudit(w http.ResponseWriter, r *http.Request) {
   158		sess := sessionFrom(r.Context())
   159		if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
   160			writeAPIError(w, err)
   161			return
   162		}
   163		var req struct {
   164			Query      string `json:"query"`
   165			ActorID    string `json:"actorId"`
   166			EntityType string `json:"entityType"`
   167			EntityID   string `json:"entityId"`
   168			Action     string `json:"action"`
   169			Role       string `json:"role"`
   170			Success    *bool  `json:"success"`
   171			FromTime   string `json:"fromTime"`
   172			ToTime     string `json:"toTime"`
   173			Limit      int    `json:"limit"`
   174			Offset     int    `json:"offset"`
   175			Order      string `json:"order"`
   176		}
   177		if r.Body != nil && r.ContentLength != 0 {
   178			if err := decodeJSON(r, &req); err != nil {
   179				writeAPIError(w, err)
   180				return
   181			}
   182		}
   183		if req.Limit == 0 {
   184			req.Limit = 500
   185		}
   186		if req.Limit < 1 || req.Limit > 5000 {
   187			writeErr(w, http.StatusBadRequest, "invalid_limit", "invalid limit")
   188			return
   189		}
   190		if req.Offset < 0 {
   191			writeErr(w, http.StatusBadRequest, "invalid_offset", "invalid offset")
   192			return
   193		}
   194		if req.Order == "" {
   195			req.Order = "newest_first"
   196		}
   197		if req.Order != "newest_first" && req.Order != "oldest_first" {
   198			writeErr(w, http.StatusBadRequest, "invalid_order", "invalid order")
   199			return
   200		}
   201		filter := bson.M{}
   202		if req.ActorID != "" {
   203			filter["actorId"] = req.ActorID
   204		}
   205		if req.EntityType != "" {
   206			filter["entityType"] = req.EntityType
   207		}
   208		if req.EntityID != "" {
   209			filter["entityId"] = req.EntityID
   210		}
   211		if req.Action != "" {
   212			filter["action"] = req.Action
   213		}
   214		if req.Role != "" {
   215			filter["role"] = req.Role
   216		}
   217		if req.Success != nil {
   218			filter["success"] = *req.Success
   219		}
   220		timeFilter := bson.M{}
   221		if req.FromTime != "" {
   222			t, err := parseTime(req.FromTime, "invalid_time")
   223			if err != nil {
   224				writeAPIError(w, err)
   225				return
   226			}
   227			timeFilter["$gte"] = t
   228		}
   229		if req.ToTime != "" {
   230			t, err := parseTime(req.ToTime, "invalid_time")
   231			if err != nil {
   232				writeAPIError(w, err)
   233				return
   234			}
   235			timeFilter["$lte"] = t
   236		}
   237		if len(timeFilter) > 0 {
   238			filter["occurredAt"] = timeFilter
   239		}
   240		if strings.TrimSpace(req.Query) != "" {
   241			filter["$or"] = []bson.M{
   242				{"action": bson.M{"$regex": req.Query, "$options": "i"}},
   243				{"entityType": bson.M{"$regex": req.Query, "$options": "i"}},
   244				{"entityId": bson.M{"$regex": req.Query, "$options": "i"}},
   245				{"role": bson.M{"$regex": req.Query, "$options": "i"}},
   246				{"actorId": bson.M{"$regex": req.Query, "$options": "i"}},
   247			}
   248		}
   249		ctx := r.Context()
   250		total, err := st.Audit.CountDocuments(ctx, filter)
   251		if err != nil {
   252			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   253			return
   254		}
   255		sort := bson.D{{Key: "occurredAt", Value: -1}, {Key: "auditId", Value: -1}}
   256		if req.Order == "oldest_first" {
   257			sort = bson.D{{Key: "occurredAt", Value: 1}, {Key: "auditId", Value: 1}}
   258		}
   259		opts := options.Find().SetSort(sort).SetSkip(int64(req.Offset)).SetLimit(int64(req.Limit))
   260		cur, err := st.Audit.Find(ctx, filter, opts)
   261		if err != nil {
   262			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   263			return
   264		}
   265		defer cur.Close(ctx)
   266		entries := []map[string]any{}
   267		for cur.Next(ctx) {
   268			var d AuditDoc
   269			if err := cur.Decode(&d); err != nil {
   270				continue
   271			}
   272			if d.Details == nil {
   273				d.Details = map[string]any{}
   274			}
   275			occurred := d.OccurredAt
   276			if occurred.IsZero() {
   277				occurred = d.OccurredAt2
   278			}
   279			iso := formatTime(occurred)
   280			entries = append(entries, map[string]any{
   281				"auditId":     d.AuditID,
   282				"audit_id":    d.AuditID,
   283				"actorId":     d.ActorID,
   284				"actor_id":    d.ActorID,
   285				"role":        d.Role,
   286				"actorRole":   defaultIfEmpty(d.ActorRole, d.Role),
   287				"action":      d.Action,
   288				"entityType":  d.EntityType,
   289				"entity_type": d.EntityType,
   290				"entityId":    d.EntityID,
   291				"entity_id":   d.EntityID,
   292				"success":     d.Success,
   293				"occurredAt":  iso,
   294				"occurred_at": iso,
   295				"details":     d.Details,
   296			})
   297		}
   298		returned := len(entries)
   299		hasMore := int64(req.Offset+returned) < total
   300		var nextOffset any
   301		if hasMore {
   302			nextOffset = req.Offset + returned
   303		}
   304		result := map[string]any{
   305			"entries":    entries,
   306			"total":      total,
   307			"returned":   returned,
   308			"offset":     req.Offset,
   309			"limit":      req.Limit,
   310			"order":      req.Order,
   311			"hasMore":    hasMore,
   312			"nextOffset": nextOffset,
   313		}
   314		st.audit(ctx, sess, "search_audit_trail", "audit", "", true, map[string]any{"query": req.Query})
   315		writeData(w, http.StatusOK, result)
   316	}
