    59	func (st *Store) listWork(ctx context.Context, sess *Session, role, statusFilter string) ([]map[string]any, error) {
    60		now := time.Now().UTC()
    61		items := []map[string]any{}
    62	
    63		if role == RoleRequester {
    64			rows, err := st.PG.QueryContext(ctx, `
    65				SELECT s.sample_id, s.request_id, s.status, s.serviceability, s.target_laboratory_id,
    66				       r.requested_at, r.delivery_deadline, r.origin_lat, r.origin_lng
    67				FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
    68				WHERE s.requester_id = $1
    69				ORDER BY r.created_at DESC`, sess.UserID)
    70			if err != nil {
    71				return nil, err
    72			}
    73			defer rows.Close()
    74			for rows.Next() {
    75				var sid, rid, status, svc string
    76				var lab sql.NullString
    77				var requested, deadline time.Time
    78				var lat, lng float64
    79				if err := rows.Scan(&sid, &rid, &status, &svc, &lab, &requested, &deadline, &lat, &lng); err != nil {
    80					continue
    81				}
    82				if !matchStatus(statusFilter, status, isTerminal(status)) {
    83					continue
    84				}
    85				tl, _ := st.loadTimelineForSample(ctx, sid)
    86				items = append(items, map[string]any{
    87					"kind":             "request",
    88					"sampleId":         sid,
    89					"requestId":        rid,
    90					"status":           status,
    91					"serviceability":   svc,
    92					"targetLaboratoryId": nullStr(lab),
    93					"requestedAt":      formatTime(requested),
    94					"deliveryDeadline": formatTime(deadline),
    95					"origin":           Coordinate{Latitude: lat, Longitude: lng},
    96					"timeline":         tl,
    97					"current":          !isTerminal(status),
    98				})
    99			}
   100			return items, nil
   101		}
   102	
   103		if isAdminOrDispatcher(role) {
   104			rows, err := st.PG.QueryContext(ctx, `
   105				SELECT a.assignment_id, a.sample_id, a.journey_id, a.kind, a.status, a.from_location_id, a.to_location_id,
   106				       a.worker_id, a.offered_worker_id, a.sequence, s.status
   107				FROM assignments a JOIN samples s ON s.sample_id = a.sample_id
   108				ORDER BY a.created_at DESC LIMIT 500`)
   109			if err != nil {
   110				return nil, err
   111			}
   112			defer rows.Close()
   113			for rows.Next() {
   114				item, ok := scanWorkItem(rows, statusFilter)
   115				if ok {
   116					sid, _ := item["sampleId"].(string)
   117					tl, _ := st.loadTimelineForSample(ctx, sid)
   118					item["timeline"] = tl
   119					items = append(items, item)
   120				}
   121			}
   122			return items, nil
   123		}
   124	
   125		rows, err := st.PG.QueryContext(ctx, `
   126			SELECT a.assignment_id, a.sample_id, a.journey_id, a.kind, a.status, a.from_location_id, a.to_location_id,
   127			       a.worker_id, a.offered_worker_id, a.sequence, s.status
   128			FROM assignments a JOIN samples s ON s.sample_id = a.sample_id
   129			WHERE a.worker_id = $1 OR a.offered_worker_id = $1
   130			ORDER BY a.created_at DESC`, sess.UserID)
   131		if err != nil {
   132			return nil, err
   133		}
   134		defer rows.Close()
   135		for rows.Next() {
   136			item, ok := scanWorkItem(rows, statusFilter)
   137			if !ok {
   138				continue
   139			}
   140			// collection professionals only see collection work they are qualified for
   141			if role == RoleCollection {
   142				kind, _ := item["kind"].(string)
   143				if kind != KindCollection && kind != KindNode {
   144					// they can also see handoff-related transport they hold
   145					if kind != KindTransport {
   146						continue
   147					}
   148				}
   149			}
   150			if role == RoleDelivery {
   151				kind, _ := item["kind"].(string)
   152				if kind != KindTransport {
   153					continue
   154				}
   155			}
   156			if role == RoleNode {
   157				kind, _ := item["kind"].(string)
   158				if kind != KindNode && kind != KindTransport && kind != KindCollection {
   159					continue
   160				}
   161			}
   162			if role == RoleLab {
   163				kind, _ := item["kind"].(string)
   164				if kind != KindLaboratory {
   165					continue
   166				}
   167			}
   168			sid, _ := item["sampleId"].(string)
   169			tl, _ := st.loadTimelineForSample(ctx, sid)
   170			item["timeline"] = tl
   171			_ = now
   172			items = append(items, item)
   173		}
   174		return items, nil
   175	}
