   269			                      total_cost_units, capacity_used, capacity_available, valid, active)
   270			VALUES ($1, 1, $2, $3, $4, $5, 1, 0, TRUE, TRUE)`,
   271			journeyID, mode, JourneyPlanned, eta, route.TotalCost); err != nil {
