   281		if _, err := tx.ExecContext(ctx, `
   282			INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
   283			VALUES ($1,$2,'pickup',$3,$4,0)`, journeyID, route.CollectionNode, seq, t); err != nil {
