   499	func (st *Store) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
   500		sess := sessionFrom(r.Context())
   501		if err := sess.requireAny(RoleAdministrator, RoleDispatcher, RoleNode, RoleLab, RoleDelivery, RoleCollection); err != nil {
   502			writeAPIError(w, err)
   503			return
   504		}
   505		var req struct {
   506			ResourceType   string `json:"resourceType"`
   507			ResourceID     string `json:"resourceId"`
   508			Reason         string `json:"reason"`
   509			OccurredAt     string `json:"occurredAt"`
   510			IdempotencyKey string `json:"idempotencyKey"`
   511		}
   512		if err := decodeJSON(r, &req); err != nil {
   513			writeAPIError(w, err)
   514			return
   515		}
   516		allowed := map[string]bool{"worker": true, "node": true, "route": true, "laboratory": true, "capacity": true}
   517		if !allowed[req.ResourceType] {
   518			writeErr(w, http.StatusBadRequest, "invalid_resource_type", "invalid resource type")
   519			return
   520		}
   521		occurredAt, err := parseTime(req.OccurredAt, "invalid_time")
   522		if err != nil {
   523			writeAPIError(w, err)
   524			return
   525		}
   526		ctx := r.Context()
   527		if req.IdempotencyKey != "" {
   528			hash := hashRequest("disruption", req.ResourceType, req.ResourceID, req.OccurredAt)
   529			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "disruption", hash)
   530			if err != nil {
   531				writeAPIError(w, err)
   532				return
   533			}
   534			if hit {
   535				replayIdempotent(w, status, body)
   536				return
   537			}
   538		}
   539		id := newUUID()
   540		// mark resource unavailable
   541		switch req.ResourceType {
   542		case "worker":
   543			_, _ = st.PG.ExecContext(ctx, `UPDATE users SET available = FALSE WHERE user_id = $1`, req.ResourceID)
   544		case "node", "laboratory":
   545			_, _ = st.PG.ExecContext(ctx, `UPDATE locations SET active = FALSE WHERE location_id = $1`, req.ResourceID)
   546			st.bumpNetwork(ctx, nil)
   547		case "route":
   548			_, _ = st.PG.ExecContext(ctx, `UPDATE connections SET active = FALSE WHERE connection_id = $1`, req.ResourceID)
   549			st.bumpNetwork(ctx, nil)
   550		}
   551		// find affected unfinished journeys
   552		affected := []string{}
   553		var rows *sql.Rows
   554		switch req.ResourceType {
   555		case "worker":
   556			rows, _ = st.PG.QueryContext(ctx, `
   557				SELECT DISTINCT journey_id FROM assignments
   558				WHERE (worker_id = $1 OR offered_worker_id = $1) AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   559		case "node", "laboratory":
   560			rows, _ = st.PG.QueryContext(ctx, `
   561				SELECT DISTINCT journey_id FROM assignments
   562				WHERE (from_location_id = $1 OR to_location_id = $1 OR node_id = $1 OR laboratory_id = $1)
   563				  AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   564		case "route":
   565			rows, _ = st.PG.QueryContext(ctx, `
   566				SELECT DISTINCT a.journey_id FROM assignments a
   567				JOIN connections c ON (c.from_location_id = a.from_location_id AND c.to_location_id = a.to_location_id)
   568				WHERE c.connection_id = $1 AND a.status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   569		case "capacity":
   570			rows, _ = st.PG.QueryContext(ctx, `
   571				SELECT DISTINCT journey_id FROM capacity_reservations WHERE resource_id = $1 AND active = TRUE`, req.ResourceID)
   572		}
   573		if rows != nil {
   574			affected, _ = scanStrings(rows)
   575		}
   576		replan := "not_required"
   577		if len(affected) > 0 {
   578			replan = "completed"
   579			for _, jid := range affected {
   580				_, rs, err := st.replanJourney(ctx, jid)
   581				if err != nil || rs == "failed" || rs == "expired" {
   582					if rs == "expired" {
   583						replan = "expired"
   584					} else if replan != "expired" {
   585						replan = "failed"
   586					}
   587				}
   588			}
   589		}
   590		_, _ = st.PG.ExecContext(ctx, `
   591			INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at, replan_status)
   592			VALUES ($1,$2,$3,$4,$5,$6)`, id, req.ResourceType, req.ResourceID, req.Reason, occurredAt, replan)
   593		st.audit(ctx, sess, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]any{"replanStatus": replan})
   594		out := map[string]any{"disruptionId": id, "replanStatus": replan}
   595		if req.IdempotencyKey != "" {
   596			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "disruption", hashRequest("disruption", req.ResourceType, req.ResourceID, req.OccurredAt), http.StatusCreated, out)
