   346	func (st *Store) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
   347		sess := sessionFrom(r.Context())
   348		if err := sess.requireAny(RoleAdministrator, RoleDispatcher, RoleNode, RoleLab, RoleDelivery, RoleCollection); err != nil {
   349			writeAPIError(w, err)
   350			return
   351		}
   352		var req struct {
   353			ResourceType   string `json:"resourceType"`
   354			ResourceID     string `json:"resourceId"`
   355			Reason         string `json:"reason"`
   356			OccurredAt     string `json:"occurredAt"`
   357			IdempotencyKey string `json:"idempotencyKey"`
   358		}
   359		if err := decodeJSON(r, &req); err != nil {
   360			writeAPIError(w, err)
   361			return
   362		}
   363		allowed := map[string]bool{"worker": true, "node": true, "route": true, "laboratory": true, "capacity": true}
   364		if !allowed[req.ResourceType] {
   365			writeErr(w, http.StatusBadRequest, "invalid_resource_type", "invalid resource type")
   366			return
   367		}
   368		occurredAt, err := parseTime(req.OccurredAt, "invalid_time")
   369		if err != nil {
   370			writeAPIError(w, err)
   371			return
   372		}
   373		ctx := r.Context()
   374		if req.IdempotencyKey != "" {
   375			hash := hashRequest("disruption", req.ResourceType, req.ResourceID, req.OccurredAt)
   376			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "disruption", hash)
   377			if err != nil {
   378				writeAPIError(w, err)
   379				return
   380			}
   381			if hit {
   382				replayIdempotent(w, status, body)
   383				return
   384			}
   385		}
   386		id := newUUID()
   387		// mark resource unavailable
   388		switch req.ResourceType {
   389		case "worker":
   390			_, _ = st.PG.ExecContext(ctx, `UPDATE users SET available = FALSE WHERE user_id = $1`, req.ResourceID)
   391		case "node", "laboratory":
   392			_, _ = st.PG.ExecContext(ctx, `UPDATE locations SET active = FALSE WHERE location_id = $1`, req.ResourceID)
   393			st.bumpNetwork(ctx, nil)
   394		case "route":
   395			_, _ = st.PG.ExecContext(ctx, `UPDATE connections SET active = FALSE WHERE connection_id = $1`, req.ResourceID)
   396			st.bumpNetwork(ctx, nil)
   397		}
   398		// find affected unfinished journeys
   399		affected := []string{}
   400		var rows *sql.Rows
   401		switch req.ResourceType {
   402		case "worker":
   403			rows, _ = st.PG.QueryContext(ctx, `
   404				SELECT DISTINCT journey_id FROM assignments
   405				WHERE (worker_id = $1 OR offered_worker_id = $1) AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   406		case "node", "laboratory":
   407			rows, _ = st.PG.QueryContext(ctx, `
   408				SELECT DISTINCT journey_id FROM assignments
   409				WHERE (from_location_id = $1 OR to_location_id = $1 OR node_id = $1 OR laboratory_id = $1)
   410				  AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   411		case "route":
   412			rows, _ = st.PG.QueryContext(ctx, `
   413				SELECT DISTINCT a.journey_id FROM assignments a
   414				JOIN connections c ON (c.from_location_id = a.from_location_id AND c.to_location_id = a.to_location_id)
   415				WHERE c.connection_id = $1 AND a.status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   416		case "capacity":
   417			rows, _ = st.PG.QueryContext(ctx, `
   418				SELECT DISTINCT journey_id FROM capacity_reservations WHERE resource_id = $1 AND active = TRUE`, req.ResourceID)
   419		}
   420		if rows != nil {
   421			affected, _ = scanStrings(rows)
   422		}
   423		replan := "not_required"
   424		if len(affected) > 0 {
   425			replan = "completed"
   426			for _, jid := range affected {
   427				_, rs, err := st.replanJourney(ctx, jid)
   428				if err != nil || rs == "failed" || rs == "expired" {
   429					if rs == "expired" {
   430						replan = "expired"
   431					} else if replan != "expired" {
   432						replan = "failed"
   433					}
   434				}
   435			}
   436		}
   437		_, _ = st.PG.ExecContext(ctx, `
   438			INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at, replan_status)
   439			VALUES ($1,$2,$3,$4,$5,$6)`, id, req.ResourceType, req.ResourceID, req.Reason, occurredAt, replan)
   440		st.audit(ctx, sess, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]any{"replanStatus": replan})
   441		out := map[string]any{"disruptionId": id, "replanStatus": replan}
   442		if req.IdempotencyKey != "" {
   443			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "disruption", hashRequest("disruption", req.ResourceType, req.ResourceID, req.OccurredAt), http.StatusCreated, out)
   444		}
   445		writeData(w, http.StatusCreated, out)
   446	}
