   170	func bearerFromWS(r *http.Request, protocols []string) string {
   171		if h := r.Header.Get("Authorization"); strings.HasPrefix(strings.ToLower(h), "bearer ") {
   172			return strings.TrimSpace(h[7:])
   173		}
   174		for _, p := range protocols {
   175			if strings.HasPrefix(p, "bearer.") {
   176				// base64url-encoded bearer.<token> — the token after the prefix may itself be the session token
   177				// Spec: "A bearer [REDACTED] is sent as a base64url-encoded bearer.<token> WebSocket subprotocol."
   178				rest := strings.TrimPrefix(p, "bearer.")
   179				if decoded, err := decodeB64URL(rest); err == nil && decoded != "" {
   180					return decoded
   181				}
   182				return rest
   183			}
   184		}
   185		if q := r.URL.Query().Get("token"); q != "" {
   186			return q
   187		}
   188		return ""
   189	}
