   381		if req.CapacityUnits < 0 {
   382			writeErr(w, http.StatusBadRequest, "invalid_capacity", "invalid capacity")
   383			return
   384		}
   385		cooled := 0
   386		if req.CooledCapacityUnits != nil {
   387			if *req.CooledCapacityUnits < 0 {
   388				writeErr(w, http.StatusBadRequest, "invalid_capacity", "invalid capacity")
   389				return
   390			}
   391			cooled = *req.CooledCapacityUnits
