   373		}
   374		var req struct {
   375			TargetJourneyID     string   `json:"targetJourneyId"`
   376			ExpectedPlanVersion int      `json:"expectedPlanVersion"`
   377			SourceJourneyIDs    []string `json:"sourceJourneyIds"`
   378			IdempotencyKey      string   `json:"idempotencyKey"`
   379		}
   380		if err := decodeJSON(r, &req); err != nil {
   381			writeAPIError(w, err)
   382			return
   383		}
   384		if len(req.SourceJourneyIDs) == 0 {
   385			writeErr(w, http.StatusBadRequest, "invalid_merge", "invalid merge")
   386			return
   387		}
   388		ctx := r.Context()
   389		if req.IdempotencyKey != "" {
   390			hash := hashRequest("merge", req.TargetJourneyID, itoa(req.ExpectedPlanVersion))
   391			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "merge", hash)
   392			if err != nil {
   393				writeAPIError(w, err)
   394				return
   395			}
   396			if hit {
   397				replayIdempotent(w, status, body)
   398				return
   399			}
   400		}
   401		if _, err := st.expectPlanVersion(ctx, req.TargetJourneyID, req.ExpectedPlanVersion); err != nil {
   402			writeAPIError(w, err)
   403			return
   404		}
   405		// validate compatibility of samples
   406		if err := st.validateMerge(ctx, req.TargetJourneyID, req.SourceJourneyIDs); err != nil {
   407			writeAPIError(w, err)
   408			return
   409		}
   410		var newVersion int
   411		err := st.tx(ctx, func(tx *sql.Tx) error {
   412			v, err := st.bumpPlan(ctx, tx, req.TargetJourneyID)
   413			if err != nil {
