    11	func (st *Store) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
    12		sess := sessionFrom(r.Context())
    13		if err := sess.requireActiveRole(); err != nil {
    14			writeAPIError(w, err)
    15			return
    16		}
    17		role := sess.ActiveRole
    18		statusFilter := ""
    19		if r.Method == http.MethodPost && r.ContentLength > 0 {
    20			var body struct {
    21				Role   string `json:"role"`
    22				Status string `json:"status"`
    23			}
    24			if err := decodeJSON(r, &body); err != nil {
    25				writeAPIError(w, err)
    26				return
    27			}
    28			if body.Role != "" {
    29				if !sess.hasRole(body.Role) && !isAdminOrDispatcher(sess.ActiveRole) {
    30					writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
    31					return
    32				}
    33				if !validRole(body.Role) {
    34					writeErr(w, http.StatusBadRequest, "invalid_role", "invalid role")
