    37				role = body.Role
    38			}
    39			statusFilter = body.Status
    40		}
    41		if q := r.URL.Query().Get("role"); q != "" {
    42			role = q
    43		}
    44		if q := r.URL.Query().Get("status"); q != "" {
    45			statusFilter = q
    46		}
    47		st.expireOffers(r.Context())
    48		items, err := st.listWork(r.Context(), sess, role, statusFilter)
    49		if err != nil {
    50			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
    51			return
