   126			SELECT a.assignment_id, a.sample_id, a.journey_id, a.kind, a.status, a.from_location_id, a.to_location_id,
   127			       a.worker_id, a.offered_worker_id, a.sequence, s.status
   128			FROM assignments a JOIN samples s ON s.sample_id = a.sample_id
   129			WHERE a.worker_id = $1 OR a.offered_worker_id = $1
   130			ORDER BY a.created_at DESC`, sess.UserID)
   131		if err != nil {
   132			return nil, err
   133		}
   134		defer rows.Close()
   135		for rows.Next() {
   136			item, ok := scanWorkItem(rows, statusFilter)
   137			if !ok {
   138				continue
