   260	func (st *Store) handleConfirmLabReceipt(w http.ResponseWriter, r *http.Request) {
   261		sess := sessionFrom(r.Context())
   262		if err := sess.requireAny(RoleLab, RoleAdministrator, RoleDispatcher); err != nil {
   263			writeAPIError(w, err)
   264			return
   265		}
   266		var req struct {
   267			SampleID       string `json:"sampleId"`
   268			LaboratoryID   string `json:"laboratoryId"`
   269			ReceivedAt     string `json:"receivedAt"`
   270			IdempotencyKey string `json:"idempotencyKey"`
   271		}
   272		if err := decodeJSON(r, &req); err != nil {
   273			writeAPIError(w, err)
   274			return
   275		}
   276		receivedAt, err := parseTime(req.ReceivedAt, "invalid_time")
   277		if err != nil {
   278			writeAPIError(w, err)
   279			return
   280		}
   281		ctx := r.Context()
   282		if req.IdempotencyKey != "" {
   283			hash := hashRequest("lab_receipt", req.SampleID, req.LaboratoryID)
   284			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "lab_receipt", hash)
   285			if err != nil {
   286				writeAPIError(w, err)
   287				return
   288			}
   289			if hit {
   290				replayIdempotent(w, status, body)
   291				return
   292			}
   293		}
   294		var status string
   295		var deadline time.Time
   296		err = st.PG.QueryRowContext(ctx, `
   297			SELECT s.status, r.delivery_deadline
   298			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
   299			WHERE s.sample_id = $1`, req.SampleID).Scan(&status, &deadline)
   300		if err == sql.ErrNoRows {
   301			writeErr(w, http.StatusNotFound, "not_found", "not found")
   302			return
   303		}
   304		if status == SampleReceived {
   305			out := map[string]any{"sampleId": req.SampleID, "status": SampleReceived}
   306			writeData(w, http.StatusOK, out)
   307			return
   308		}
   309		final := SampleReceived
   310		var exc any
   311		if receivedAt.After(deadline) {
   312			final = SampleExpired
   313			b, _ := json.Marshal(map[string]any{"reason": "missed_delivery_deadline"})
   314			exc = b
   315		}
   316		_, err = st.PG.ExecContext(ctx, `
   317			UPDATE samples SET status = $1, received_laboratory_id = $2, received_at = $3, current_holder_id = $4, exception = COALESCE($5, exception)
   318			WHERE sample_id = $6`, final, req.LaboratoryID, receivedAt, sess.UserID, exc, req.SampleID)
   319		if err != nil {
   320			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   321			return
   322		}
   323		_, _ = st.PG.ExecContext(ctx, `
   324			UPDATE assignments SET status = 'completed', completed_at = $1
   325			WHERE sample_id = $2 AND kind = 'laboratory' AND status NOT IN ('cancelled','completed')`, receivedAt, req.SampleID)
   326		_, _ = st.PG.ExecContext(ctx, `
   327			UPDATE journeys SET status = 'completed'
   328			WHERE journey_id IN (SELECT journey_id FROM journey_samples WHERE sample_id = $1) AND active = TRUE`, req.SampleID)
   329		st.audit(ctx, sess, "confirm_laboratory_receipt", "sample", req.SampleID, true, map[string]any{"laboratoryId": req.LaboratoryID})
   330		_, _ = st.writeTimeline(ctx, nil, req.SampleID, "", "", "confirm_laboratory_receipt", sess.UserID, sess.ActiveRole, "sample", req.SampleID, true, map[string]any{"status": final})
   331		st.emitEvent(ctx, "sample_received", "sample", req.SampleID, map[string]any{"status": final}, "")
   332		out := map[string]any{"sampleId": req.SampleID, "status": final}
   333		if req.IdempotencyKey != "" {
   334			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "lab_receipt", hashRequest("lab_receipt", req.SampleID, req.LaboratoryID), http.StatusOK, out)
   335		}
   336		writeData(w, http.StatusOK, out)
   337	}
