   339	func (st *Store) handleRecordLabException(w http.ResponseWriter, r *http.Request) {
   340		sess := sessionFrom(r.Context())
   341		if err := sess.requireAny(RoleLab, RoleAdministrator, RoleDispatcher); err != nil {
   342			writeAPIError(w, err)
