   344		}
   345		var req struct {
   346			SampleID       string `json:"sampleId"`
   347			LaboratoryID   string `json:"laboratoryId"`
   348			Reason         string `json:"reason"`
   349			ObservedAt     string `json:"observedAt"`
   350			IdempotencyKey string `json:"idempotencyKey"`
   351		}
   352		if err := decodeJSON(r, &req); err != nil {
   353			writeAPIError(w, err)
   354			return
   355		}
   356		if req.Reason == "" {
   357			writeErr(w, http.StatusBadRequest, "invalid_reason", "invalid reason")
   358			return
   359		}
   360		observedAt, err := parseTime(req.ObservedAt, "invalid_time")
   361		if err != nil {
   362			writeAPIError(w, err)
   363			return
   364		}
   365		ctx := r.Context()
   366		if req.IdempotencyKey != "" {
   367			hash := hashRequest("lab_exc", req.SampleID, req.Reason)
   368			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "lab_exc", hash)
   369			if err != nil {
   370				writeAPIError(w, err)
   371				return
   372			}
   373			if hit {
   374				replayIdempotent(w, status, body)
   375				return
   376			}
   377		}
   378		var exists int
   379		_ = st.PG.QueryRowContext(ctx, `SELECT COUNT(*) FROM samples WHERE sample_id = $1`, req.SampleID).Scan(&exists)
   380		if exists == 0 {
   381			writeErr(w, http.StatusNotFound, "not_found", "not found")
   382			return
   383		}
   384		id := newUUID()
   385		_, _ = st.PG.ExecContext(ctx, `
   386			INSERT INTO exceptions (exception_id, sample_id, laboratory_id, reason, observed_at)
   387			VALUES ($1,$2,$3,$4,$5)`, id, req.SampleID, req.LaboratoryID, req.Reason, observedAt)
   388		exc, _ := json.Marshal(map[string]any{"reason": req.Reason, "laboratoryId": req.LaboratoryID})
   389		_, _ = st.PG.ExecContext(ctx, `UPDATE samples SET status = $1, exception = $2 WHERE sample_id = $3`, SampleException, exc, req.SampleID)
   390		st.audit(ctx, sess, "record_laboratory_exception", "sample", req.SampleID, true, map[string]any{"reason": req.Reason})
   391		_, _ = st.writeTimeline(ctx, nil, req.SampleID, "", "", "record_laboratory_exception", sess.UserID, sess.ActiveRole, "sample", req.SampleID, true, map[string]any{"reason": req.Reason})
   392		out := map[string]any{"exceptionId": id, "status": SampleException}
   393		if req.IdempotencyKey != "" {
   394			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "lab_exc", hashRequest("lab_exc", req.SampleID, req.Reason), http.StatusCreated, out)
   395		}
   396		writeData(w, http.StatusCreated, out)
   397	}
