import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

print('ALL SCHEMAS:', list(spec['components']['schemas'].keys()))
print()
for name in spec['components']['schemas']:
    sch = spec['components']['schemas'][name]
    print('='*70)
    print(name, 'required=', sch.get('required'), 'addProps=', sch.get('additionalProperties'), 'type=', sch.get('type'))
    if 'enum' in sch:
        print('  enum=', sch['enum'])
    if 'properties' in sch:
        print('  props=', list(sch['properties'].keys()))
        for k,v in sch['properties'].items():
            extra = {kk:vv for kk,vv in v.items() if kk in ('type','enum','format','$ref','minimum','nullable','minLength')}
            if 'items' in v:
                extra['items'] = v['items']
            if 'additionalProperties' in v:
                extra['additionalProperties'] = v['additionalProperties']
            print(f'    {k}: {json.dumps(extra)}')
    if 'allOf' in sch:
        print('  allOf=', json.dumps(sch['allOf'])[:400])
    if 'oneOf' in sch:
        print('  oneOf=', json.dumps(sch['oneOf'])[:400])

print('\n\n==== ALL OPS ====')
for p, methods in spec['paths'].items():
    for m, op in methods.items():
        oid = op.get('operationId')
        req = op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema',{})
        print(f'{oid:40} {m.upper():4} {p}')
        if req:
            print(f'    REQ required={req.get("required")} props={list(req.get("properties",{}).keys())}')
        for c,r in op.get('responses',{}).items():
            sch = r.get('content',{}).get('application/json',{}).get('schema',{})
            if sch:
                data = sch.get('properties',{}).get('data', sch)
                print(f'    {c} required={data.get("required")} props={list(data.get("properties",{}).keys())[:20]} ref={data.get("$ref")} add={data.get("additionalProperties")}')
