python3 << 'PY'
import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

# dump remaining important schemas
for name in ['JourneyPlan','JourneyStop','JourneyLeg','Assignment','Handoff','HandlingCheckpoint',
             'SampleType','UserRecord','WorkerAvailability','Disruption','ExceptionRecord',
             'RealtimeEvent','TimelineEntry','Coordinate','Capacity','Location','Connection',
             'OperationsLocation','OperationsConnection','AuditEntry','Role']:
    if name not in spec['components']['schemas']:
        print('MISSING', name)
        continue
    sch = spec['components']['schemas'][name]
    print('='*70)
    print(name, 'required=', sch.get('required'), 'addProps=', sch.get('additionalProperties'))
    print('  props=', list(sch.get('properties',{}).keys()))
    for k,v in sch.get('properties',{}).items():
        extra = {kk:vv for kk,vv in v.items() if kk in ('type','enum','format','$ref','minimum','nullable')}
        if 'items' in v:
            extra['items'] = {ik:iv for ik,iv in v['items'].items() if ik in ('type','format','$ref','enum')} if isinstance(v['items'], dict) else v['items']
        if 'additionalProperties' in v:
            extra['additionalProperties'] = v['additionalProperties']
        if 'allOf' in v:
            extra['allOf'] = v['allOf']
        print(f'    {k}: {json.dumps(extra)}')
    if 'enum' in sch:
        print('  enum=', sch['enum'])

print('\n\n==== remaining path request/response summaries ====')
for p, methods in spec['paths'].items():
    for m, op in methods.items():
        oid = op.get('operationId','')
        print(f'\n{oid} {m.upper()} {p}')
        req = op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema',{})
        if req:
            print('  REQ required=', req.get('required'), 'props=', list(req.get('properties',{}).keys()))
        params = op.get('parameters',[])
        if params:
            print('  PARAMS', [(x.get('name'), x.get('in'), x.get('required')) for x in params])
        for c,r in op.get('responses',{}).items():
            if str(c).startswith('2'):
                sch = r.get('content',{}).get('application/json',{}).get('schema',{})
                data = sch.get('properties',{}).get('data', sch)
                print(f'  {c} required=', data.get('required'), 'props=', list(data.get('properties',{}).keys())[:20], 'ref=', data.get('$ref'), 'oneOf=', bool(data.get('oneOf')))
