import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

# dump request bodies and 200/201/4xx for every path
for p, methods in spec['paths'].items():
    for m, op in methods.items():
        print('='*80)
        print(op.get('operationId'), m.upper(), p)
        print(' security:', op.get('security'))
        if 'parameters' in op:
            print(' params:', json.dumps(op['parameters'])[:500])
        if 'requestBody' in op:
            content = op['requestBody'].get('content',{})
            for ct, body in content.items():
                print(' request required:', op['requestBody'].get('required'))
                sch = body.get('schema',{})
                print(' request schema required:', sch.get('required'))
                print(' request props:', list(sch.get('properties',{}).keys()) if 'properties' in sch else sch)
                for k,v in sch.get('properties',{}).items():
                    extra = {kk:vv for kk,vv in v.items() if kk in ('type','enum','format','$ref','minimum','nullable','minimum','maximum')}
                    if 'items' in v:
                        extra['items'] = v['items'] if not isinstance(v['items'], dict) else {ik:iv for ik,iv in v['items'].items() if ik in ('type','format','$ref','enum')}
                    print(f'    {k}: {json.dumps(extra)[:250]}')
        for code, resp in op.get('responses',{}).items():
            desc = resp.get('description','')
            content = resp.get('content',{})
            if not content:
                print(f'  {code}: {desc} (no content)')
                continue
            for ct, body in content.items():
                sch = body.get('schema',{})
                if '$ref' in sch:
                    print(f'  {code}: $ref {sch["$ref"]}')
                elif sch.get('properties',{}).get('data'):
                    d = sch['properties']['data']
                    if '$ref' in d:
                        print(f'  {code}: data $ref {d["$ref"]}')
                    elif 'oneOf' in d:
                        print(f'  {code}: data oneOf {[x.get("$ref") for x in d["oneOf"]]}')
                    else:
                        print(f'  {code}: data required={d.get("required")} props={list(d.get("properties",{}).keys())}')
                else:
                    print(f'  {code}: {json.dumps(sch)[:300]}')
