   512	func (st *Store) reserveCapacity(ctx context.Context, tx *sql.Tx, resourceID, journeyID, sampleID string, cooled bool, units int) error {
   513		var capu, resu, ccap, cres int
   514		err := tx.QueryRowContext(ctx, `
   515			SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
   516			FROM capacity_pools WHERE resource_id = $1 FOR UPDATE`, resourceID).
   517			Scan(&capu, &resu, &ccap, &cres)
   518		if err == sql.ErrNoRows {
   519			// unlimited if not configured
   520			_, _ = tx.ExecContext(ctx, `
   521				INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   522				VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   523			return nil
   524		}
   525		if err != nil {
   526			return err
   527		}
   528		if cooled {
   529			if ccap > 0 && cres+units > ccap {
   530				return errJSON("cooled_capacity_exhausted", "cooled capacity exhausted", http.StatusConflict)
   531			}
   532			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = cooled_reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   533		} else {
