   535				return errJSON("capacity_exhausted", "capacity exhausted", http.StatusConflict)
   536			}
   537			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   538		}
   539		if err != nil {
   540			return err
   541		}
   542		_, err = tx.ExecContext(ctx, `
