print()
print('LocationFunction:', json.dumps(spec['components']['schemas']['LocationFunction'], indent=2))
print()
print('SampleState:', json.dumps(spec['components']['schemas']['SampleState'], indent=2)[:2000])
print()

# remaining ops details
for p in ['/api/read-sample-lifecycle','/api/read-sample-state/{sampleId}','/api/read-operations-state',
          '/api/read-serviceability-snapshot','/api/list-role-work','/api/create-collection-request',
          '/api/ingest-presealed-sample','/api/confirm-handoff','/api/confirm-laboratory-receipt',
          '/api/create-connection','/api/create-location','/api/create-sample-type','/api/create-user',
          '/api/decline-assignment','/api/edit-active-plan','/api/initiate-handoff',
          '/api/merge-journeys','/api/record-handling-checkpoint','/api/record-laboratory-exception',
          '/api/record-worker-location','/api/report-disruption','/api/reroute-journey',
          '/api/search-audit-trail','/api/select-active-role','/api/set-connection-status',
          '/api/set-location-function-status','/api/set-location-status','/api/split-journey',
          '/api/read-user/{userId}','/api/events']:
    methods = spec['paths'].get(p, {})
    for m, op in methods.items():
        print('='*70)
        print(op.get('operationId'), m.upper(), p)
        if 'parameters' in op:
            for prm in op['parameters']:
                print('  param', prm.get('name'), prm.get('in'), 'req=', prm.get('required'))
        if 'requestBody' in op:
            sch = list(op['requestBody']['content'].values())[0]['schema']
            print(' req required:', sch.get('required'))
            print(' req props:', {k: {kk:vv for kk,vv in v.items() if kk in ('type','enum','format','$ref','minimum')} for k,v in sch.get('properties',{}).items()})
        for code, resp in op['responses'].items():
            content = resp.get('content',{})
            if not content:
                print(f' {code}: no content')
                continue
            sch = list(content.values())[0]['schema']
            d = sch.get('properties',{}).get('data', sch)
            if '$ref' in d:
                print(f' {code}: data $ref {d["$ref"]}')
            elif 'oneOf' in d:
                print(f' {code}: oneOf {[x.get("$ref") for x in d["oneOf"]]}')
            else:
                print(f' {code}: required={d.get("required")} props={list(d.get("properties",{}).keys())[:20]} addProps={d.get("additionalProperties")}')
                if d.get('properties') and len(d.get('properties',{})) <= 12:
                    for k,v in d.get('properties',{}).items():
                        extra = {kk:vv for kk,vv in v.items() if kk in ('type','enum','format','$ref')}
                        print(f'    {k}: {json.dumps(extra)[:180]}')

print('\n=== error codes used ===')
# collect unique error codes
codes=set()
def walk(o):
    if isinstance(o, dict):
        if 'enum' in o and 'code' in str(o)[:50]:
            pass
        if o.get('type')=='string' and 'enum' in o:
            # look at parent context later
            for e in o['enum']:
                if isinstance(e,str) and ('_' in e or e in ('unauthorized','forbidden','not_found')):
                    codes.add(e)
        for v in o.values():
            walk(v)
    elif isinstance(o, list):
        for i in o: walk(i)
walk(spec)
print(sorted(codes))
