   405		compliant := req.ObservedTemperatureC >= minT && req.ObservedTemperatureC <= maxT
   406		if req.ContainerType != "" && reqContainer != "" && req.ContainerType != reqContainer {
   407			compliant = false
   408		}
   409		status := SampleSealed
   410		var exc any
   411		if !compliant {
   412			status = SampleException
   413			excMap := map[string]any{
