   421		_, err = st.PG.ExecContext(ctx, `
   422			UPDATE samples SET status = $1, sealed = TRUE, sealed_at = $2, current_holder_id = $3, exception = COALESCE($4, exception)
   423			WHERE sample_id = $5`, status, collectedAt, sess.UserID, exc, req.SampleID)
   424		if err != nil {
   425			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
