   687	func (st *Store) releaseJourneyCapacity(ctx context.Context, tx *sql.Tx, journeyID string) {
   688		rows, err := tx.QueryContext(ctx, `
   689			SELECT reservation_id, resource_id, cooled, units FROM capacity_reservations
   690			WHERE journey_id = $1 AND active = TRUE`, journeyID)
   691		if err != nil {
   692			return
   693		}
   694		type resv struct {
   695			id, resource string
   696			cooled       bool
   697			units        int
   698		}
   699		var list []resv
   700		for rows.Next() {
   701			var r resv
   702			if err := rows.Scan(&r.id, &r.resource, &r.cooled, &r.units); err == nil {
   703				list = append(list, r)
   704			}
   705		}
   706		rows.Close()
   707		for _, r := range list {
   708			if r.cooled {
   709				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = GREATEST(cooled_reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   710			} else {
   711				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = GREATEST(reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   712			}
   713			_, _ = tx.ExecContext(ctx, `UPDATE capacity_reservations SET active = FALSE WHERE reservation_id = $1`, r.id)
   714		}
   715	}
