python3 << 'PY'
import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

schemas_to_print = [
    'LocationFunctionStates','Role','SampleState','SampleLifecycle','SampleWorkItem',
    'JourneyWorkItem','AssignmentWorkItem','RoleWork','RoleWorkItem','OperationsState',
    'OperationsLocation','OperationsConnection','JourneyPlan','JourneyStop','JourneyLeg',
    'TimelineEntry','AuditEntry','AuditSearchResult','ServiceabilityRegion','Capacity',
    'Certification','Coordinate','RealtimeEvent'
]
for n in schemas_to_print:
    s = spec['components']['schemas'][n]
    print('='*70)
    print(n)
    print('required:', s.get('required'))
    print('addProps:', s.get('additionalProperties'))
    for k,v in s.get('properties',{}).items():
        extra = {kk:vv for kk,vv in v.items() if kk in ('type','enum','format','$ref','minimum','maximum')}
        if 'items' in v:
            it = v['items']
            extra['items'] = {kk:vv for kk,vv in it.items() if kk in ('type','enum','format','$ref')} if isinstance(it, dict) else it
        print(f'  {k}: {json.dumps(extra)[:250]}')

print('\n=== remaining ops that were clipped ===')
for p in ['/api/create-location','/api/create-sample-type','/api/create-user','/api/decline-assignment',
          '/api/edit-active-plan','/api/ingest-presealed-sample','/api/list-role-work',
          '/api/read-operations-state','/api/read-sample-lifecycle','/api/read-sample-state/{sampleId}',
          '/api/read-serviceability-snapshot','/api/read-user/{userId}','/api/search-audit-trail',
          '/api/select-active-role','/api/set-connection-status','/api/set-location-function-status',
          '/api/set-location-status','/api/split-journey']:
    methods = spec['paths'].get(p, {})
    for m, op in methods.items():
        print('='*70)
        print(op.get('operationId'), m.upper(), p)
        if 'parameters' in op:
            for prm in op['parameters']:
                print('  param', prm.get('name'), prm.get('in'), 'req=', prm.get('required'))
        if 'requestBody' in op:
            sch = list(op['requestBody']['content'].values())[0]['schema']
            print(' req required:', sch.get('required'))
            props = {}
            for k,v in sch.get('properties',{}).items():
                extra = {kk:vv for kk,vv in v.items() if kk in ('type','enum','format','$ref','minimum','maximum')}
                if 'items' in v:
                    extra['items'] = v['items']
                props[k] = extra
            print(' req props:', json.dumps(props)[:1800])
        for code, resp in op['responses'].items():
            if code not in ('200','201','101'):
                continue
            content = resp.get('content',{})
            if not content:
                print(f' {code}: no content')
                continue
            sch = list(content.values())[0]['schema']
            if 'properties' in sch and 'data' in sch.get('properties',{}):
                d = sch['properties']['data']
                print(f' {code}: envelope data')
            else:
                d = sch
                print(f' {code}: raw body')
            if '$ref' in d:
                print(f'    $ref {d["$ref"]}')
            elif 'oneOf' in d:
                print(f'    oneOf {[x.get("$ref") for x in d["oneOf"]]}')
            else:
                print(f'    required={d.get("required")}')
                print(f'    props={list(d.get("properties",{}).keys())}')
                for k,v in d.get('properties',{}).items():
                    extra = {kk:vv for kk,vv in v.items() if kk in ('type','enum','format','$ref')}
                    if extra:
                        print(f'      {k}: {json.dumps(extra)[:200]}')
