   548	func (st *Store) releaseJourneyCapacity(ctx context.Context, tx *sql.Tx, journeyID string) {
   549		rows, err := tx.QueryContext(ctx, `
   550			SELECT reservation_id, resource_id, cooled, units FROM capacity_reservations
   551			WHERE journey_id = $1 AND active = TRUE`, journeyID)
   552		if err != nil {
   553			return
   554		}
   555		type resv struct {
   556			id, resource string
   557			cooled       bool
   558			units        int
   559		}
   560		var list []resv
   561		for rows.Next() {
   562			var r resv
   563			if err := rows.Scan(&r.id, &r.resource, &r.cooled, &r.units); err == nil {
   564				list = append(list, r)
   565			}
   566		}
   567		rows.Close()
   568		for _, r := range list {
   569			if r.cooled {
   570				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = GREATEST(cooled_reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   571			} else {
   572				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = GREATEST(reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   573			}
   574			_, _ = tx.ExecContext(ctx, `UPDATE capacity_reservations SET active = FALSE WHERE reservation_id = $1`, r.id)
   575		}
   576	}
