    78	func (st *Store) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
    79		sess := sessionFrom(r.Context())
    80		if err := sess.requireAny(RoleCollection, RoleDelivery, RoleNode, RoleLab, RoleAdministrator, RoleDispatcher); err != nil {
