    87		}
    88		if err := decodeJSON(r, &req); err != nil {
    89			writeAPIError(w, err)
    90			return
    91		}
    92		ctx := r.Context()
    93		if req.IdempotencyKey != "" {
    94			hash := hashRequest("accept", req.AssignmentID, sess.UserID)
    95			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "accept", hash)
    96			if err != nil {
    97				writeAPIError(w, err)
    98				return
    99			}
   100			if hit {
   101				replayIdempotent(w, status, body)
   102				return
   103			}
   104		}
   105		st.expireOffers(ctx)
   106		var offered sql.NullString
   107		var status, sampleID, kind string
   108		err := st.PG.QueryRowContext(ctx, `
   109			SELECT offered_worker_id, status, sample_id, kind FROM assignments WHERE assignment_id = $1`, req.AssignmentID).
   110			Scan(&offered, &status, &sampleID, &kind)
   111		if err == sql.ErrNoRows {
   112			writeErr(w, http.StatusNotFound, "not_found", "not found")
   113			return
   114		}
   115		if err != nil {
   116			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   117			return
   118		}
   119		if status == AssignAccepted || status == AssignInProgress || status == AssignCompleted ||
   120			status == AssignPickedUp || status == AssignInTransit || status == AssignArrived || status == AssignDelivered {
   121			// already accepted by this worker?
   122			var worker sql.NullString
   123			_ = st.PG.QueryRowContext(ctx, `SELECT worker_id FROM assignments WHERE assignment_id = $1`, req.AssignmentID).Scan(&worker)
   124			if worker.Valid && worker.String == sess.UserID {
   125				out := map[string]any{"assignmentId": req.AssignmentID, "status": status}
   126				writeData(w, http.StatusOK, out)
   127				return
   128			}
   129		}
   130		if status != AssignOffered && status != AssignPending {
   131			writeErr(w, http.StatusConflict, "assignment_not_offered", "assignment not offered")
   132			return
   133		}
   134		if !offered.Valid || offered.String != sess.UserID {
   135			if !isAdminOrDispatcher(sess.ActiveRole) {
   136				writeErr(w, http.StatusForbidden, "assignment_not_offered", "assignment not offered to this worker")
   137				return
   138			}
   139		}
   140		_, err = st.PG.ExecContext(ctx, `
   141			UPDATE assignments SET status = 'accepted', worker_id = $1, offered_worker_id = $1
   142			WHERE assignment_id = $2`, sess.UserID, req.AssignmentID)
   143		if err != nil {
   144			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   145			return
   146		}
   147		if kind == KindCollection {
   148			_, _ = st.PG.ExecContext(ctx, `UPDATE samples SET status = $1 WHERE sample_id = $2 AND status IN ('requested','assigned')`,
   149				SampleAssigned, sampleID)
   150		}
   151		st.audit(ctx, sess, "accept_assignment", "assignment", req.AssignmentID, true, map[string]any{"sampleId": sampleID})
   152		_, _ = st.writeTimeline(ctx, nil, sampleID, "", req.AssignmentID, "accept_assignment", sess.UserID, sess.ActiveRole, "assignment", req.AssignmentID, true, nil)
   153		st.emitEvent(ctx, "assignment_accepted", "assignment", req.AssignmentID, map[string]any{"sampleId": sampleID}, "")
   154		out := map[string]any{"assignmentId": req.AssignmentID, "status": AssignAccepted}
   155		if req.IdempotencyKey != "" {
   156			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "accept", hashRequest("accept", req.AssignmentID, sess.UserID), http.StatusOK, out)
   157		}
   158		writeData(w, http.StatusOK, out)
   159	}
