   561		var excObj any
   562		if len(exc) > 0 && string(exc) != "null" {
   563			var m map[string]any
   564			if json.Unmarshal(exc, &m) == nil {
   565				excObj = m
   566			}
   567		}
   568		var journeyID sql.NullString
   569		_ = st.PG.QueryRowContext(ctx, `
   570			SELECT js.journey_id FROM journey_samples js
   571			JOIN journeys j ON j.journey_id = js.journey_id
   572			WHERE js.sample_id = $1 AND j.active = TRUE
   573			ORDER BY j.plan_version DESC LIMIT 1`, sampleID).Scan(&journeyID)
   574	
   575		return map[string]any{
