   577			"requestId":            requestID,
   578			"status":               status,
   579			"currentHolderId":      nullStr(holder),
   580			"latestCoordinate":     coord,
   581			"locationRecordedAt":   formatTimePtr(rec),
   582			"locationStale":        isLocationStale(rec, now),
