   394	func (st *Store) pickWorkerTx(ctx context.Context, tx *sql.Tx, kind, locationID, qualification, exclude string) string {
   395		role := RoleDelivery
   396		switch kind {
   397		case KindCollection:
   398			role = RoleCollection
   399		case KindNode:
   400			role = RoleNode
   401		case KindLaboratory:
   402			role = RoleLab
   403		}
   404		q := `
   405			SELECT u.user_id
   406			FROM users u
   407			JOIN user_roles ur ON ur.user_id = u.user_id AND ur.role = $1
   408			WHERE u.active = TRUE AND u.available = TRUE`
   409		args := []any{role}
   410		idx := 2
   411		if locationID != "" && (kind == KindNode || kind == KindLaboratory) {
   412			q += ` AND u.assigned_location_id = $` + itoa(idx)
   413			args = append(args, locationID)
   414			idx++
   415		}
   416		if qualification != "" && kind == KindCollection {
   417			q += ` AND EXISTS (SELECT 1 FROM user_qualifications q WHERE q.user_id = u.user_id AND q.qualification = $` + itoa(idx) + `)`
   418			args = append(args, qualification)
   419			idx++
   420		}
   421		if exclude != "" {
   422			q += ` AND u.user_id <> $` + itoa(idx)
   423			args = append(args, exclude)
   424			idx++
   425		}
   426		// fair: fewer open assignments, then older last_assigned, then fewer recent declines
   427		q += `
   428			ORDER BY
   429			  (SELECT COUNT(*) FROM assignments a WHERE (a.worker_id = u.user_id OR a.offered_worker_id = u.user_id)
   430			     AND a.status IN ('offered','accepted','in_progress','pending','at_pickup','picked_up','in_transit','arrived')),
   431			  CASE WHEN u.last_decline_at IS NOT NULL AND u.last_decline_at > now() - interval '2 hours'
   432			       THEN u.decline_count ELSE 0 END,
   433			  COALESCE(u.last_assigned_at, '1970-01-01'::timestamptz),
   434			  u.user_id
   435			LIMIT 1`
   436		var id string
   437		if err := tx.QueryRowContext(ctx, q, args...).Scan(&id); err != nil {
   438			return ""
   439		}
   440		_, _ = tx.ExecContext(ctx, `UPDATE users SET last_assigned_at = now() WHERE user_id = $1`, id)
   441		return id
   442	}
   443	
   444	func itoa(n int) string {
   445		if n == 0 {
   446			return "0"
   447		}
   448		var b [12]byte
   449		i := len(b)
   450		for n > 0 {
   451			i--
   452			b[i] = byte('0' + n%10)
   453			n /= 10
   454		}
   455		return string(b[i:])
   456	}
