   558	func (st *Store) replanJourney(ctx context.Context, journeyID string) (int, string, error) {
   559		sids, _ := st.journeySampleIDs(ctx, journeyID)
   560		if len(sids) == 0 {
   561			return 0, "not_required", errJSON("not_found", "not found", http.StatusNotFound)
   562		}
   563		sampleID := sids[0]
   564		var originLat, originLng float64
   565		var originType string
   566		var originNode sql.NullString
   567		var deadline, earliest time.Time
   568		var typeID string
   569		var holder sql.NullString
   570		var sealed bool
   571		err := st.PG.QueryRowContext(ctx, `
   572			SELECT r.origin_lat, r.origin_lng, r.origin_type, r.origin_node_id, r.delivery_deadline, r.earliest_collection_at,
   573			       s.sample_type_id, s.current_holder_id, s.sealed
   574			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
   575			WHERE s.sample_id = $1`, sampleID).
   576			Scan(&originLat, &originLng, &originType, &originNode, &deadline, &earliest, &typeID, &holder, &sealed)
   577		if err != nil {
   578			return 0, "", err
   579		}
   580		styp, err := st.loadSampleType(ctx, typeID)
   581		if err != nil {
   582			return 0, "", err
   583		}
   584		// if sealed, start from current holder's latest location / last completed stop
   585		startType := originType
   586		startNode := nullStr(originNode)
   587		if sealed {
   588			var lastLoc sql.NullString
   589			_ = st.PG.QueryRowContext(ctx, `
   590				SELECT COALESCE(to_location_id, from_location_id) FROM assignments
   591				WHERE sample_id = $1 AND status IN ('completed','delivered')
   592				ORDER BY sequence DESC LIMIT 1`, sampleID).Scan(&lastLoc)
   593			if lastLoc.Valid {
   594				startType = OriginNode
   595				startNode = lastLoc.String
   596				if l, ok := st.locCoord(ctx, lastLoc.String); ok {
   597					originLat, originLng = l.Latitude, l.Longitude
   598				}
   599			}
   600		}
   601		route, reason := st.findRoute(ctx, originLat, originLng, startType, startNode, typeID, styp.RequiresCooled, deadline, time.Now())
   602		replan := "completed"
   603		newVersion := 0
   604		err = st.tx(ctx, func(tx *sql.Tx) error {
   605			v, err := st.bumpPlan(ctx, tx, journeyID)
   606			if err != nil {
   607				return err
   608			}
   609			newVersion = v
   610			if reason != "serviceable" || route == nil {
   611				replan = "failed"
   612				if reason == "deadline_unreachable" {
   613					replan = "expired"
   614					_, _ = tx.ExecContext(ctx, `UPDATE samples SET status = 'expired' WHERE sample_id = $1 AND status NOT IN ('received','cancelled')`, sampleID)
   615					_, _ = tx.ExecContext(ctx, `UPDATE journeys SET status = 'expired', replan_status = 'expired', valid = FALSE WHERE journey_id = $1`, journeyID)
   616				} else {
   617					_, _ = tx.ExecContext(ctx, `UPDATE journeys SET replan_status = 'failed', valid = FALSE WHERE journey_id = $1`, journeyID)
   618				}
   619				return nil
   620			}
   621			// cancel unfinished assignments and recreate
   622			_, _ = tx.ExecContext(ctx, `
   623				UPDATE assignments SET status = 'cancelled'
   624				WHERE journey_id = $1 AND status NOT IN ('completed','delivered','cancelled')`, journeyID)
   625			_, _ = tx.ExecContext(ctx, `DELETE FROM journey_stops WHERE journey_id = $1 AND completed_at IS NULL`, journeyID)
   626			st.releaseJourneyCapacity(ctx, tx, journeyID)
