import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

ops = ['authenticate_user','create_user','read_user','check_serviceability','read_serviceability_snapshot',
       'create_collection_request','collect_and_seal_sample','list_role_work','read_sample_state',
       'read_sample_lifecycle','read_journey_plan','read_operations_state','accept_assignment',
       'decline_assignment','record_worker_location','confirm_laboratory_receipt',
       'record_laboratory_exception','edit_active_plan','ingest_presealed_sample','stream_realtime_events']
for path, methods in spec['paths'].items():
    for method, op in methods.items():
        oid = op.get('operationId')
        if oid not in ops:
            continue
        print(f'\n======== {oid} {method.upper()} {path} ========')
        if op.get('parameters'):
            print('PARAMS', json.dumps([{k:p.get(k) for k in ('name','in','required')} | {'schema': p.get('schema',{})} for p in op['parameters']], indent=2)[:800])
        if op.get('requestBody'):
            content = op['requestBody'].get('content',{})
            for ct, body in content.items():
                print('REQUEST', json.dumps(body.get('schema',{}), indent=2)[:2200])
        for code, resp in op.get('responses',{}).items():
            if str(code).startswith('2'):
                content = resp.get('content',{})
                print(f'RESPONSE {code}')
                for ct, body in content.items():
                    print(json.dumps(body.get('schema',{}), indent=2)[:2200])
