   425		var curSeq int
   426		_ = st.PG.QueryRowContext(ctx, `SELECT location_sequence FROM users WHERE user_id = $1`, sess.UserID).Scan(&curSeq)
   427		if req.Sequence <= curSeq {
   428			writeErr(w, http.StatusConflict, "stale_location", "stale location")
