    98				})
    99			}
   100			return items, nil
   101		}
   102	
   103		if isAdminOrDispatcher(role) {
   104			rows, err := st.PG.QueryContext(ctx, `
   105				SELECT a.assignment_id, a.sample_id, a.journey_id, a.kind, a.status, a.from_location_id, a.to_location_id,
   106				       a.worker_id, a.offered_worker_id, a.sequence, s.status
   107				FROM assignments a JOIN samples s ON s.sample_id = a.sample_id
   108				ORDER BY a.created_at DESC LIMIT 500`)
   109			if err != nil {
   110				return nil, err
   111			}
   112			defer rows.Close()
