   473	func (st *Store) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
   474		sess := sessionFrom(r.Context())
   475		if err := sess.requireActiveRole(); err != nil {
   476			writeAPIError(w, err)
   477			return
   478		}
   479		sampleID := r.PathValue("sampleId")
   480		if !st.canSeeSample(r.Context(), sess, sampleID) {
   481			writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
   482			return
   483		}
   484		var exists int
   485		_ = st.PG.QueryRowContext(r.Context(), `SELECT COUNT(*) FROM samples WHERE sample_id = $1`, sampleID).Scan(&exists)
   486		if exists == 0 {
   487			writeErr(w, http.StatusNotFound, "not_found", "not found")
   488			return
   489		}
   490		tl, _ := st.loadTimelineForSample(r.Context(), sampleID)
   491		writeData(w, http.StatusOK, map[string]any{
   492			"sampleId": sampleID,
   493			"timeline": tl,
   494		})
   495	}
