   497	func (st *Store) canSeeSample(ctx context.Context, sess *Session, sampleID string) bool {
   498		if isAdminOrDispatcher(sess.ActiveRole) {
   499			return true
   500		}
   501		var requester, holder sql.NullString
   502		err := st.PG.QueryRowContext(ctx, `SELECT requester_id, current_holder_id FROM samples WHERE sample_id = $1`, sampleID).Scan(&requester, &holder)
   503		if err != nil {
   504			return false
   505		}
   506		if sess.ActiveRole == RoleRequester && requester.Valid && requester.String == sess.UserID {
   507			return true
   508		}
   509		if holder.Valid && holder.String == sess.UserID {
   510			return true
   511		}
   512		var n int
   513		_ = st.PG.QueryRowContext(ctx, `
   514			SELECT COUNT(*) FROM assignments
   515			WHERE sample_id = $1 AND (worker_id = $2 OR offered_worker_id = $2)`, sampleID, sess.UserID).Scan(&n)
   516		return n > 0
   517	}
