   528			       target_laboratory_id, received_laboratory_id, received_at, serviceability, serviceability_reason,
   529			       latest_lat, latest_lng, location_recorded_at, exception
   530			FROM samples WHERE sample_id = $1`, sampleID).
   531			Scan(&requestID, &requesterID, &typeID, &status, &sealed, &sealedAt, &holder, &target, &recvLab, &recvAt,
   532				&svc, &svcReason, &lat, &lng, &locAt, &exc)
   533		if err == sql.ErrNoRows {
   534			return nil, errJSON("not_found", "not found", http.StatusNotFound)
   535		}
   536		if err != nil {
   537			return nil, err
   538		}
   539		if !st.canSeeSample(ctx, sess, sampleID) {
   540			return nil, errJSON("forbidden", "forbidden", http.StatusForbidden)
   541		}
   542		var originLat, originLng float64
   543		var originType string
   544		var originNode sql.NullString
   545		var requested, deadline, earliest, latest time.Time
   546		_ = st.PG.QueryRowContext(ctx, `
   547			SELECT origin_lat, origin_lng, origin_type, origin_node_id, requested_at, delivery_deadline,
   548			       earliest_collection_at, latest_collection_at
   549			FROM collection_requests WHERE request_id = $1`, requestID).
   550			Scan(&originLat, &originLng, &originType, &originNode, &requested, &deadline, &earliest, &latest)
   551	
   552		now := time.Now().UTC()
   553		var rec *time.Time
   554		if locAt.Valid {
   555			rec = &locAt.Time
   556		}
   557		var coord any
   558		if lat.Valid && lng.Valid {
   559			coord = Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
   560		}
   561		var excObj any
   562		if len(exc) > 0 && string(exc) != "null" {
   563			var m map[string]any
   564			if json.Unmarshal(exc, &m) == nil {
   565				excObj = m
   566			}
   567		}
   568		var journeyID sql.NullString
   569		_ = st.PG.QueryRowContext(ctx, `
   570			SELECT js.journey_id FROM journey_samples js
   571			JOIN journeys j ON j.journey_id = js.journey_id
   572			WHERE js.sample_id = $1 AND j.active = TRUE
   573			ORDER BY j.plan_version DESC LIMIT 1`, sampleID).Scan(&journeyID)
   574	
   575		return map[string]any{
   576			"sampleId":             sampleID,
   577			"requestId":            requestID,
   578			"status":               status,
   579			"currentHolderId":      nullStr(holder),
   580			"latestCoordinate":     coord,
   581			"locationRecordedAt":   formatTimePtr(rec),
   582			"locationStale":        isLocationStale(rec, now),
   583			"sealed":               sealed,
   584			"serviceability":       svc,
   585			"serviceabilityReason": svcReason,
   586			"targetLaboratoryId":   nullStr(target),
   587			"receivedLaboratoryId": nullStr(recvLab),
   588			"exception":            excObj,
   589			"journeyId":            nullStr(journeyID),
   590			"origin":               Coordinate{Latitude: originLat, Longitude: originLng},
   591			"originType":           originType,
   592			"deliveryDeadline":     formatTime(deadline),
   593		}, nil
   594	}
