    10	func (st *Store) checkIdempotency(ctx context.Context, userID, key, operation, reqHash string) (hit bool, status int, body []byte, err error) {
    11		if key == "" {
    12			return false, 0, nil, errJSON("idempotency_required", "idempotency key required", http.StatusBadRequest)
    13		}
    14		var storedHash string
    15		var storedStatus int
    16		var storedBody []byte
    17		qerr := st.PG.QueryRowContext(ctx, `
    18			SELECT request_hash, status_code, response_body FROM idempotency_keys
    19			WHERE key = $1`, key).Scan(&storedHash, &storedStatus, &storedBody)
    20		if qerr == sql.ErrNoRows {
    21			return false, 0, nil, nil
    22		}
    23		if qerr != nil {
    24			return false, 0, nil, qerr
    25		}
    26		if storedHash != reqHash {
    27			return false, 0, nil, errJSON("idempotency_conflict", "idempotency conflict", http.StatusConflict)
    28		}
    29		return true, storedStatus, storedBody, nil
    30	}
