   111			SELECT id, type, entity_type, entity_id, payload, created_at
   112			FROM realtime_events
   113			WHERE id > $1
   114			  AND (audience_role IS NULL OR audience_role = $2)
   115			ORDER BY id ASC
   116			LIMIT 200`, *cursor, c.sess.ActiveRole)
   117		if err != nil {
