   130	func (st *Store) recomputeServiceability(ctx context.Context) {
   131		locs, err := st.loadLocations(ctx)
   132		if err != nil {
   133			return
   134		}
   135		var revision int
   136		_ = st.PG.QueryRowContext(ctx, `SELECT value::int FROM app_meta WHERE key = 'network_revision'`).Scan(&revision)
   137		regions := []map[string]any{}
   138		count := 0
   139		for _, l := range locs {
   140			if l.Active && l.Collection {
   141				count++
   142				regions = append(regions, map[string]any{
   143					"locationId": l.ID,
   144					"name":       l.Name,
   145					"latitude":   l.Lat,
   146					"longitude":  l.Lng,
   147					"coverageKm": l.Coverage,
   148				})
   149			}
   150		}
   151		payload, _ := json.Marshal(map[string]any{
   152			"regions":                    regions,
   153			"activeCollectionPointCount": count,
   154		})
   155		var last int
   156		_ = st.PG.QueryRowContext(ctx, `SELECT COALESCE(MAX(version),0) FROM serviceability_snapshots`).Scan(&last)
   157		_, _ = st.PG.ExecContext(ctx, `
   158			INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, payload)
   159			VALUES ($1, 'complete', now(), $2, $3)`, last+1, revision, payload)
   160		_, _ = st.PG.ExecContext(ctx, `UPDATE app_meta SET value = $1 WHERE key = 'serviceability_version'`, last+1)
   161	}
