   163	func (st *Store) findRoute(ctx context.Context, originLat, originLng float64, originType, originNodeID, typeID string, needsCooled bool, deadline time.Time, earliest time.Time) (*plannedRoute, string) {
   164		locs, err := st.loadLocations(ctx)
   165		if err != nil {
   166			return nil, "no_route"
   167		}
   168		conns, err := st.loadConnections(ctx)
   169		if err != nil {
   170			return nil, "no_route"
   171		}
   172		locByID := map[string]locRow{}
   173		for _, l := range locs {
   174			locByID[l.ID] = l
   175		}
   176		accept, _ := st.acceptingLabs(ctx, typeID)
   177		labs := []locRow{}
   178		for _, l := range locs {
   179			if l.Active && l.Laboratory && accept[l.ID] {
   180				labs = append(labs, l)
   181			}
   182		}
   183		if len(labs) == 0 {
   184			return nil, "no_accepting_laboratory"
   185		}
   186	
   187		// determine start nodes
   188		startNodes := []locRow{}
   189		if originType == OriginNode && originNodeID != "" {
   190			if l, ok := locByID[originNodeID]; ok && l.Active {
   191				startNodes = append(startNodes, l)
   192			}
   193		} else {
   194			for _, l := range locs {
   195				if !l.Active || !l.Collection {
   196					continue
   197				}
   198				d := haversineKm(originLat, originLng, l.Lat, l.Lng)
   199				if d <= l.Coverage && d <= 5.0 {
   200					startNodes = append(startNodes, l)
   201				}
   202			}
   203		}
   204		if len(startNodes) == 0 {
   205			return nil, "outside_service_coverage"
   206		}
   207	
   208		// graph of active connections (optionally requiring cooled)
   209		type edge struct {
   210			to      string
   211			minutes int
   212			cost    float64
   213			connID  string
   214			cooled  bool
   215		}
   216		graph := map[string][]edge{}
   217		for _, c := range conns {
   218			if !c.Active {
   219				continue
   220			}
   221			if needsCooled && !c.Cooled {
   222				continue
   223			}
   224			from := locByID[c.FromID]
   225			to := locByID[c.ToID]
   226			if !from.Active || !to.Active {
   227				continue
   228			}
   229			graph[c.FromID] = append(graph[c.FromID], edge{to: c.ToID, minutes: c.TravelMinutes, cost: c.Cost, connID: c.ID, cooled: c.Cooled})
   230		}
   231	
   232		// Dijkstra-like by minutes then cost
   233		type state struct {
   234			node    string
   235			minutes int
   236			cost    float64
   237			path    []routeHop
   238		}
   239		best := (*plannedRoute)(nil)
   240		for _, start := range startNodes {
   241			// if start itself is an accepting lab, zero-hop route
   242			if accept[start.ID] && start.Laboratory {
   243				cand := &plannedRoute{
   244					CollectionNode: start.ID,
   245					Laboratory:     start.ID,
   246					Hops:           []routeHop{},
   247					TotalMinutes:   start.Handling,
   248					TotalCost:      0,
   249					NeedsCooled:    needsCooled,
   250				}
   251				if best == nil || cand.TotalMinutes < best.TotalMinutes || (cand.TotalMinutes == best.TotalMinutes && cand.TotalCost < best.TotalCost) {
   252					best = cand
   253				}
   254			}
   255			seen := map[string]int{}
   256			queue := []state{{node: start.ID, minutes: start.Handling, cost: 0}}
   257			for len(queue) > 0 {
   258				// pop min minutes
   259				mi := 0
   260				for i := 1; i < len(queue); i++ {
   261					if queue[i].minutes < queue[mi].minutes || (queue[i].minutes == queue[mi].minutes && queue[i].cost < queue[mi].cost) {
   262						mi = i
   263					}
   264				}
   265				cur := queue[mi]
   266				queue = append(queue[:mi], queue[mi+1:]...)
   267				if prev, ok := seen[cur.node]; ok && prev <= cur.minutes {
   268					continue
   269				}
   270				seen[cur.node] = cur.minutes
   271				if accept[cur.node] && locByID[cur.node].Laboratory {
   272					cand := &plannedRoute{
   273						CollectionNode: start.ID,
   274						Laboratory:     cur.node,
   275						Hops:           append([]routeHop{}, cur.path...),
   276						TotalMinutes:   cur.minutes + locByID[cur.node].Handling,
   277						TotalCost:      cur.cost,
   278						NeedsCooled:    needsCooled,
   279					}
   280					if best == nil || cand.TotalMinutes < best.TotalMinutes || (cand.TotalMinutes == best.TotalMinutes && cand.TotalCost < best.TotalCost) {
   281						best = cand
   282					}
   283				}
   284				for _, e := range graph[cur.node] {
   285					hop := routeHop{FromID: cur.node, ToID: e.to, ConnID: e.connID, Minutes: e.minutes, Cost: e.cost, Cooled: e.cooled}
   286					np := append(append([]routeHop{}, cur.path...), hop)
   287					queue = append(queue, state{node: e.to, minutes: cur.minutes + e.minutes + locByID[e.to].Handling, cost: cur.cost + e.cost, path: np})
   288				}
   289			}
   290		}
   291		if best == nil {
   292			return nil, "no_route"
   293		}
   294		// deadline check
   295		if !deadline.IsZero() && !earliest.IsZero() {
   296			eta := earliest.Add(time.Duration(best.TotalMinutes) * time.Minute)
   297			if eta.After(deadline) {
   298				return nil, "deadline_unreachable"
   299			}
   300		}
   301		return best, "serviceable"
   302	}
   303	
   304	func (st *Store) checkCapacityForRoute(ctx context.Context, route *plannedRoute, cooled bool) bool {
   305		if route == nil {
   306			return false
   307		}
   308		check := func(id string) bool {
   309			c := st.getCapacity(ctx, id)
   310			if cooled {
   311				if c.CooledCapacityUnits > 0 && c.CooledAvailableUnits < 1 {
   312					return false
   313				}
   314			} else {
   315				if c.CapacityUnits > 0 && c.AvailableUnits < 1 {
   316					return false
   317				}
   318			}
   319			return true
   320		}
   321		if !check(route.CollectionNode) {
   322			return false
   323		}
   324		if !check(route.Laboratory) {
   325			return false
   326		}
   327		for _, h := range route.Hops {
   328			if !check(h.ConnID) {
   329				return false
   330			}
   331		}
   332		return true
   333	}
   334	
   335	type svcResult struct {
   336		Serviceable           bool
   337		Reason                string
   338		TargetLaboratoryID    string
   339		EstimatedArrivalAt    time.Time
   340		ServiceabilityVersion int
   341		Route                 *plannedRoute
   342	}
   343	
   344	func (st *Store) evaluateServiceability(ctx context.Context, origin Coordinate, originType, originNodeID, typeID string, requestedAt, deadline, earliest, latest time.Time) (*svcResult, error) {
   345		styp, err := st.loadSampleType(ctx, typeID)
   346		if err != nil {
   347			return nil, errJSON("not_found", "sample type not found", http.StatusNotFound)
   348		}
   349		var version int
   350		_ = st.PG.QueryRowContext(ctx, `SELECT COALESCE(MAX(version),1) FROM serviceability_snapshots`).Scan(&version)
   351		needsCooled := styp.RequiresCooled
   352		route, reason := st.findRoute(ctx, origin.Latitude, origin.Longitude, originType, originNodeID, typeID, needsCooled, deadline, earliest)
   353		res := &svcResult{Reason: reason, ServiceabilityVersion: version, Route: route}
   354		if reason != "serviceable" {
   355			res.Serviceable = false
   356			return res, nil
   357		}
   358		if !st.checkCapacityForRoute(ctx, route, needsCooled) {
   359			res.Serviceable = false
   360			res.Reason = "insufficient_capacity"
   361			return res, nil
   362		}
   363		res.Serviceable = true
   364		res.TargetLaboratoryID = route.Laboratory
   365		res.EstimatedArrivalAt = earliest.Add(time.Duration(route.TotalMinutes) * time.Minute)
   366		return res, nil
   367	}
   368	
   369	func (st *Store) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
   370		sess := sessionFrom(r.Context())
   371		if err := sess.requireAny(RoleRequester, RoleAdministrator, RoleDispatcher); err != nil {
   372			writeAPIError(w, err)
   373			return
   374		}
   375		var req struct {
   376			Origin               Coordinate `json:"origin"`
   377			OriginType           string     `json:"originType"`
   378			OriginNodeID         string     `json:"originNodeId"`
   379			SampleTypeID         string     `json:"sampleTypeId"`
   380			RequestedAt          string     `json:"requestedAt"`
   381			DeliveryDeadline     string     `json:"deliveryDeadline"`
   382			EarliestCollectionAt string     `json:"earliestCollectionAt"`
   383			LatestCollectionAt   string     `json:"latestCollectionAt"`
   384		}
   385		if err := decodeJSON(r, &req); err != nil {
   386			writeAPIError(w, err)
   387			return
   388		}
   389		if !validCoord(req.Origin) {
   390			writeErr(w, http.StatusBadRequest, "invalid_origin", "invalid origin")
   391			return
   392		}
   393		if req.OriginType == "" {
   394			req.OriginType = OriginHome
   395		}
   396		if req.OriginType != OriginHome && req.OriginType != OriginClinic && req.OriginType != OriginNode {
   397			writeErr(w, http.StatusBadRequest, "invalid_origin_type", "invalid origin type")
   398			return
   399		}
   400		requestedAt, err := parseTime(req.RequestedAt, "invalid_time")
   401		if err != nil {
   402			writeAPIError(w, err)
   403			return
   404		}
   405		deadline, err := parseTime(req.DeliveryDeadline, "invalid_deadline")
   406		if err != nil {
   407			writeAPIError(w, err)
   408			return
   409		}
   410		if !deadline.After(requestedAt) {
   411			writeErr(w, http.StatusBadRequest, "invalid_deadline", "invalid deadline")
   412			return
   413		}
   414		earliest := requestedAt
   415		if req.EarliestCollectionAt != "" {
   416			earliest, err = parseTime(req.EarliestCollectionAt, "invalid_collection_window")
   417			if err != nil {
   418				writeAPIError(w, err)
   419				return
   420			}
   421		}
   422		latest := deadline
   423		if req.LatestCollectionAt != "" {
   424			latest, err = parseTime(req.LatestCollectionAt, "invalid_collection_window")
   425			if err != nil {
   426				writeAPIError(w, err)
   427				return
   428			}
   429		}
   430		if latest.Before(earliest) {
   431			writeErr(w, http.StatusBadRequest, "invalid_collection_window", "invalid collection window")
   432			return
   433		}
   434		ctx := r.Context()
   435		res, err := st.evaluateServiceability(ctx, req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, requestedAt, deadline, earliest, latest)
   436		if err != nil {
   437			writeAPIError(w, err)
   438			return
   439		}
   440		out := map[string]any{
   441			"serviceable":           res.Serviceable,
   442			"reason":                res.Reason,
   443			"serviceabilityVersion": res.ServiceabilityVersion,
   444		}
   445		if res.TargetLaboratoryID != "" {
   446			out["targetLaboratoryId"] = res.TargetLaboratoryID
   447		}
   448		if !res.EstimatedArrivalAt.IsZero() {
   449			out["estimatedArrivalAt"] = formatTime(res.EstimatedArrivalAt)
   450		}
   451		st.audit(ctx, sess, "check_serviceability", "serviceability", req.SampleTypeID, true, map[string]any{"reason": res.Reason})
   452		writeData(w, http.StatusOK, out)
   453	}
