   428	func (st *Store) validateMerge(ctx context.Context, target string, sources []string) error {
   429		type meta struct {
   430			typeID, container string
   431			cooled, batch     bool
   432			incompat          []string
   433		}
   434		load := func(jid string) []meta {
   435			rows, err := st.PG.QueryContext(ctx, `
   436				SELECT s.sample_type_id, st.container_type, st.requires_cooled_route, st.batching_allowed
   437				FROM journey_samples js
   438				JOIN samples s ON s.sample_id = js.sample_id
   439				JOIN sample_types st ON st.sample_type_id = s.sample_type_id
   440				WHERE js.journey_id = $1`, jid)
   441			if err != nil {
   442				return nil
   443			}
   444			defer rows.Close()
   445			var out []meta
   446			for rows.Next() {
   447				var m meta
   448				if err := rows.Scan(&m.typeID, &m.container, &m.cooled, &m.batch); err == nil {
   449					m.incompat, _ = st.loadIncompat(ctx, m.typeID)
   450					out = append(out, m)
   451				}
   452			}
   453			return out
   454		}
   455		all := load(target)
   456		for _, s := range sources {
   457			all = append(all, load(s)...)
   458		}
   459		for i := 0; i < len(all); i++ {
   460			if !all[i].batch {
   461				return errJSON("incompatible_batch", "incompatible batch", http.StatusConflict)
   462			}
   463			for j := i + 1; j < len(all); j++ {
   464				if all[i].container != all[j].container {
   465					return errJSON("incompatible_container", "incompatible container", http.StatusConflict)
   466				}
   467				if all[i].cooled != all[j].cooled {
   468					return errJSON("incompatible_temperature", "incompatible temperature", http.StatusConflict)
   469				}
   470				if containsStr(all[i].incompat, all[j].typeID) || containsStr(all[j].incompat, all[i].typeID) {
   471					return errJSON("incompatible_sample_types", "incompatible sample types", http.StatusConflict)
   472				}
   473			}
   474		}
   475		return nil
   476	}
