   151		st.audit(ctx, sess, "accept_assignment", "assignment", req.AssignmentID, true, map[string]any{"sampleId": sampleID})
   152		_, _ = st.writeTimeline(ctx, nil, sampleID, "", req.AssignmentID, "accept_assignment", sess.UserID, sess.ActiveRole, "assignment", req.AssignmentID, true, nil)
   153		st.emitEvent(ctx, "assignment_accepted", "assignment", req.AssignmentID, map[string]any{"sampleId": sampleID}, "")
   154		out := map[string]any{"assignmentId": req.AssignmentID, "status": AssignAccepted}
   155		if req.IdempotencyKey != "" {
