import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

ops = [
    'create_sample_type','create_user','decline_assignment','edit_active_plan',
    'stream_realtime_events','ingest_presealed_sample','initiate_handoff',
    'list_role_work','merge_journeys','read_journey_plan','read_operations_state',
    'read_sample_lifecycle'
]
for p, methods in spec['paths'].items():
    for m, op in methods.items():
        oid = op.get('operationId')
        if oid not in ops:
            continue
        print('='*80)
        print(f"{m.upper()} {p}  op={oid}")
        if op.get('parameters'):
            print('PARAMS:', json.dumps(op['parameters'])[:600])
        if op.get('requestBody'):
            schema = op['requestBody'].get('content',{}).get('application/json',{}).get('schema',{})
            print('REQ required:', schema.get('required'))
            print('REQ props:', list(schema.get('properties',{}).keys()))
            for k,v in schema.get('properties',{}).items():
                if '$ref' not in str(v) or True:
                    print(f'  {k}:', json.dumps(v)[:300])
        for code in ['200','201']:
            if code in op.get('responses',{}):
                schema = op['responses'][code].get('content',{}).get('application/json',{}).get('schema',{})
                print(f'RESP {code}:', json.dumps(schema, indent=2)[:5000])
        for code in ['400','401','403','404','409']:
            if code in op.get('responses',{}):
                schema = op['responses'][code].get('content',{}).get('application/json',{}).get('schema',{})
                enums = schema.get('properties',{}).get('code',{}).get('enum',[])
                if enums:
                    print(f'{code}:', enums)
        print()

# dump remaining schemas that were clipped
for name in ['JourneyPlan','OperationsState','OperationsWorker']:
    s = spec['components']['schemas'].get(name)
    if s:
        print('==== SCHEMA', name, '====')
        print(json.dumps(s, indent=2)[:6000])
        print()
