   163	func (st *Store) findRoute(ctx context.Context, originLat, originLng float64, originType, originNodeID, typeID string, needsCooled bool, deadline time.Time, earliest time.Time) (*plannedRoute, string) {
   164		locs, err := st.loadLocations(ctx)
   165		if err != nil {
   166			return nil, "no_route"
   167		}
   168		conns, err := st.loadConnections(ctx)
   169		if err != nil {
   170			return nil, "no_route"
   171		}
   172		locByID := map[string]locRow{}
   173		for _, l := range locs {
   174			locByID[l.ID] = l
   175		}
   176		accept, _ := st.acceptingLabs(ctx, typeID)
   177		labs := []locRow{}
   178		for _, l := range locs {
   179			if l.Active && l.Laboratory && accept[l.ID] {
   180				labs = append(labs, l)
   181			}
   182		}
   183		if len(labs) == 0 {
   184			return nil, "no_accepting_laboratory"
   185		}
   186	
   187		// determine start nodes
   188		startNodes := []locRow{}
   189		if originType == OriginNode && originNodeID != "" {
   190			if l, ok := locByID[originNodeID]; ok && l.Active {
   191				startNodes = append(startNodes, l)
   192			}
   193		} else {
   194			for _, l := range locs {
   195				if !l.Active || !l.Collection {
   196					continue
   197				}
   198				d := haversineKm(originLat, originLng, l.Lat, l.Lng)
   199				if d <= l.Coverage && d <= 5.0 {
   200					startNodes = append(startNodes, l)
   201				}
   202			}
   203		}
   204		if len(startNodes) == 0 {
   205			return nil, "outside_service_coverage"
   206		}
   207	
   208		// graph of active connections (optionally requiring cooled)
   209		type edge struct {
   210			to      string
   211			minutes int
   212			cost    float64
   213			connID  string
   214			cooled  bool
   215		}
   216		graph := map[string][]edge{}
   217		for _, c := range conns {
   218			if !c.Active {
   219				continue
   220			}
   221			if needsCooled && !c.Cooled {
   222				continue
   223			}
   224			from := locByID[c.FromID]
   225			to := locByID[c.ToID]
   226			if !from.Active || !to.Active {
   227				continue
   228			}
   229			graph[c.FromID] = append(graph[c.FromID], edge{to: c.ToID, minutes: c.TravelMinutes, cost: c.Cost, connID: c.ID, cooled: c.Cooled})
   230		}
   231	
   232		// Dijkstra-like by minutes then cost
   233		type state struct {
   234			node    string
   235			minutes int
   236			cost    float64
   237			path    []routeHop
   238		}
   239		best := (*plannedRoute)(nil)
   240		for _, start := range startNodes {
   241			// if start itself is an accepting lab, zero-hop route
   242			if accept[start.ID] && start.Laboratory {
   243				cand := &plannedRoute{
   244					CollectionNode: start.ID,
   245					Laboratory:     start.ID,
   246					Hops:           []routeHop{},
   247					TotalMinutes:   start.Handling,
   248					TotalCost:      0,
   249					NeedsCooled:    needsCooled,
   250				}
   251				if best == nil || cand.TotalMinutes < best.TotalMinutes || (cand.TotalMinutes == best.TotalMinutes && cand.TotalCost < best.TotalCost) {
   252					best = cand
   253				}
   254			}
   255			seen := map[string]int{}
   256			queue := []state{{node: start.ID, minutes: start.Handling, cost: 0}}
   257			for len(queue) > 0 {
   258				// pop min minutes
   259				mi := 0
   260				for i := 1; i < len(queue); i++ {
   261					if queue[i].minutes < queue[mi].minutes || (queue[i].minutes == queue[mi].minutes && queue[i].cost < queue[mi].cost) {
   262						mi = i
   263					}
   264				}
   265				cur := queue[mi]
   266				queue = append(queue[:mi], queue[mi+1:]...)
   267				if prev, ok := seen[cur.node]; ok && prev <= cur.minutes {
   268					continue
   269				}
   270				seen[cur.node] = cur.minutes
   271				if accept[cur.node] && locByID[cur.node].Laboratory {
   272					cand := &plannedRoute{
   273						CollectionNode: start.ID,
   274						Laboratory:     cur.node,
   275						Hops:           append([]routeHop{}, cur.path...),
   276						TotalMinutes:   cur.minutes + locByID[cur.node].Handling,
   277						TotalCost:      cur.cost,
   278						NeedsCooled:    needsCooled,
   279					}
   280					if best == nil || cand.TotalMinutes < best.TotalMinutes || (cand.TotalMinutes == best.TotalMinutes && cand.TotalCost < best.TotalCost) {
   281						best = cand
   282					}
   283				}
   284				for _, e := range graph[cur.node] {
   285					hop := routeHop{FromID: cur.node, ToID: e.to, ConnID: e.connID, Minutes: e.minutes, Cost: e.cost, Cooled: e.cooled}
   286					np := append(append([]routeHop{}, cur.path...), hop)
   287					queue = append(queue, state{node: e.to, minutes: cur.minutes + e.minutes + locByID[e.to].Handling, cost: cur.cost + e.cost, path: np})
   288				}
   289			}
   290		}
   291		if best == nil {
   292			return nil, "no_route"
   293		}
   294		// deadline check
   295		if !deadline.IsZero() && !earliest.IsZero() {
   296			eta := earliest.Add(time.Duration(best.TotalMinutes) * time.Minute)
   297			if eta.After(deadline) {
   298				return nil, "deadline_unreachable"
   299			}
   300		}
   301		return best, "serviceable"
   302	}
