   602	func (st *Store) replanJourney(ctx context.Context, journeyID string) (int, string, error) {
   603		sids, _ := st.journeySampleIDs(ctx, journeyID)
   604		if len(sids) == 0 {
   605			return 0, "not_required", errJSON("not_found", "not found", http.StatusNotFound)
   606		}
   607		sampleID := sids[0]
   608		var originLat, originLng float64
   609		var originType string
   610		var originNode sql.NullString
   611		var deadline, earliest time.Time
   612		var typeID string
   613		var holder sql.NullString
   614		var sealed bool
   615		err := st.PG.QueryRowContext(ctx, `
   616			SELECT r.origin_lat, r.origin_lng, r.origin_type, r.origin_node_id, r.delivery_deadline, r.earliest_collection_at,
   617			       s.sample_type_id, s.current_holder_id, s.sealed
   618			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
   619			WHERE s.sample_id = $1`, sampleID).
   620			Scan(&originLat, &originLng, &originType, &originNode, &deadline, &earliest, &typeID, &holder, &sealed)
   621		if err != nil {
   622			return 0, "", err
   623		}
   624		styp, err := st.loadSampleType(ctx, typeID)
   625		if err != nil {
   626			return 0, "", err
   627		}
   628		// if sealed, start from current holder's latest location / last completed stop
   629		startType := originType
   630		startNode := nullStr(originNode)
   631		if sealed {
   632			var lastLoc sql.NullString
   633			_ = st.PG.QueryRowContext(ctx, `
   634				SELECT COALESCE(to_location_id, from_location_id) FROM assignments
   635				WHERE sample_id = $1 AND status IN ('completed','delivered')
   636				ORDER BY sequence DESC LIMIT 1`, sampleID).Scan(&lastLoc)
   637			if lastLoc.Valid {
   638				startType = OriginNode
   639				startNode = lastLoc.String
   640				if l, ok := st.locCoord(ctx, lastLoc.String); ok {
   641					originLat, originLng = l.Latitude, l.Longitude
   642				}
   643			}
   644		}
   645		route, reason := st.findRoute(ctx, originLat, originLng, startType, startNode, typeID, styp.RequiresCooled, deadline, time.Now())
   646		replan := "completed"
   647		newVersion := 0
   648		err = st.tx(ctx, func(tx *sql.Tx) error {
   649			v, err := st.bumpPlan(ctx, tx, journeyID)
   650			if err != nil {
   651				return err
   652			}
   653			newVersion = v
   654			if reason != "serviceable" || route == nil {
   655				replan = "failed"
   656				if reason == "deadline_unreachable" {
   657					replan = "expired"
   658					_, _ = tx.ExecContext(ctx, `UPDATE samples SET status = 'expired' WHERE sample_id = $1 AND status NOT IN ('received','cancelled')`, sampleID)
   659					_, _ = tx.ExecContext(ctx, `UPDATE journeys SET status = 'expired', replan_status = 'expired', valid = FALSE WHERE journey_id = $1`, journeyID)
   660				} else {
   661					_, _ = tx.ExecContext(ctx, `UPDATE journeys SET replan_status = 'failed', valid = FALSE WHERE journey_id = $1`, journeyID)
   662				}
   663				return nil
   664			}
