   666			_, _ = tx.ExecContext(ctx, `
   667				UPDATE assignments SET status = 'cancelled'
   668				WHERE journey_id = $1 AND status NOT IN ('completed','delivered','cancelled')`, journeyID)
   669			_, _ = tx.ExecContext(ctx, `DELETE FROM journey_stops WHERE journey_id = $1 AND completed_at IS NULL`, journeyID)
   670			st.releaseJourneyCapacity(ctx, tx, journeyID)
   671			// recreate remaining legs
   672			eta := time.Now().Add(time.Duration(route.TotalMinutes) * time.Minute)
   673			_, _ = tx.ExecContext(ctx, `
   674				UPDATE journeys SET estimated_delivery_at = $1, total_cost_units = $2, replan_status = 'completed', valid = TRUE, status = 'active'
   675				WHERE journey_id = $3`, eta, route.TotalCost, journeyID)
   676			t := time.Now()
   677			seq := 1
