   679				INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
   680				VALUES ($1,$2,'pickup',$3,$4,0)`, journeyID, route.CollectionNode, seq, t); err != nil {
   681				return err
   682			}
   683			_ = st.reserveCapacity(ctx, tx, route.CollectionNode, journeyID, sampleID, styp.RequiresCooled, 1)
   684			maxSeq := 0
   685			_ = tx.QueryRowContext(ctx, `SELECT COALESCE(MAX(sequence),0) FROM assignments WHERE journey_id = $1`, journeyID).Scan(&maxSeq)
   686			asgSeq := maxSeq
   687			for _, hop := range route.Hops {
   688				t = t.Add(time.Duration(hop.Minutes) * time.Minute)
   689				seq++
   690				stopType := "transfer"
   691				if hop.ToID == route.Laboratory {
   692					stopType = "dropoff"
