   493	func (st *Store) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
   494		sess := sessionFrom(r.Context())
   495		if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
   496			writeAPIError(w, err)
