   498		}
   499		var req struct {
   500			JourneyID           string `json:"journeyId"`
   501			ExpectedPlanVersion int    `json:"expectedPlanVersion"`
   502			Reason              string `json:"reason"`
   503			IdempotencyKey      string `json:"idempotencyKey"`
   504		}
   505		if err := decodeJSON(r, &req); err != nil {
   506			writeAPIError(w, err)
   507			return
   508		}
   509		ctx := r.Context()
   510		if req.IdempotencyKey != "" {
   511			hash := hashRequest("cancel", req.JourneyID, itoa(req.ExpectedPlanVersion))
   512			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "cancel", hash)
   513			if err != nil {
   514				writeAPIError(w, err)
   515				return
   516			}
   517			if hit {
   518				replayIdempotent(w, status, body)
   519				return
   520			}
   521		}
   522		if _, err := st.expectPlanVersion(ctx, req.JourneyID, req.ExpectedPlanVersion); err != nil {
   523			writeAPIError(w, err)
   524			return
   525		}
   526		var newVersion int
   527		err := st.tx(ctx, func(tx *sql.Tx) error {
   528			v, err := st.bumpPlan(ctx, tx, req.JourneyID)
   529			if err != nil {
   530				return err
   531			}
   532			newVersion = v
   533			_, _ = tx.ExecContext(ctx, `
   534				UPDATE assignments SET status = 'cancelled'
   535				WHERE journey_id = $1 AND status NOT IN ('completed','delivered','cancelled')`, req.JourneyID)
   536			_, _ = tx.ExecContext(ctx, `UPDATE journeys SET status = 'cancelled' WHERE journey_id = $1`, req.JourneyID)
   537			_, _ = tx.ExecContext(ctx, `
   538				UPDATE samples SET status = 'cancelled'
   539				WHERE sample_id IN (SELECT sample_id FROM journey_samples WHERE journey_id = $1)
   540				  AND status NOT IN ('received','cancelled')`, req.JourneyID)
   541			st.releaseJourneyCapacity(ctx, tx, req.JourneyID)
   542			return nil
   543		})
   544		if err != nil {
   545			writeAPIError(w, err)
   546			return
   547		}
   548		st.audit(ctx, sess, "cancel_journey", "journey", req.JourneyID, true, map[string]any{"reason": req.Reason})
   549		out := map[string]any{"journeyId": req.JourneyID, "planVersion": newVersion, "status": JourneyCancelled}
   550		if req.IdempotencyKey != "" {
   551			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "cancel", hashRequest("cancel", req.JourneyID, itoa(req.ExpectedPlanVersion)), http.StatusOK, out)
   552		}
   553		writeData(w, http.StatusOK, out)
   554	}
