   673			_, _ = tx.ExecContext(ctx, `
   674				UPDATE journeys SET estimated_delivery_at = $1, total_cost_units = $2, replan_status = 'completed', valid = TRUE, status = 'active'
   675				WHERE journey_id = $3`, eta, route.TotalCost, journeyID)
