import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

# dump each operation's request body schema + 200/201 response
for p, methods in spec['paths'].items():
    for m, op in methods.items():
        if m.startswith('x-'): continue
        print('='*80)
        print(f"{m.upper()} {p}  ({op.get('operationId')})")
        if op.get('description'):
            print('DESC:', op['description'][:300])
        if op.get('summary'):
            print('SUM:', op['summary'][:200])
        if 'parameters' in op:
            print('PARAMS:', json.dumps(op['parameters'])[:500])
        if 'requestBody' in op:
            rb = op['requestBody']
            content = rb.get('content',{})
            for ct, c in content.items():
                print('REQ:', json.dumps(c.get('schema',{}), indent=2)[:2500])
        for code in ['200','201']:
            if code in op.get('responses',{}):
                r = op['responses'][code]
                print(f'RESP {code}:', r.get('description',''))
                content = r.get('content',{})
                for ct, c in content.items():
                    print(json.dumps(c.get('schema',{}), indent=2)[:2500])
        # error examples
        for code in ['400','401','403','404','409']:
            if code in op.get('responses',{}):
                r = op['responses'][code]
                content = r.get('content',{})
                for ct, c in content.items():
                    ex = c.get('example') or (c.get('examples') or {})
                    if ex:
                        print(f'ERR {code}:', json.dumps(ex)[:400])
