   137				"entityType": et,
   138				"entityId":   eid,
   139				"payload":    p,
   140				"createdAt":  formatTime(created),
   141			}
   142			b, _ := json.Marshal(evt)
   143			select {
   144			case c.send <- b:
   145				*cursor = id
