    64		var s Session
    65		s.Token = token
    66		err := st.PG.QueryRowContext(ctx, `
    67			SELECT u.user_id, u.username, u.full_name, u.active, s.active_role, u.assigned_location_id
    68			FROM sessions s JOIN users u ON u.user_id = s.user_id
    69			WHERE s.token = $1`, token).Scan(&s.UserID, &s.Username, &s.FullName, &s.Active, &s.ActiveRole, &s.AssignedLoc)
    70		if err == sql.ErrNoRows {
    71			return nil, errJSON("unauthorized", "unauthorized", http.StatusUnauthorized)
    72		}
    73		if err != nil {
    74			return nil, err
    75		}
    76		if !s.Active {
    77			return nil, errJSON("unauthorized", "unauthorized", http.StatusUnauthorized)
    78		}
    79		roles, err := st.loadRoles(ctx, s.UserID)
    80		if err != nil {
    81			return nil, err
    82		}
    83		s.Roles = roles
    84		_, _ = st.PG.ExecContext(ctx, `UPDATE sessions SET last_seen_at = now() WHERE token = $1`, token)
    85		return &s, nil
    86	}
