   191			"sampleId":     sid,
   192			"journeyId":    jid,
   193			"status":       astatus,
   194			"sequence":     seq,
   195			"sampleStatus": sstatus,
   196			"current":      !terminal,
   197		}
   198		if from.Valid {
   199			item["fromLocationId"] = from.String
   200		}
   201		if to.Valid {
   202			item["toLocationId"] = to.String
   203		}
   204		if worker.Valid {
