   498	func (st *Store) listRequesterSamples(ctx context.Context, requesterID string) ([]map[string]any, error) {
   499		rows, err := st.PG.QueryContext(ctx, `
   500			SELECT s.sample_id, s.request_id, s.status, s.serviceability, s.target_laboratory_id,
   501			       r.requested_at, r.delivery_deadline
   502			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
   503			WHERE s.requester_id = $1
   504			ORDER BY r.created_at DESC`, requesterID)
   505		if err != nil {
   506			return nil, err
   507		}
   508		defer rows.Close()
   509		out := []map[string]any{}
   510		for rows.Next() {
   511			var sampleID, requestID, status, svc string
   512			var lab sql.NullString
   513			var requested, deadline time.Time
   514			if err := rows.Scan(&sampleID, &requestID, &status, &svc, &lab, &requested, &deadline); err != nil {
   515				continue
   516			}
   517			out = append(out, map[string]any{
   518				"sampleId":            sampleID,
   519				"requestId":           requestID,
   520				"status":              status,
   521				"serviceability":      svc,
   522				"targetLaboratoryId":  nullStr(lab),
   523				"requestedAt":         formatTime(requested),
   524				"deliveryDeadline":    formatTime(deadline),
   525			})
   526		}
   527		return out, nil
   528	}
