   158				if kind != KindNode && kind != KindTransport && kind != KindCollection {
   159					continue
   160				}
   161			}
   162			if role == RoleLab {
   163				kind, _ := item["kind"].(string)
   164				if kind != KindLaboratory {
   165					continue
   166				}
   167			}
   168			sid, _ := item["sampleId"].(string)
   169			tl, _ := st.loadTimelineForSample(ctx, sid)
   170			item["timeline"] = tl
   171			_ = now
   172			items = append(items, item)
   173		}
   174		return items, nil
   175	}
   176	
   177	func scanWorkItem(rows *sql.Rows, statusFilter string) (map[string]any, bool) {
   178		var aid, sid, jid, kind, astatus, sstatus string
   179		var from, to, worker, offered sql.NullString
   180		var seq int
   181		if err := rows.Scan(&aid, &sid, &jid, &kind, &astatus, &from, &to, &worker, &offered, &seq, &sstatus); err != nil {
   182			return nil, false
   183		}
   184		terminal := astatus == AssignCompleted || astatus == AssignCancelled || astatus == AssignDelivered
   185		if !matchStatus(statusFilter, astatus, terminal) {
   186			return nil, false
   187		}
   188		item := map[string]any{
   189			"kind":         kind,
   190			"assignmentId": aid,
   191			"sampleId":     sid,
   192			"journeyId":    jid,
   193			"status":       astatus,
   194			"sequence":     seq,
   195			"sampleStatus": sstatus,
   196			"current":      !terminal,
   197		}
   198		if from.Valid {
   199			item["fromLocationId"] = from.String
   200		}
   201		if to.Valid {
   202			item["toLocationId"] = to.String
   203		}
   204		if worker.Valid {
   205			item["workerId"] = worker.String
   206		} else if offered.Valid {
   207			item["offeredWorkerId"] = offered.String
   208		}
   209		return item, true
   210	}
   211	
   212	func matchStatus(filter, status string, terminal bool) bool {
   213		if filter == "" {
   214			return true
   215		}
   216		switch filter {
   217		case "current":
   218			return !terminal
   219		case "past", "completed":
   220			return terminal
   221		default:
   222			return status == filter
   223		}
   224	}
   225	
   226	func isTerminal(status string) bool {
   227		switch status {
   228		case SampleReceived, SampleCancelled, SampleExpired:
   229			return true
   230		}
   231		return false
   232	}
