   355		}
   356		var req struct {
   357			WorkerID      string `json:"workerId"`
   358			Available     bool   `json:"available"`
   359			CapacityUnits int    `json:"capacityUnits"`
   360		}
   361		if err := decodeJSON(r, &req); err != nil {
   362			writeAPIError(w, err)
   363			return
   364		}
   365		if req.CapacityUnits < 0 {
   366			writeErr(w, http.StatusBadRequest, "invalid_capacity", "invalid capacity")
