   389	func (st *Store) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
   390		sess := sessionFrom(r.Context())
   391		if err := sess.requireAny(RoleCollection, RoleDelivery, RoleNode, RoleLab, RoleAdministrator, RoleDispatcher); err != nil {
   392			writeAPIError(w, err)
   393			return
   394		}
   395		var req struct {
   396			AssignmentID string     `json:"assignmentId"`
   397			Coordinate   Coordinate `json:"coordinate"`
   398			Sequence     int        `json:"sequence"`
   399			RecordedAt   string     `json:"recordedAt"`
   400		}
   401		if err := decodeJSON(r, &req); err != nil {
   402			writeAPIError(w, err)
   403			return
   404		}
   405		if !validCoord(req.Coordinate) {
   406			writeErr(w, http.StatusBadRequest, "invalid_coordinate", "invalid coordinate")
   407			return
   408		}
   409		if req.Sequence < 1 {
   410			writeErr(w, http.StatusBadRequest, "invalid_sequence", "invalid sequence")
   411			return
   412		}
   413		recordedAt, err := parseTime(req.RecordedAt, "invalid_time")
   414		if err != nil {
   415			writeAPIError(w, err)
   416			return
   417		}
   418		ctx := r.Context()
   419		var exists int
   420		_ = st.PG.QueryRowContext(ctx, `SELECT COUNT(*) FROM assignments WHERE assignment_id = $1`, req.AssignmentID).Scan(&exists)
   421		if exists == 0 {
   422			writeErr(w, http.StatusNotFound, "not_found", "not found")
   423			return
   424		}
   425		var curSeq int
   426		_ = st.PG.QueryRowContext(ctx, `SELECT location_sequence FROM users WHERE user_id = $1`, sess.UserID).Scan(&curSeq)
   427		if req.Sequence <= curSeq {
   428			writeErr(w, http.StatusConflict, "stale_location", "stale location")
   429			return
   430		}
   431		_, err = st.PG.ExecContext(ctx, `
   432			INSERT INTO worker_locations (worker_id, assignment_id, latitude, longitude, sequence, recorded_at)
   433			VALUES ($1,$2,$3,$4,$5,$6)`,
   434			sess.UserID, req.AssignmentID, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, recordedAt)
   435		if err != nil {
   436			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   437			return
   438		}
   439		_, _ = st.PG.ExecContext(ctx, `
   440			UPDATE users SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3, location_sequence = $4
   441			WHERE user_id = $5`,
   442			req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, req.Sequence, sess.UserID)
   443		// propagate to samples currently held by this worker
   444		_, _ = st.PG.ExecContext(ctx, `
   445			UPDATE samples SET latest_lat = $1, latest_lng = $2, location_recorded_at = $3
   446			WHERE current_holder_id = $4`,
   447			req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, sess.UserID)
   448		st.audit(ctx, sess, "record_worker_location", "assignment", req.AssignmentID, true, map[string]any{
   449			"coordinate": req.Coordinate, "sequence": req.Sequence,
   450		})
   451		st.emitEvent(ctx, "worker_location", "worker", sess.UserID, map[string]any{
   452			"assignmentId": req.AssignmentID, "coordinate": req.Coordinate,
   453		}, "")
   454		writeData(w, http.StatusCreated, map[string]any{
   455			"assignmentId": req.AssignmentID,
   456			"coordinate":   req.Coordinate,
   457			"sequence":     req.Sequence,
   458			"recordedAt":   formatTime(recordedAt),
   459		})
   460	}
