   498	func (st *Store) listRequesterSamples(ctx context.Context, requesterID string) ([]map[string]any, error) {
   499		rows, err := st.PG.QueryContext(ctx, `
   500			SELECT s.sample_id, s.request_id, s.status, s.serviceability, s.target_laboratory_id,
   501			       r.requested_at, r.delivery_deadline
   502			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
   503			WHERE s.requester_id = $1
   504			ORDER BY r.created_at DESC`, requesterID)
   505		if err != nil {
   506			return nil, err
   507		}
   508		defer rows.Close()
   509		out := []map[string]any{}
   510		for rows.Next() {
   511			var sampleID, requestID, status, svc string
   512			var lab sql.NullString
   513			var requested, deadline time.Time
   514			if err := rows.Scan(&sampleID, &requestID, &status, &svc, &lab, &requested, &deadline); err != nil {
   515				continue
   516			}
   517			out = append(out, map[string]any{
   518				"sampleId":            sampleID,
   519				"requestId":           requestID,
   520				"status":              status,
   521				"serviceability":      svc,
   522				"targetLaboratoryId":  nullStr(lab),
   523				"requestedAt":         formatTime(requested),
   524				"deliveryDeadline":    formatTime(deadline),
   525			})
   526		}
   527		return out, nil
   528	}
   529	
   530	func (st *Store) handleEvents(w http.ResponseWriter, r *http.Request) {
   531		sess := sessionFrom(r.Context())
   532		since := int64(0)
   533		if q := r.URL.Query().Get("since"); q != "" {
   534			var n int64
   535			if _, err := parseInt64(q, &n); err == nil {
   536				since = n
   537			}
   538		}
   539		upgrade := strings.Contains(strings.ToLower(r.Header.Get("Upgrade")), "websocket")
   540		if upgrade {
   541			st.handleWSEvents(w, r, sess, since)
   542			return
   543		}
   544		ctx := r.Context()
   545		rows, err := st.PG.QueryContext(ctx, `
   546			SELECT id, type, entity_type, entity_id, payload, created_at, audience_role
   547			FROM realtime_events
   548			WHERE id > $1
   549			  AND (audience_role IS NULL OR audience_role = $2)
   550			ORDER BY id ASC
   551			LIMIT 500`, since, sess.ActiveRole)
   552		if err != nil {
   553			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   554			return
   555		}
   556		defer rows.Close()
   557		events := []map[string]any{}
   558		var cursor int64 = since
   559		for rows.Next() {
   560			var id int64
   561			var typ, et, eid string
   562			var payload []byte
   563			var created time.Time
   564			var aud sql.NullString
   565			if err := rows.Scan(&id, &typ, &et, &eid, &payload, &created, &aud); err != nil {
   566				continue
   567			}
   568			var p map[string]any
   569			_ = json.Unmarshal(payload, &p)
   570			if p == nil {
   571				p = map[string]any{}
   572			}
   573			events = append(events, map[string]any{
   574				"id":         id,
   575				"type":       typ,
   576				"entityType": et,
   577				"entityId":   eid,
   578				"payload":    p,
   579				"createdAt":  formatTime(created),
   580			})
   581			cursor = id
   582		}
   583		writeData(w, http.StatusOK, map[string]any{"events": events, "cursor": cursor})
   584	}
   585	
   586	func parseInt64(s string, dest *int64) (int, error) {
   587		var n int64
   588		for _, c := range s {
   589			if c < '0' || c > '9' {
   590				return 0, errJSON("invalid_json", "invalid", 400)
   591			}
   592			n = n*10 + int64(c-'0')
   593		}
   594		*dest = n
   595		return 0, nil
   596	}

