   469	func (st *Store) reserveCapacity(ctx context.Context, tx *sql.Tx, resourceID, journeyID, sampleID string, cooled bool, units int) error {
   470		var capu, resu, ccap, cres int
   471		err := tx.QueryRowContext(ctx, `
   472			SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
   473			FROM capacity_pools WHERE resource_id = $1 FOR UPDATE`, resourceID).
   474			Scan(&capu, &resu, &ccap, &cres)
   475		if err == sql.ErrNoRows {
   476			// unlimited if not configured
   477			_, _ = tx.ExecContext(ctx, `
   478				INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   479				VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   480			return nil
   481		}
   482		if err != nil {
   483			return err
   484		}
   485		if cooled {
   486			if ccap > 0 && cres+units > ccap {
   487				return errJSON("cooled_capacity_exhausted", "cooled capacity exhausted", http.StatusConflict)
   488			}
   489			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = cooled_reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   490		} else {
   491			if capu > 0 && resu+units > capu {
   492				return errJSON("capacity_exhausted", "capacity exhausted", http.StatusConflict)
   493			}
   494			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   495		}
   496		if err != nil {
   497			return err
   498		}
   499		_, err = tx.ExecContext(ctx, `
   500			INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   501			VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   502		return err
