   505	func (st *Store) releaseJourneyCapacity(ctx context.Context, tx *sql.Tx, journeyID string) {
   506		rows, err := tx.QueryContext(ctx, `
   507			SELECT reservation_id, resource_id, cooled, units FROM capacity_reservations
   508			WHERE journey_id = $1 AND active = TRUE`, journeyID)
   509		if err != nil {
   510			return
   511		}
   512		type resv struct {
   513			id, resource string
   514			cooled       bool
   515			units        int
   516		}
   517		var list []resv
   518		for rows.Next() {
   519			var r resv
   520			if err := rows.Scan(&r.id, &r.resource, &r.cooled, &r.units); err == nil {
   521				list = append(list, r)
   522			}
   523		}
   524		rows.Close()
   525		for _, r := range list {
   526			if r.cooled {
   527				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = GREATEST(cooled_reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   528			} else {
   529				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = GREATEST(reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   530			}
   531			_, _ = tx.ExecContext(ctx, `UPDATE capacity_reservations SET active = FALSE WHERE reservation_id = $1`, r.id)
   532		}
   533	}
