   325		if err == sql.ErrNoRows {
   326			writeErr(w, http.StatusNotFound, "not_found", "not found")
   327			return
   328		}
   329		if collectedAt.Before(earliest) || collectedAt.After(latest) {
   330			writeErr(w, http.StatusConflict, "outside_collection_window", "outside collection window")
