   546	func (st *Store) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
   547		sess := sessionFrom(r.Context())
   548		if err := sess.requireAny(RoleAdministrator, RoleDispatcher, RoleNode, RoleLab, RoleDelivery, RoleCollection); err != nil {
   549			writeAPIError(w, err)
   550			return
   551		}
   552		var req struct {
   553			ResourceType   string `json:"resourceType"`
   554			ResourceID     string `json:"resourceId"`
   555			Reason         string `json:"reason"`
   556			OccurredAt     string `json:"occurredAt"`
   557			IdempotencyKey string `json:"idempotencyKey"`
   558		}
   559		if err := decodeJSON(r, &req); err != nil {
   560			writeAPIError(w, err)
   561			return
   562		}
   563		allowed := map[string]bool{"worker": true, "node": true, "route": true, "laboratory": true, "capacity": true}
   564		if !allowed[req.ResourceType] {
   565			writeErr(w, http.StatusBadRequest, "invalid_resource_type", "invalid resource type")
   566			return
   567		}
   568		occurredAt, err := parseTime(req.OccurredAt, "invalid_time")
   569		if err != nil {
   570			writeAPIError(w, err)
   571			return
   572		}
   573		ctx := r.Context()
   574		if req.IdempotencyKey != "" {
   575			hash := hashRequest("disruption", req.ResourceType, req.ResourceID, req.OccurredAt)
   576			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "disruption", hash)
   577			if err != nil {
   578				writeAPIError(w, err)
   579				return
   580			}
   581			if hit {
   582				replayIdempotent(w, status, body)
   583				return
   584			}
   585		}
   586		id := newUUID()
   587		// mark resource unavailable
   588		switch req.ResourceType {
   589		case "worker":
   590			_, _ = st.PG.ExecContext(ctx, `UPDATE users SET available = FALSE WHERE user_id = $1`, req.ResourceID)
   591		case "node", "laboratory":
   592			_, _ = st.PG.ExecContext(ctx, `UPDATE locations SET active = FALSE WHERE location_id = $1`, req.ResourceID)
   593			st.bumpNetwork(ctx, nil)
   594		case "route":
   595			_, _ = st.PG.ExecContext(ctx, `UPDATE connections SET active = FALSE WHERE connection_id = $1`, req.ResourceID)
   596			st.bumpNetwork(ctx, nil)
   597		}
   598		// find affected unfinished journeys
   599		affected := []string{}
   600		var rows *sql.Rows
   601		switch req.ResourceType {
   602		case "worker":
   603			rows, _ = st.PG.QueryContext(ctx, `
   604				SELECT DISTINCT journey_id FROM assignments
   605				WHERE (worker_id = $1 OR offered_worker_id = $1) AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   606		case "node", "laboratory":
   607			rows, _ = st.PG.QueryContext(ctx, `
   608				SELECT DISTINCT journey_id FROM assignments
   609				WHERE (from_location_id = $1 OR to_location_id = $1 OR node_id = $1 OR laboratory_id = $1)
   610				  AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   611		case "route":
   612			rows, _ = st.PG.QueryContext(ctx, `
   613				SELECT DISTINCT a.journey_id FROM assignments a
   614				JOIN connections c ON (c.from_location_id = a.from_location_id AND c.to_location_id = a.to_location_id)
   615				WHERE c.connection_id = $1 AND a.status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   616		case "capacity":
   617			rows, _ = st.PG.QueryContext(ctx, `
   618				SELECT DISTINCT journey_id FROM capacity_reservations WHERE resource_id = $1 AND active = TRUE`, req.ResourceID)
   619		}
   620		if rows != nil {
   621			affected, _ = scanStrings(rows)
   622		}
   623		replan := "not_required"
   624		if len(affected) > 0 {
   625			replan = "completed"
   626			for _, jid := range affected {
   627				_, rs, err := st.replanJourney(ctx, jid)
   628				if err != nil || rs == "failed" || rs == "expired" {
   629					if rs == "expired" {
   630						replan = "expired"
   631					} else if replan != "expired" {
   632						replan = "failed"
   633					}
   634				}
   635			}
   636		}
   637		_, _ = st.PG.ExecContext(ctx, `
   638			INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at, replan_status)
   639			VALUES ($1,$2,$3,$4,$5,$6)`, id, req.ResourceType, req.ResourceID, req.Reason, occurredAt, replan)
   640		st.audit(ctx, sess, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]any{"replanStatus": replan})
   641		out := map[string]any{"disruptionId": id, "replanStatus": replan}
   642		if req.IdempotencyKey != "" {
   643			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "disruption", hashRequest("disruption", req.ResourceType, req.ResourceID, req.OccurredAt), http.StatusCreated, out)
   644		}
   645		writeData(w, http.StatusCreated, out)
   646	}

