   618	func (st *Store) reserveCapacity(ctx context.Context, tx *sql.Tx, resourceID, journeyID, sampleID string, cooled bool, units int) error {
   619		var capu, resu, ccap, cres int
   620		err := tx.QueryRowContext(ctx, `
   621			SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
   622			FROM capacity_pools WHERE resource_id = $1 FOR UPDATE`, resourceID).
   623			Scan(&capu, &resu, &ccap, &cres)
   624		if err == sql.ErrNoRows {
   625			// unlimited if not configured
   626			_, _ = tx.ExecContext(ctx, `
   627				INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   628				VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   629			return nil
   630		}
   631		if err != nil {
   632			return err
   633		}
   634		if cooled {
   635			if ccap > 0 && cres+units > ccap {
   636				return errJSON("cooled_capacity_exhausted", "cooled capacity exhausted", http.StatusConflict)
   637			}
   638			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = cooled_reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   639		} else {
   640			if capu > 0 && resu+units > capu {
   641				return errJSON("capacity_exhausted", "capacity exhausted", http.StatusConflict)
   642			}
   643			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   644		}
   645		if err != nil {
   646			return err
   647		}
   648		_, err = tx.ExecContext(ctx, `
   649			INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   650			VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   651		return err
   652	}
