   654	func (st *Store) releaseJourneyCapacity(ctx context.Context, tx *sql.Tx, journeyID string) {
   655		rows, err := tx.QueryContext(ctx, `
   656			SELECT reservation_id, resource_id, cooled, units FROM capacity_reservations
   657			WHERE journey_id = $1 AND active = TRUE`, journeyID)
   658		if err != nil {
   659			return
   660		}
   661		type resv struct {
   662			id, resource string
   663			cooled       bool
   664			units        int
   665		}
   666		var list []resv
   667		for rows.Next() {
   668			var r resv
   669			if err := rows.Scan(&r.id, &r.resource, &r.cooled, &r.units); err == nil {
   670				list = append(list, r)
   671			}
   672		}
   673		rows.Close()
   674		for _, r := range list {
   675			if r.cooled {
   676				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = GREATEST(cooled_reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   677			} else {
   678				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = GREATEST(reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   679			}
   680			_, _ = tx.ExecContext(ctx, `UPDATE capacity_reservations SET active = FALSE WHERE reservation_id = $1`, r.id)
   681		}
   682	}
