    63	func (st *Store) loadSession(ctx context.Context, token string) (*Session, error) {
    64		var s Session
    65		s.Token = token
    66		err := st.PG.QueryRowContext(ctx, `
    67			SELECT u.user_id, u.username, u.full_name, u.active, s.active_role, u.assigned_location_id
    68			FROM sessions s JOIN users u ON u.user_id = s.user_id
    69			WHERE s.token = $1`, token).Scan(&s.UserID, &s.Username, &s.FullName, &s.Active, &s.ActiveRole, &s.AssignedLoc)
    70		if err == sql.ErrNoRows {
