    88	func (st *Store) authMiddleware(next http.Handler) http.Handler {
    89		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    90			header := r.Header.Get("Authorization")
    91			token := ""
    92			if strings.HasPrefix(strings.ToLower(header), "bearer ") {
    93				token = strings.TrimSpace(header[7:])
    94			}
    95			if token == "" {
    96				writeErr(w, http.StatusUnauthorized, "unauthorized", "unauthorized")
    97				return
    98			}
    99			sess, err := st.loadSession(r.Context(), token)
   100			if err != nil {
   101				writeAPIError(w, err)
   102				return
   103			}
   104			ctx := context.WithValue(r.Context(), sessionKey, sess)
   105			next.ServeHTTP(w, r.WithContext(ctx))
   106		})
   107	}
