    56	func (st *Store) createRequest(w http.ResponseWriter, r *http.Request, sess *Session, req createRequestBody, presealed bool) {
    57		ctx := r.Context()
    58		if req.IdempotencyKey != "" {
    59			hash := hashRequest("create", req.IdempotencyKey, req.SampleTypeID, req.RequestedAt)
    60			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "create_request", hash)
    61			if err != nil {
    62				writeAPIError(w, err)
    63				return
    64			}
    65			if hit {
    66				replayIdempotent(w, status, body)
    67				return
    68			}
    69		}
    70		if !validCoord(req.Origin) {
    71			writeErr(w, http.StatusBadRequest, "invalid_origin", "invalid origin")
    72			return
    73		}
    74		if req.OriginType == "" {
    75			if presealed {
    76				req.OriginType = OriginClinic
    77			} else {
    78				req.OriginType = OriginHome
    79			}
    80		}
    81		if req.OriginType != OriginHome && req.OriginType != OriginClinic && req.OriginType != OriginNode {
    82			writeErr(w, http.StatusBadRequest, "invalid_origin_type", "invalid origin type")
    83			return
    84		}
    85		if presealed && req.OriginType == OriginHome {
    86			writeErr(w, http.StatusBadRequest, "invalid_origin_type", "pre-sealed samples cannot originate at a home")
    87			return
    88		}
    89		requestedAt, err := parseTime(req.RequestedAt, "invalid_time")
    90		if err != nil {
    91			writeAPIError(w, err)
    92			return
    93		}
    94		deadline, err := parseTime(req.DeliveryDeadline, "invalid_deadline")
    95		if err != nil {
    96			writeAPIError(w, err)
    97			return
    98		}
    99		if !deadline.After(requestedAt) {
   100			writeErr(w, http.StatusBadRequest, "invalid_deadline", "invalid deadline")
   101			return
   102		}
   103		earliest := requestedAt
   104		if req.EarliestCollectionAt != "" {
   105			earliest, err = parseTime(req.EarliestCollectionAt, "invalid_collection_window")
   106			if err != nil {
   107				writeAPIError(w, err)
   108				return
   109			}
   110		}
   111		latest := deadline
   112		if req.LatestCollectionAt != "" {
   113			latest, err = parseTime(req.LatestCollectionAt, "invalid_collection_window")
   114			if err != nil {
   115				writeAPIError(w, err)
   116				return
   117			}
   118		}
   119		if latest.Before(earliest) {
   120			writeErr(w, http.StatusBadRequest, "invalid_collection_window", "invalid collection window")
   121			return
   122		}
   123		if req.ContainerType == "" || req.TemperatureMinC > req.TemperatureMaxC {
   124			writeErr(w, http.StatusBadRequest, "invalid_handling_rule", "invalid handling rule")
   125			return
   126		}
   127		styp, err := st.loadSampleType(ctx, req.SampleTypeID)
   128		if err != nil {
   129			writeErr(w, http.StatusNotFound, "not_found", "sample type not found")
   130			return
   131		}
   132		requesterID := sess.UserID
   133		if req.RequesterID != "" && isAdminOrDispatcher(sess.ActiveRole) {
   134			requesterID = req.RequesterID
   135		}
   136		svc, err := st.evaluateServiceability(ctx, req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, requestedAt, deadline, earliest, latest)
   137		if err != nil {
   138			writeAPIError(w, err)
   139			return
   140		}
   141	
   142		requestID := newUUID()
   143		sampleID := newUUID()
   144		status := SampleRequested
   145		svcLabel := "unserviceable"
   146		if svc.Serviceable {
   147			svcLabel = "serviceable"
   148		} else {
   149			status = SampleUnserviceable
   150		}
   151		if presealed {
   152			status = SampleSealed
