   750	func (st *Store) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
   751		sess := sessionFrom(r.Context())
   752		if err := sess.requireAny(RoleAdministrator, RoleDispatcher, RoleNode, RoleLab, RoleDelivery, RoleCollection); err != nil {
   753			writeAPIError(w, err)
   754			return
   755		}
   756		var req struct {
   757			ResourceType   string `json:"resourceType"`
   758			ResourceID     string `json:"resourceId"`
   759			Reason         string `json:"reason"`
   760			OccurredAt     string `json:"occurredAt"`
   761			IdempotencyKey string `json:"idempotencyKey"`
   762		}
   763		if err := decodeJSON(r, &req); err != nil {
   764			writeAPIError(w, err)
   765			return
   766		}
   767		allowed := map[string]bool{"worker": true, "node": true, "route": true, "laboratory": true, "capacity": true}
   768		if !allowed[req.ResourceType] {
   769			writeErr(w, http.StatusBadRequest, "invalid_resource_type", "invalid resource type")
   770			return
   771		}
   772		occurredAt, err := parseTime(req.OccurredAt, "invalid_time")
   773		if err != nil {
   774			writeAPIError(w, err)
   775			return
   776		}
   777		ctx := r.Context()
   778		if req.IdempotencyKey != "" {
   779			hash := hashRequest("disruption", req.ResourceType, req.ResourceID, req.OccurredAt)
   780			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "disruption", hash)
   781			if err != nil {
   782				writeAPIError(w, err)
   783				return
   784			}
   785			if hit {
   786				replayIdempotent(w, status, body)
   787				return
   788			}
   789		}
   790		id := newUUID()
   791		// mark resource unavailable
   792		switch req.ResourceType {
   793		case "worker":
   794			_, _ = st.PG.ExecContext(ctx, `UPDATE users SET available = FALSE WHERE user_id = $1`, req.ResourceID)
   795		case "node", "laboratory":
   796			_, _ = st.PG.ExecContext(ctx, `UPDATE locations SET active = FALSE WHERE location_id = $1`, req.ResourceID)
   797			st.bumpNetwork(ctx, nil)
   798		case "route":
   799			_, _ = st.PG.ExecContext(ctx, `UPDATE connections SET active = FALSE WHERE connection_id = $1`, req.ResourceID)
   800			st.bumpNetwork(ctx, nil)
   801		}
   802		// find affected unfinished journeys
   803		affected := []string{}
   804		var rows *sql.Rows
   805		switch req.ResourceType {
   806		case "worker":
   807			rows, _ = st.PG.QueryContext(ctx, `
   808				SELECT DISTINCT journey_id FROM assignments
   809				WHERE (worker_id = $1 OR offered_worker_id = $1) AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   810		case "node", "laboratory":
   811			rows, _ = st.PG.QueryContext(ctx, `
   812				SELECT DISTINCT journey_id FROM assignments
   813				WHERE (from_location_id = $1 OR to_location_id = $1 OR node_id = $1 OR laboratory_id = $1)
   814				  AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   815		case "route":
   816			rows, _ = st.PG.QueryContext(ctx, `
   817				SELECT DISTINCT a.journey_id FROM assignments a
   818				JOIN connections c ON (c.from_location_id = a.from_location_id AND c.to_location_id = a.to_location_id)
   819				WHERE c.connection_id = $1 AND a.status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   820		case "capacity":
   821			rows, _ = st.PG.QueryContext(ctx, `
   822				SELECT DISTINCT journey_id FROM capacity_reservations WHERE resource_id = $1 AND active = TRUE`, req.ResourceID)
   823		}
   824		if rows != nil {
   825			affected, _ = scanStrings(rows)
   826		}
   827		replan := "not_required"
   828		if len(affected) > 0 {
   829			replan = "completed"
   830			for _, jid := range affected {
   831				_, rs, err := st.replanJourney(ctx, jid)
   832				if err != nil || rs == "failed" || rs == "expired" {
   833					if rs == "expired" {
   834						replan = "expired"
   835					} else if replan != "expired" {
   836						replan = "failed"
   837					}
   838				}
   839			}
   840		}
   841		_, _ = st.PG.ExecContext(ctx, `
   842			INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at, replan_status)
   843			VALUES ($1,$2,$3,$4,$5,$6)`, id, req.ResourceType, req.ResourceID, req.Reason, occurredAt, replan)
   844		st.audit(ctx, sess, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]any{"replanStatus": replan})
   845		out := map[string]any{"disruptionId": id, "replanStatus": replan}
   846		if req.IdempotencyKey != "" {
   847			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "disruption", hashRequest("disruption", req.ResourceType, req.ResourceID, req.OccurredAt), http.StatusCreated, out)
   848		}
   849		writeData(w, http.StatusCreated, out)
   850	}

