   324	func (st *Store) handleCollectAndSeal(w http.ResponseWriter, r *http.Request) {
   325		sess := sessionFrom(r.Context())
   326		if err := sess.requireAny(RoleCollection, RoleAdministrator, RoleDispatcher); err != nil {
   327			writeAPIError(w, err)
   328			return
   329		}
   330		var req struct {
   331			SampleID              string  `json:"sampleId"`
   332			AssignmentID          string  `json:"assignmentId"`
   333			CollectedAt           string  `json:"collectedAt"`
   334			ContainerType         string  `json:"containerType"`
   335			ObservedTemperatureC  float64 `json:"observedTemperatureC"`
   336			IdempotencyKey        string  `json:"idempotencyKey"`
   337		}
   338		if err := decodeJSON(r, &req); err != nil {
   339			writeAPIError(w, err)
   340			return
   341		}
   342		ctx := r.Context()
   343		if req.IdempotencyKey != "" {
   344			hash := hashRequest("seal", req.SampleID, req.AssignmentID)
   345			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "seal", hash)
   346			if err != nil {
   347				writeAPIError(w, err)
   348				return
   349			}
   350			if hit {
   351				replayIdempotent(w, status, body)
   352				return
   353			}
   354		}
   355		collectedAt, err := parseTime(req.CollectedAt, "invalid_time")
   356		if err != nil {
   357			writeAPIError(w, err)
   358			return
   359		}
   360		var earliest, latest time.Time
   361		var originType string
   362		err = st.PG.QueryRowContext(ctx, `
   363			SELECT r.earliest_collection_at, r.latest_collection_at, r.origin_type
   364			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
   365			WHERE s.sample_id = $1`, req.SampleID).Scan(&earliest, &latest, &originType)
   366		if err == sql.ErrNoRows {
   367			writeErr(w, http.StatusNotFound, "not_found", "not found")
   368			return
   369		}
   370		if collectedAt.Before(earliest) || collectedAt.After(latest) {
   371			writeErr(w, http.StatusConflict, "outside_collection_window", "outside collection window")
   372			return
   373		}
   374		var worker sql.NullString
   375		var kind, astatus, asample string
   376		err = st.PG.QueryRowContext(ctx, `
   377			SELECT worker_id, kind, status, sample_id FROM assignments WHERE assignment_id = $1`, req.AssignmentID).
   378			Scan(&worker, &kind, &astatus, &asample)
   379		if err == sql.ErrNoRows || asample != req.SampleID {
   380			writeErr(w, http.StatusNotFound, "not_found", "not found")
   381			return
   382		}
   383		if kind != KindCollection {
   384			writeErr(w, http.StatusConflict, "invalid_assignment", "not a collection assignment")
   385			return
   386		}
   387		if !worker.Valid || worker.String != sess.UserID {
   388			if !isAdminOrDispatcher(sess.ActiveRole) {
   389				writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
   390				return
   391			}
   392		}
   393		var sealed bool
   394		var minT, maxT float64
   395		var reqContainer string
   396		_ = st.PG.QueryRowContext(ctx, `
   397			SELECT s.sealed, r.temperature_min_c, r.temperature_max_c, r.container_type
   398			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
   399			WHERE s.sample_id = $1`, req.SampleID).Scan(&sealed, &minT, &maxT, &reqContainer)
   400		if sealed {
   401			out := map[string]any{"sampleId": req.SampleID, "status": SampleSealed, "sealed": true}
   402			writeData(w, http.StatusOK, out)
   403			return
   404		}
   405		compliant := req.ObservedTemperatureC >= minT && req.ObservedTemperatureC <= maxT
   406		if req.ContainerType != "" && reqContainer != "" && req.ContainerType != reqContainer {
   407			compliant = false
   408		}
   409		status := SampleSealed
   410		var exc any
   411		if !compliant {
   412			status = SampleException
   413			excMap := map[string]any{
   414				"reason":                "handling_checkpoint_failed",
   415				"containerType":         req.ContainerType,
   416				"observedTemperatureC":  req.ObservedTemperatureC,
   417			}
   418			b, _ := json.Marshal(excMap)
   419			exc = b
   420		}
   421		_, err = st.PG.ExecContext(ctx, `
   422			UPDATE samples SET status = $1, sealed = TRUE, sealed_at = $2, current_holder_id = $3, exception = COALESCE($4, exception)
   423			WHERE sample_id = $5`, status, collectedAt, sess.UserID, exc, req.SampleID)
   424		if err != nil {
   425			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   426			return
   427		}
   428		_, _ = st.PG.ExecContext(ctx, `
   429			UPDATE assignments SET status = 'completed', completed_at = $1 WHERE assignment_id = $2`, collectedAt, req.AssignmentID)
   430		_, _ = st.PG.ExecContext(ctx, `
   431			INSERT INTO handling_checkpoints (sample_id, assignment_id, container_type, observed_temperature_c, recorded_at, compliant)
   432			VALUES ($1,$2,$3,$4,$5,$6)`, req.SampleID, req.AssignmentID, req.ContainerType, req.ObservedTemperatureC, collectedAt, compliant)
   433		st.audit(ctx, sess, "collect_and_seal_sample", "sample", req.SampleID, true, map[string]any{"assignmentId": req.AssignmentID})
   434		_, _ = st.writeTimeline(ctx, nil, req.SampleID, "", req.AssignmentID, "collect_and_seal_sample", sess.UserID, sess.ActiveRole, "sample", req.SampleID, true, map[string]any{"sealed": true})
   435		st.emitEvent(ctx, "sample_sealed", "sample", req.SampleID, map[string]any{"status": status}, "")
   436		out := map[string]any{"sampleId": req.SampleID, "status": status, "sealed": true}
   437		if req.IdempotencyKey != "" {
   438			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "seal", hashRequest("seal", req.SampleID, req.AssignmentID), http.StatusOK, out)
   439		}
   440		writeData(w, http.StatusOK, out)
   441	}
