   528	func (st *Store) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
   529		sess := sessionFrom(r.Context())
   530		if err := sess.requireAny(RoleCollection, RoleDelivery, RoleNode, RoleLab, RoleAdministrator, RoleDispatcher); err != nil {
   531			writeAPIError(w, err)
   532			return
   533		}
   534		var req struct {
   535			HandoffID        string `json:"handoffId"`
   536			ConfirmationSide string `json:"confirmationSide"`
   537			ConfirmedAt      string `json:"confirmedAt"`
   538			IdempotencyKey   string `json:"idempotencyKey"`
   539		}
   540		if err := decodeJSON(r, &req); err != nil {
   541			writeAPIError(w, err)
   542			return
   543		}
   544		if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
   545			writeErr(w, http.StatusBadRequest, "invalid_confirmation_side", "invalid confirmation side")
   546			return
   547		}
   548		confirmedAt, err := parseTime(req.ConfirmedAt, "invalid_time")
   549		if err != nil {
   550			writeAPIError(w, err)
   551			return
   552		}
   553		ctx := r.Context()
   554		if req.IdempotencyKey != "" {
   555			hash := hashRequest("confirm_handoff", req.HandoffID, req.ConfirmationSide)
   556			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "confirm_handoff", hash)
   557			if err != nil {
   558				writeAPIError(w, err)
   559				return
   560			}
   561			if hit {
   562				replayIdempotent(w, status, body)
   563				return
   564			}
   565		}
   566		var sampleID, senderID, receiverID, status string
   567		var sConf, rConf bool
   568		err = st.PG.QueryRowContext(ctx, `
   569			SELECT sample_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed
   570			FROM handoffs WHERE handoff_id = $1`, req.HandoffID).
   571			Scan(&sampleID, &senderID, &receiverID, &status, &sConf, &rConf)
   572		if err == sql.ErrNoRows {
   573			writeErr(w, http.StatusNotFound, "not_found", "not found")
   574			return
   575		}
   576		if req.ConfirmationSide == "sender" {
   577			if sess.UserID != senderID && !isAdminOrDispatcher(sess.ActiveRole) {
   578				writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
   579				return
   580			}
   581			sConf = true
   582			_, _ = st.PG.ExecContext(ctx, `UPDATE handoffs SET sender_confirmed = TRUE WHERE handoff_id = $1`, req.HandoffID)
   583		} else {
   584			if sess.UserID != receiverID && !isAdminOrDispatcher(sess.ActiveRole) {
   585				writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
   586				return
   587			}
   588			rConf = true
   589			_, _ = st.PG.ExecContext(ctx, `UPDATE handoffs SET receiver_confirmed = TRUE WHERE handoff_id = $1`, req.HandoffID)
   590		}
   591		final := "pending"
   592		if sConf && rConf {
   593			final = "confirmed"
   594			if status != "confirmed" {
   595				_, _ = st.PG.ExecContext(ctx, `
   596					UPDATE handoffs SET status = 'confirmed', confirmed_at = $1 WHERE handoff_id = $2`, confirmedAt, req.HandoffID)
   597				_, _ = st.PG.ExecContext(ctx, `UPDATE samples SET current_holder_id = $1 WHERE sample_id = $2`, receiverID, sampleID)
   598			}
   599		}
   600		st.audit(ctx, sess, "confirm_handoff", "handoff", req.HandoffID, true, map[string]any{"side": req.ConfirmationSide, "sampleId": sampleID})
   601		_, _ = st.writeTimeline(ctx, nil, sampleID, "", "", "confirm_handoff", sess.UserID, sess.ActiveRole, "handoff", req.HandoffID, true, map[string]any{"side": req.ConfirmationSide, "status": final})
   602		if final == "confirmed" {
   603			st.emitEvent(ctx, "handoff_confirmed", "handoff", req.HandoffID, map[string]any{"sampleId": sampleID, "holderId": receiverID}, "")
   604		}
   605		out := map[string]any{"handoffId": req.HandoffID, "status": final}
   606		if req.IdempotencyKey != "" {
   607			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "confirm_handoff", hashRequest("confirm_handoff", req.HandoffID, req.ConfirmationSide), http.StatusOK, out)
   608		}
   609		writeData(w, http.StatusOK, out)
   610	}
