# Print operationIds and request/response summaries
for path, methods in sorted(spec['paths'].items()):
    for method, op in methods.items():
        if method.startswith('x-'): continue
        print('='*80)
        print(f"{method.upper()} {path}  op={op.get('operationId')}")
        print('summary:', op.get('summary','')[:200])
        if 'parameters' in op:
            for p in op['parameters']:
                print(f"  param {p.get('name')} in={p.get('in')} req={p.get('required')}")
        if 'requestBody' in op:
            rb = op['requestBody']
            content = rb.get('content',{})
            for ct, body in content.items():
                schema = body.get('schema',{})
                print('  requestBody required=', rb.get('required'), 'schema=', json.dumps(schema)[:800])
        for code, resp in op.get('responses',{}).items():
            content = resp.get('content',{})
            for ct, body in content.items():
                schema = body.get('schema',{})
                print(f"  {code} {resp.get('description','')[:80]} schema=", json.dumps(schema)[:600])
