   110	func scanTimeline(rows *sql.Rows) ([]TimelineEntry, error) {
   111		out := []TimelineEntry{}
   112		for rows.Next() {
   113			var e TimelineEntry
   114			var details []byte
   115			var occurred time.Time
   116			if err := rows.Scan(&e.EventID, &e.Action, &e.ActorID, &e.Role, &e.EntityType, &e.EntityID, &e.Success, &occurred, &details); err != nil {
   117				return nil, err
   118			}
   119			e.OccurredAt = formatTime(occurred)
   120			e.Details = map[string]any{}
   121			if len(details) > 0 {
   122				_ = json.Unmarshal(details, &e.Details)
   123			}
   124			out = append(out, e)
   125		}
   126		return out, rows.Err()
   127	}
