   707	func (st *Store) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
   708		sess := sessionFrom(r.Context())
   709		if err := sess.requireAny(RoleAdministrator, RoleDispatcher, RoleNode, RoleLab, RoleDelivery, RoleCollection); err != nil {
   710			writeAPIError(w, err)
   711			return
   712		}
   713		var req struct {
   714			ResourceType   string `json:"resourceType"`
   715			ResourceID     string `json:"resourceId"`
   716			Reason         string `json:"reason"`
   717			OccurredAt     string `json:"occurredAt"`
   718			IdempotencyKey string `json:"idempotencyKey"`
   719		}
   720		if err := decodeJSON(r, &req); err != nil {
   721			writeAPIError(w, err)
   722			return
   723		}
   724		allowed := map[string]bool{"worker": true, "node": true, "route": true, "laboratory": true, "capacity": true}
   725		if !allowed[req.ResourceType] {
   726			writeErr(w, http.StatusBadRequest, "invalid_resource_type", "invalid resource type")
   727			return
   728		}
   729		occurredAt, err := parseTime(req.OccurredAt, "invalid_time")
   730		if err != nil {
   731			writeAPIError(w, err)
   732			return
   733		}
   734		ctx := r.Context()
   735		if req.IdempotencyKey != "" {
   736			hash := hashRequest("disruption", req.ResourceType, req.ResourceID, req.OccurredAt)
   737			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "disruption", hash)
   738			if err != nil {
   739				writeAPIError(w, err)
   740				return
   741			}
   742			if hit {
   743				replayIdempotent(w, status, body)
   744				return
   745			}
   746		}
   747		id := newUUID()
   748		// mark resource unavailable
   749		switch req.ResourceType {
   750		case "worker":
   751			_, _ = st.PG.ExecContext(ctx, `UPDATE users SET available = FALSE WHERE user_id = $1`, req.ResourceID)
   752		case "node", "laboratory":
   753			_, _ = st.PG.ExecContext(ctx, `UPDATE locations SET active = FALSE WHERE location_id = $1`, req.ResourceID)
   754			st.bumpNetwork(ctx, nil)
   755		case "route":
   756			_, _ = st.PG.ExecContext(ctx, `UPDATE connections SET active = FALSE WHERE connection_id = $1`, req.ResourceID)
   757			st.bumpNetwork(ctx, nil)
   758		}
   759		// find affected unfinished journeys
   760		affected := []string{}
   761		var rows *sql.Rows
   762		switch req.ResourceType {
   763		case "worker":
   764			rows, _ = st.PG.QueryContext(ctx, `
   765				SELECT DISTINCT journey_id FROM assignments
   766				WHERE (worker_id = $1 OR offered_worker_id = $1) AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   767		case "node", "laboratory":
   768			rows, _ = st.PG.QueryContext(ctx, `
   769				SELECT DISTINCT journey_id FROM assignments
   770				WHERE (from_location_id = $1 OR to_location_id = $1 OR node_id = $1 OR laboratory_id = $1)
   771				  AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   772		case "route":
   773			rows, _ = st.PG.QueryContext(ctx, `
   774				SELECT DISTINCT a.journey_id FROM assignments a
   775				JOIN connections c ON (c.from_location_id = a.from_location_id AND c.to_location_id = a.to_location_id)
   776				WHERE c.connection_id = $1 AND a.status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   777		case "capacity":
   778			rows, _ = st.PG.QueryContext(ctx, `
   779				SELECT DISTINCT journey_id FROM capacity_reservations WHERE resource_id = $1 AND active = TRUE`, req.ResourceID)
   780		}
   781		if rows != nil {
   782			affected, _ = scanStrings(rows)
   783		}
   784		replan := "not_required"
   785		if len(affected) > 0 {
   786			replan = "completed"
   787			for _, jid := range affected {
   788				_, rs, err := st.replanJourney(ctx, jid)
   789				if err != nil || rs == "failed" || rs == "expired" {
   790					if rs == "expired" {
   791						replan = "expired"
   792					} else if replan != "expired" {
   793						replan = "failed"
   794					}
   795				}
   796			}
   797		}
   798		_, _ = st.PG.ExecContext(ctx, `
   799			INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at, replan_status)
   800			VALUES ($1,$2,$3,$4,$5,$6)`, id, req.ResourceType, req.ResourceID, req.Reason, occurredAt, replan)
   801		st.audit(ctx, sess, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]any{"replanStatus": replan})
   802		out := map[string]any{"disruptionId": id, "replanStatus": replan}
   803		if req.IdempotencyKey != "" {
   804			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "disruption", hashRequest("disruption", req.ResourceType, req.ResourceID, req.OccurredAt), http.StatusCreated, out)
   805		}
   806		writeData(w, http.StatusCreated, out)
   807	}

