   651	func (st *Store) reserveCapacity(ctx context.Context, tx *sql.Tx, resourceID, journeyID, sampleID string, cooled bool, units int) error {
   652		var capu, resu, ccap, cres int
   653		err := tx.QueryRowContext(ctx, `
   654			SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
   655			FROM capacity_pools WHERE resource_id = $1 FOR UPDATE`, resourceID).
   656			Scan(&capu, &resu, &ccap, &cres)
   657		if err == sql.ErrNoRows {
   658			// unlimited if not configured
   659			_, _ = tx.ExecContext(ctx, `
   660				INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   661				VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   662			return nil
   663		}
   664		if err != nil {
   665			return err
   666		}
   667		if cooled {
   668			if ccap > 0 && cres+units > ccap {
   669				return errJSON("cooled_capacity_exhausted", "cooled capacity exhausted", http.StatusConflict)
   670			}
   671			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = cooled_reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   672		} else {
   673			if capu > 0 && resu+units > capu {
   674				return errJSON("capacity_exhausted", "capacity exhausted", http.StatusConflict)
   675			}
   676			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   677		}
   678		if err != nil {
   679			return err
   680		}
   681		_, err = tx.ExecContext(ctx, `
   682			INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   683			VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   684		return err
   685	}
