    45	export async function api<T>(
    46	  path: string,
    47	  opts: { method?: string; body?: unknown; auth?: boolean } = {}
    48	): Promise<T> {
    49	  const headers: Record<string, string> = { "Content-Type": "application/json" };
    50	  if (opts.auth !== false) {
    51	    const t = getToken();
    52	    if (t) headers.Authorization = `Bearer ${t}`;
    53	  }
    54	  const res = await fetch(path, {
    55	    method: opts.method ?? (opts.body ? "POST" : "GET"),
    56	    headers,
    57	    body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
    58	  });
    59	  const json = (await res.json().catch(() => ({}))) as Envelope<T> & {
    60	    error?: string;
    61	    code?: string;
    62	    status?: string;
    63	  };
    64	  if (!res.ok) {
    65	    throw new ApiError(json.code || "error", json.error || res.statusText, res.status);
    66	  }
    67	  if ("data" in json) return json.data as T;
    68	  return json as T;
    69	}
