   641			return nil
   642		}
   643		if err != nil {
   644			return err
   645		}
   646		if cooled {
   647			if ccap > 0 && cres+units > ccap {
   648				return errJSON("cooled_capacity_exhausted", "cooled capacity exhausted", http.StatusConflict)
   649			}
   650			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = cooled_reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
