   666	func (st *Store) releaseJourneyCapacity(ctx context.Context, tx *sql.Tx, journeyID string) {
   667		rows, err := tx.QueryContext(ctx, `
   668			SELECT reservation_id, resource_id, cooled, units FROM capacity_reservations
   669			WHERE journey_id = $1 AND active = TRUE`, journeyID)
   670		if err != nil {
   671			return
   672		}
   673		type resv struct {
   674			id, resource string
   675			cooled       bool
   676			units        int
   677		}
   678		var list []resv
   679		for rows.Next() {
   680			var r resv
   681			if err := rows.Scan(&r.id, &r.resource, &r.cooled, &r.units); err == nil {
   682				list = append(list, r)
   683			}
   684		}
   685		rows.Close()
   686		for _, r := range list {
   687			if r.cooled {
   688				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = GREATEST(cooled_reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   689			} else {
   690				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = GREATEST(reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   691			}
   692			_, _ = tx.ExecContext(ctx, `UPDATE capacity_reservations SET active = FALSE WHERE reservation_id = $1`, r.id)
   693		}
   694	}
