    32	func (st *Store) saveIdempotency(ctx context.Context, userID, key, operation, reqHash string, status int, data any) {
    33		b, _ := json.Marshal(map[string]any{"data": data})
    34		_, _ = st.PG.ExecContext(ctx, `
    35			INSERT INTO idempotency_keys (key, user_id, operation, request_hash, status_code, response_body)
    36			VALUES ($1,$2,$3,$4,$5,$6)
    37			ON CONFLICT (key) DO NOTHING`, key, userID, operation, reqHash, status, b)
    38	}
