    59	func parseTime(s string, code string) (time.Time, error) {
    60		if s == "" {
    61			return time.Time{}, errJSON(code, "invalid time", http.StatusBadRequest)
    62		}
    63		formats := []string{
    64			time.RFC3339Nano,
    65			time.RFC3339,
    66			"2006-01-02T15:04:05Z07:00",
    67			"2006-01-02T15:04:05.000Z07:00",
    68		}
    69		for _, f := range formats {
    70			if t, err := time.Parse(f, s); err == nil {
    71				return t, nil
    72			}
    73		}
    74		return time.Time{}, errJSON(code, "invalid time", http.StatusBadRequest)
    75	}
