   283	func (st *Store) handleCollectAndSeal(w http.ResponseWriter, r *http.Request) {
   284		sess := sessionFrom(r.Context())
   285		if err := sess.requireAny(RoleCollection, RoleAdministrator, RoleDispatcher); err != nil {
   286			writeAPIError(w, err)
   287			return
   288		}
   289		var req struct {
   290			SampleID              string  `json:"sampleId"`
   291			AssignmentID          string  `json:"assignmentId"`
   292			CollectedAt           string  `json:"collectedAt"`
   293			ContainerType         string  `json:"containerType"`
   294			ObservedTemperatureC  float64 `json:"observedTemperatureC"`
   295			IdempotencyKey        string  `json:"idempotencyKey"`
   296		}
   297		if err := decodeJSON(r, &req); err != nil {
   298			writeAPIError(w, err)
   299			return
   300		}
   301		ctx := r.Context()
   302		if req.IdempotencyKey != "" {
   303			hash := hashRequest("seal", req.SampleID, req.AssignmentID)
   304			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "seal", hash)
   305			if err != nil {
   306				writeAPIError(w, err)
   307				return
   308			}
   309			if hit {
   310				replayIdempotent(w, status, body)
   311				return
   312			}
   313		}
   314		collectedAt, err := parseTime(req.CollectedAt, "invalid_time")
   315		if err != nil {
   316			writeAPIError(w, err)
   317			return
   318		}
   319		var earliest, latest time.Time
   320		var originType string
   321		err = st.PG.QueryRowContext(ctx, `
   322			SELECT r.earliest_collection_at, r.latest_collection_at, r.origin_type
   323			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
   324			WHERE s.sample_id = $1`, req.SampleID).Scan(&earliest, &latest, &originType)
   325		if err == sql.ErrNoRows {
   326			writeErr(w, http.StatusNotFound, "not_found", "not found")
   327			return
   328		}
   329		if collectedAt.Before(earliest) || collectedAt.After(latest) {
   330			writeErr(w, http.StatusConflict, "outside_collection_window", "outside collection window")
   331			return
   332		}
   333		var worker sql.NullString
   334		var kind, astatus, asample string
   335		err = st.PG.QueryRowContext(ctx, `
   336			SELECT worker_id, kind, status, sample_id FROM assignments WHERE assignment_id = $1`, req.AssignmentID).
   337			Scan(&worker, &kind, &astatus, &asample)
   338		if err == sql.ErrNoRows || asample != req.SampleID {
   339			writeErr(w, http.StatusNotFound, "not_found", "not found")
   340			return
   341		}
   342		if kind != KindCollection {
   343			writeErr(w, http.StatusConflict, "invalid_assignment", "not a collection assignment")
   344			return
   345		}
   346		if !worker.Valid || worker.String != sess.UserID {
   347			if !isAdminOrDispatcher(sess.ActiveRole) {
   348				writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
   349				return
   350			}
   351		}
   352		var sealed bool
   353		var minT, maxT float64
   354		var reqContainer string
   355		_ = st.PG.QueryRowContext(ctx, `
   356			SELECT s.sealed, r.temperature_min_c, r.temperature_max_c, r.container_type
   357			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
   358			WHERE s.sample_id = $1`, req.SampleID).Scan(&sealed, &minT, &maxT, &reqContainer)
   359		if sealed {
   360			out := map[string]any{"sampleId": req.SampleID, "status": SampleSealed, "sealed": true}
   361			writeData(w, http.StatusOK, out)
   362			return
   363		}
   364		compliant := req.ObservedTemperatureC >= minT && req.ObservedTemperatureC <= maxT
   365		if req.ContainerType != "" && reqContainer != "" && req.ContainerType != reqContainer {
   366			compliant = false
   367		}
   368		status := SampleSealed
   369		var exc any
   370		if !compliant {
   371			status = SampleException
   372			excMap := map[string]any{
   373				"reason":                "handling_checkpoint_failed",
   374				"containerType":         req.ContainerType,
   375				"observedTemperatureC":  req.ObservedTemperatureC,
   376			}
   377			b, _ := json.Marshal(excMap)
   378			exc = b
   379		}
   380		_, err = st.PG.ExecContext(ctx, `
   381			UPDATE samples SET status = $1, sealed = TRUE, sealed_at = $2, current_holder_id = $3, exception = COALESCE($4, exception)
   382			WHERE sample_id = $5`, status, collectedAt, sess.UserID, exc, req.SampleID)
   383		if err != nil {
   384			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   385			return
   386		}
   387		_, _ = st.PG.ExecContext(ctx, `
   388			UPDATE assignments SET status = 'completed', completed_at = $1 WHERE assignment_id = $2`, collectedAt, req.AssignmentID)
   389		_, _ = st.PG.ExecContext(ctx, `
   390			INSERT INTO handling_checkpoints (sample_id, assignment_id, container_type, observed_temperature_c, recorded_at, compliant)
   391			VALUES ($1,$2,$3,$4,$5,$6)`, req.SampleID, req.AssignmentID, req.ContainerType, req.ObservedTemperatureC, collectedAt, compliant)
   392		st.audit(ctx, sess, "collect_and_seal_sample", "sample", req.SampleID, true, map[string]any{"assignmentId": req.AssignmentID})
   393		_, _ = st.writeTimeline(ctx, nil, req.SampleID, "", req.AssignmentID, "collect_and_seal_sample", sess.UserID, sess.ActiveRole, "sample", req.SampleID, true, map[string]any{"sealed": true})
   394		st.emitEvent(ctx, "sample_sealed", "sample", req.SampleID, map[string]any{"status": status}, "")
   395		out := map[string]any{"sampleId": req.SampleID, "status": status, "sealed": true}
   396		if req.IdempotencyKey != "" {
   397			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "seal", hashRequest("seal", req.SampleID, req.AssignmentID), http.StatusOK, out)
   398		}
   399		writeData(w, http.StatusOK, out)
   400	}
