   640				return err
   641			}
   642			newVersion = v
   643			if reason != "serviceable" || route == nil {
   644				replan = "failed"
   645				if reason == "deadline_unreachable" {
   646					replan = "expired"
   647					_, _ = tx.ExecContext(ctx, `UPDATE samples SET status = 'expired' WHERE sample_id = $1 AND status NOT IN ('received','cancelled')`, sampleID)
   648					_, _ = tx.ExecContext(ctx, `UPDATE journeys SET status = 'expired', replan_status = 'expired', valid = FALSE WHERE journey_id = $1`, journeyID)
   649				} else {
   650					_, _ = tx.ExecContext(ctx, `UPDATE journeys SET replan_status = 'failed', valid = FALSE WHERE journey_id = $1`, journeyID)
   651				}
   652				return nil
   653			}
   654			// cancel unfinished assignments and recreate
   655			_, _ = tx.ExecContext(ctx, `
   656				UPDATE assignments SET status = 'cancelled'
   657				WHERE journey_id = $1 AND status NOT IN ('completed','delivered','cancelled')`, journeyID)
   658			_, _ = tx.ExecContext(ctx, `DELETE FROM journey_stops WHERE journey_id = $1 AND completed_at IS NULL`, journeyID)
   659			st.releaseJourneyCapacity(ctx, tx, journeyID)
   660			// recreate remaining legs
   661			eta := time.Now().Add(time.Duration(route.TotalMinutes) * time.Minute)
   662			_, _ = tx.ExecContext(ctx, `
   663				UPDATE journeys SET estimated_delivery_at = $1, total_cost_units = $2, replan_status = 'completed', valid = TRUE, status = 'active'
   664				WHERE journey_id = $3`, eta, route.TotalCost, journeyID)
   665			t := time.Now()
   666			seq := 1
   667			if _, err := tx.ExecContext(ctx, `
   668				INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
   669				VALUES ($1,$2,'pickup',$3,$4,0)`, journeyID, route.CollectionNode, seq, t); err != nil {
   670				return err
   671			}
   672			_ = st.reserveCapacity(ctx, tx, route.CollectionNode, journeyID, sampleID, styp.RequiresCooled, 1)
   673			maxSeq := 0
   674			_ = tx.QueryRowContext(ctx, `SELECT COALESCE(MAX(sequence),0) FROM assignments WHERE journey_id = $1`, journeyID).Scan(&maxSeq)
   675			asgSeq := maxSeq
   676			for _, hop := range route.Hops {
   677				t = t.Add(time.Duration(hop.Minutes) * time.Minute)
   678				seq++
   679				stopType := "transfer"
   680				if hop.ToID == route.Laboratory {
   681					stopType = "dropoff"
   682				}
   683				if _, err := tx.ExecContext(ctx, `
   684					INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
   685					VALUES ($1,$2,$3,$4,$5,0)`, journeyID, hop.ToID, stopType, seq, t); err != nil {
   686					return err
   687				}
   688				_ = st.reserveCapacity(ctx, tx, hop.ConnID, journeyID, sampleID, styp.RequiresCooled, 1)
   689				asgSeq++
   690				worker := st.pickWorkerTx(ctx, tx, KindTransport, "", "", "")
   691				status := AssignOffered
   692				var offered any
   693				var expires any
   694				if worker != "" {
   695					offered = worker
   696					expires = time.Now().Add(offerTTL)
