    13	func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
    14		const r = 6371.0
    15		p1 := lat1 * math.Pi / 180
    16		p2 := lat2 * math.Pi / 180
    17		dlat := (lat2 - lat1) * math.Pi / 180
    18		dlng := (lng2 - lng1) * math.Pi / 180
    19		a := math.Sin(dlat/2)*math.Sin(dlat/2) + math.Cos(p1)*math.Cos(p2)*math.Sin(dlng/2)*math.Sin(dlng/2)
    20		return 2 * r * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
    21	}
