def summarize_schema(s, depth=0):
    if s is None:
        return None
    if '$ref' in s:
        return s['$ref'].split('/')[-1]
    t = s.get('type')
    if t == 'object':
        props = {}
        for k,v in s.get('properties',{}).items():
            props[k] = summarize_schema(v, depth+1)
        req = s.get('required')
        addl = s.get('additionalProperties')
        out = {'type':'object','props':props}
        if req: out['required']=req
        if addl is not None:
            if isinstance(addl, dict):
                out['additionalProperties']=summarize_schema(addl)
            else:
                out['additionalProperties']=addl
        return out
    if t == 'array':
        return {'type':'array','items':summarize_schema(s.get('items'))}
    if 'enum' in s:
        return {'type':t or 'string','enum':s['enum']}
    if t:
        extra = {k:s[k] for k in ('format','nullable','minimum','maximum','minLength','maxLength','description') if k in s}
        extra['type']=t
        return extra
    if 'allOf' in s:
        return {'allOf':[summarize_schema(x) for x in s['allOf']]}
    if 'oneOf' in s:
        return {'oneOf':[summarize_schema(x) for x in s['oneOf']]}
    if 'anyOf' in s:
        return {'anyOf':[summarize_schema(x) for x in s['anyOf']]}
    return s

for p, methods in spec['paths'].items():
