python3 - <<'PY'
import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

# print each operation's request body and responses in compact form
def summarize_schema(s, depth=0):
    if s is None:
        return None
    if '$ref' in s:
        return s['$ref'].split('/')[-1]
    t = s.get('type')
    if t == 'object':
        props = {}
        for k,v in s.get('properties',{}).items():
            props[k] = summarize_schema(v, depth+1)
        req = s.get('required')
        addl = s.get('additionalProperties')
        out = {'type':'object','props':props}
        if req: out['required']=req
        if addl is not None:
            if isinstance(addl, dict):
                out['additionalProperties']=summarize_schema(addl)
            else:
                out['additionalProperties']=addl
        return out
    if t == 'array':
        return {'type':'array','items':summarize_schema(s.get('items'))}
    if 'enum' in s:
        return {'type':t or 'string','enum':s['enum']}
    if t:
        extra = {k:s[k] for k in ('format','nullable','minimum','maximum','minLength','maxLength','description') if k in s}
        extra['type']=t
        return extra
    if 'allOf' in s:
        return {'allOf':[summarize_schema(x) for x in s['allOf']]}
    if 'oneOf' in s:
        return {'oneOf':[summarize_schema(x) for x in s['oneOf']]}
    if 'anyOf' in s:
        return {'anyOf':[summarize_schema(x) for x in s['anyOf']]}
    return s

for p, methods in spec['paths'].items():
    for m, op in methods.items():
        if m.startswith('x-'): continue
        print('='*80)
        print(f"{m.upper()} {p}  op={op.get('operationId')}")
        print('summary:', op.get('summary','')[:200])
        if op.get('parameters'):
            for prm in op['parameters']:
                print('  param', prm.get('name'), prm.get('in'), prm.get('required'), summarize_schema(prm.get('schema')))
        if 'requestBody' in op:
            rb = op['requestBody']
            print('  requestBody required=', rb.get('required'))
            content = rb.get('content',{})
            for ct, cv in content.items():
                print('  content', ct, json.dumps(summarize_schema(cv.get('schema')), default=str)[:2000])
        for code, resp in op.get('responses',{}).items():
            desc = resp.get('description','')[:80]
            content = resp.get('content',{})
            if content:
                for ct, cv in content.items():
                    print(f'  resp {code} {desc}:', json.dumps(summarize_schema(cv.get('schema')), default=str)[:1500])
            else:
                print(f'  resp {code} {desc}')
