import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

def summarize_schema(s, depth=0):
    if s is None:
        return None
    if '$ref' in s:
        return s['$ref'].split('/')[-1]
    t = s.get('type')
    if t == 'object':
        props = {}
        for k,v in s.get('properties',{}).items():
            props[k] = summarize_schema(v, depth+1)
        req = s.get('required')
        out = {'props':props}
        if req: out['required']=req
        return out
    if t == 'array':
        return [summarize_schema(s.get('items'))]
    if 'enum' in s:
        return f"enum{s['enum']}"
    if t:
        return t
    if 'allOf' in s:
        return {'allOf':[summarize_schema(x) for x in s['allOf']]}
    if 'oneOf' in s:
        return {'oneOf':[summarize_schema(x) for x in s['oneOf']]}
    return s

print('=== COMPONENT SCHEMAS ===')
for name, schema in spec['components']['schemas'].items():
