    13			SELECT assignment_id, offered_worker_id, kind, sample_id, journey_id, node_id, laboratory_id
    14			FROM assignments
    15			WHERE status = 'offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < now()`)
    16		if err != nil {
    17			return
    18		}
    19		type exp struct {
    20			asg, worker, kind, sample, journey string
    21			node, lab                          sql.NullString
    22		}
    23		var list []exp
    24		for rows.Next() {
    25			var e exp
    26			if err := rows.Scan(&e.asg, &e.worker, &e.kind, &e.sample, &e.journey, &e.node, &e.lab); err == nil {
    27				list = append(list, e)
    28			}
    29		}
    30		rows.Close()
    31		for _, e := range list {
    32			_, _ = st.PG.ExecContext(ctx, `
    33				INSERT INTO assignment_declines (assignment_id, worker_id, reason)
    34				VALUES ($1,$2,'offer_expired') ON CONFLICT DO NOTHING`, e.asg, e.worker)
    35			st.reoffer(ctx, e.asg, e.kind, e.sample, e.journey, nullStr(e.node), nullStr(e.lab), e.worker)
    36		}
    37	}
