   107		var status, sampleID, kind string
   108		err := st.PG.QueryRowContext(ctx, `
   109			SELECT offered_worker_id, status, sample_id, kind FROM assignments WHERE assignment_id = $1`, req.AssignmentID).
   110			Scan(&offered, &status, &sampleID, &kind)
   111		if err == sql.ErrNoRows {
   112			writeErr(w, http.StatusNotFound, "not_found", "not found")
   113			return
   114		}
   115		if err != nil {
   116			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
