python3 - <<'PY'
import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

# dump remaining operations that were clipped
ops_of_interest = [
    'configure_capacity','configure_laboratory_acceptance','confirm_handoff','confirm_laboratory_receipt',
    'create_collection_request','create_connection','create_location','create_sample_type','create_user',
    'decline_assignment','edit_active_plan','stream_realtime_events','ingest_presealed_sample',
    'initiate_handoff','list_role_work','merge_journeys','read_journey_plan','read_operations_state',
    'read_sample_lifecycle','read_sample_state','read_serviceability_snapshot','read_user',
    'record_handling_checkpoint','record_laboratory_exception','record_worker_location',
    'report_disruption','reroute_journey','search_audit_trail','select_active_role',
    'set_connection_status','set_location_function_status','set_location_status','set_worker_availability',
    'split_journey'
]

def summarize_schema(s):
    if s is None: return None
    if '$ref' in s: return s['$ref'].split('/')[-1]
    t = s.get('type')
    if t == 'object':
        props = {k: summarize_schema(v) for k,v in s.get('properties',{}).items()}
        out = {'props':props}
        if s.get('required'): out['required']=s['required']
        return out
    if t == 'array':
        return [summarize_schema(s.get('items'))]
    if 'enum' in s:
        return f"enum{s['enum']}"
    if t: return t
    if 'allOf' in s: return {'allOf':[summarize_schema(x) for x in s['allOf']]}
    if 'oneOf' in s: return {'oneOf':[summarize_schema(x) for x in s['oneOf']]}
    return s

for p, methods in spec['paths'].items():
    for m, op in methods.items():
        if m.startswith('x-'): continue
        oid = op.get('operationId')
        if oid not in ops_of_interest: continue
        print('='*80)
        print(f"{m.upper()} {p}  op={oid}")
        if op.get('parameters'):
            for prm in op['parameters']:
                print('  param', prm.get('name'), prm.get('in'), prm.get('required'), summarize_schema(prm.get('schema')))
        if 'requestBody' in op:
            rb = op['requestBody']
            content = rb.get('content',{})
            for ct, cv in content.items():
                print('  req', json.dumps(summarize_schema(cv.get('schema')), default=str)[:2500])
        for code, resp in op.get('responses',{}).items():
            content = resp.get('content',{})
            if content:
                for ct, cv in content.items():
                    print(f'  {code}:', json.dumps(summarize_schema(cv.get('schema')), default=str)[:1800])
            else:
                print(f'  {code}: (no content)')
