    19	func errJSON(code, msg string, status int) *apiError {
    20		return &apiError{status: status, code: code, msg: msg}
    21	}
    22	
    23	func writeJSON(w http.ResponseWriter, status int, v any) {
    24		w.Header().Set("Content-Type", "application/json")
    25		w.WriteHeader(status)
    26		_ = json.NewEncoder(w).Encode(v)
    27	}
