    37	func writeAPIError(w http.ResponseWriter, err error) {
    38		if e, ok := err.(*apiError); ok {
    39			writeErr(w, e.status, e.code, e.msg)
    40			return
    41		}
    42		writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
    43	}
