    45	func decodeJSON(r *http.Request, dest any) error {
    46		body, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
    47		if err != nil {
    48			return errJSON("invalid_json", "invalid json", http.StatusBadRequest)
    49		}
    50		if len(strings.TrimSpace(string(body))) == 0 {
    51			return errJSON("invalid_json", "invalid json", http.StatusBadRequest)
    52		}
    53		if err := json.Unmarshal(body, dest); err != nil {
    54			return errJSON("invalid_json", "invalid json", http.StatusBadRequest)
    55		}
    56		return nil
    57	}
