python3 - <<'PY'
import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

print('=== PATHS ===')
for p, methods in spec['paths'].items():
    for m, op in methods.items():
        if m.startswith('x-'): continue
        print(f"{m.upper():6} {p:50} {op.get('operationId')}")

print('\n=== COMPONENTS/SCHEMAS ===')
schemas = spec.get('components',{}).get('schemas',{})
print(list(schemas.keys()))

def summarize_schema(s, depth=0):
    if s is None: return None
    if '$ref' in s: return s['$ref'].split('/')[-1]
    t = s.get('type')
    if t == 'object':
        props = {k: summarize_schema(v, depth+1) for k,v in s.get('properties',{}).items()}
        out = {'props':props}
        if s.get('required'): out['required']=s['required']
        if s.get('additionalProperties') is not None:
            out['additionalProperties']=summarize_schema(s.get('additionalProperties'), depth+1) if isinstance(s.get('additionalProperties'), dict) else s.get('additionalProperties')
        return out
    if t == 'array':
        return [summarize_schema(s.get('items'), depth+1)]
    if 'enum' in s:
        return f"{t or 'enum'}{s['enum']}"
    if t: return t
    if 'allOf' in s: return {'allOf':[summarize_schema(x, depth+1) for x in s['allOf']]}
    if 'oneOf' in s: return {'oneOf':[summarize_schema(x, depth+1) for x in s['oneOf']]}
    return {k:s[k] for k in s if k not in ('description',)}

wanted = ['RoleWork','SampleState','SampleLifecycle','OperationsState','JourneyPlan','RequesterJourneyPlan','WorkerJourneyPlan','RealtimeEvent','Certification','Role','Coordinate','ServiceabilityRegion']
for name in wanted:
    if name in schemas:
        print('\n====', name, '====')
        print(json.dumps(summarize_schema(schemas[name]), indent=2)[:4000])
    else:
        print('\nMISSING', name)
