    15		CheckOrigin: func(r *http.Request) bool { return true },
    16		Subprotocols: []string{"lab-logistics-v1"},
    17	}
    18	
    19	type wsClient struct {
    20		conn   *websocket.Conn
    21		sess   *Session
    22		send   chan []byte
    23		since  int64
    24	}
    25	
    26	type hub struct {
    27		mu      sync.Mutex
    28		clients map[*wsClient]struct{}
    29	}
    30	
    31	func newHub() *hub {
    32		return &hub{clients: map[*wsClient]struct{}{}}
    33	}
    34	
    35	func (h *hub) add(c *wsClient) {
    36		h.mu.Lock()
    37		h.clients[c] = struct{}{}
    38		h.mu.Unlock()
    39	}
    40	
    41	func (h *hub) remove(c *wsClient) {
    42		h.mu.Lock()
    43		delete(h.clients, c)
    44		h.mu.Unlock()
    45	}
    46	
    47	func (st *Store) handleWSEvents(w http.ResponseWriter, r *http.Request, sess *Session, since int64) {
    48		// extract token from subprotocol if middleware already authenticated via header
    49		hdr := http.Header{}
    50		requested := websocket.Subprotocols(r)
    51		chosen := []string{}
    52		for _, p := range requested {
    53			if p == "lab-logistics-v1" || strings.HasPrefix(p, "bearer.") {
    54				chosen = append(chosen, p)
    55			}
    56		}
    57		if len(chosen) > 0 {
    58			hdr.Set("Sec-WebSocket-Protocol", strings.Join(chosen, ", "))
    59		}
    60		conn, err := upgrader.Upgrade(w, r, hdr)
    61		if err != nil {
    62			return
    63		}
    64		c := &wsClient{conn: conn, sess: sess, send: make(chan []byte, 32), since: since}
    65		go c.writePump()
    66		st.replayAndListen(c)
    67	}
    68	
    69	func (c *wsClient) writePump() {
    70		defer c.conn.Close()
    71		ticker := time.NewTicker(25 * time.Second)
    72		defer ticker.Stop()
    73		for {
    74			select {
    75			case msg, ok := <-c.send:
    76				if !ok {
    77					return
    78				}
    79				_ = c.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
    80				if err := c.conn.WriteMessage(websocket.TextMessage, msg); err != nil {
    81					return
    82				}
    83			case <-ticker.C:
    84				_ = c.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
    85				if err := c.conn.WriteMessage(websocket.PingMessage, nil); err != nil {
    86					return
    87				}
    88			}
    89		}
    90	}
    91	
    92	func (st *Store) replayAndListen(c *wsClient) {
    93		defer close(c.send)
    94		cursor := c.since
    95		// initial replay
    96		st.pushEvents(c, &cursor)
    97		ticker := time.NewTicker(1 * time.Second)
    98		defer ticker.Stop()
    99		for {
   100			select {
   101			case <-ticker.C:
   102				if err := st.pushEvents(c, &cursor); err != nil {
   103					return
   104				}
   105			}
   106		}
   107	}
   108	
   109	func (st *Store) pushEvents(c *wsClient, cursor *int64) error {
   110		rows, err := st.PG.Query(`
   111			SELECT id, type, entity_type, entity_id, payload, created_at
   112			FROM realtime_events
   113			WHERE id > $1
   114			  AND (audience_role IS NULL OR audience_role = $2)
   115			ORDER BY id ASC
   116			LIMIT 200`, *cursor, c.sess.ActiveRole)
   117		if err != nil {
   118			return err
   119		}
   120		defer rows.Close()
   121		for rows.Next() {
   122			var id int64
   123			var typ, et, eid string
   124			var payload []byte
   125			var created time.Time
   126			if err := rows.Scan(&id, &typ, &et, &eid, &payload, &created); err != nil {
   127				continue
   128			}
   129			var p map[string]any
   130			_ = json.Unmarshal(payload, &p)
   131			if p == nil {
   132				p = map[string]any{}
   133			}
   134			evt := map[string]any{
   135				"id":         id,
   136				"type":       typ,
   137				"entityType": et,
   138				"entityId":   eid,
   139				"payload":    p,
   140				"createdAt":  formatTime(created),
   141			}
   142			b, _ := json.Marshal(evt)
   143			select {
   144			case c.send <- b:
   145				*cursor = id
   146			default:
   147				return errJSON("internal_error", "slow consumer", 500)
   148			}
   149		}
   150		return nil
   151	}
   152	
   153	func (st *Store) wsAuthMiddleware(next http.Handler) http.Handler {
   154		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
   155			// allow unauthenticated ready; for /api/events try multiple token sources
   156			if r.URL.Path == "/api/events" {
   157				token := bearerFromWS(r, websocket.Subprotocols(r))
   158				if token == "" {
   159					// if this is a websocket upgrade without token, reject
   160					if strings.Contains(strings.ToLower(r.Header.Get("Upgrade")), "websocket") {
   161						writeErr(w, http.StatusUnauthorized, "unauthorized", "unauthorized")
   162						return
   163					}
   164				} else {
   165					sess, err := st.loadSession(r.Context(), token)
   166					if err != nil {
   167						writeAPIError(w, err)
   168						return
   169					}
   170					ctx := contextWithSession(r, sess)
   171					next.ServeHTTP(w, r.WithContext(ctx))
   172					return
   173				}
   174			}
   175			st.authMiddleware(next).ServeHTTP(w, r)
   176		})
   177	}
   178	
   179	func contextWithSession(r *http.Request, sess *Session) context.Context {
   180		return context.WithValue(r.Context(), sessionKey, sess)
