import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

def summarize_schema(s, depth=0):
    if s is None: return None
    if '$ref' in s: return s['$ref'].split('/')[-1]
    t = s.get('type')
    if t == 'object':
        props = {k: summarize_schema(v, depth+1) for k,v in s.get('properties',{}).items()}
        out = {'props':props}
        if s.get('required'): out['required']=s['required']
        if 'additionalProperties' in s:
            out['ap'] = s['additionalProperties'] if not isinstance(s['additionalProperties'], dict) else summarize_schema(s['additionalProperties'])
        return out
    if t == 'array':
        return [summarize_schema(s.get('items'), depth+1)]
    if 'enum' in s:
        return f"{t or 'enum'}{s['enum']}"
    if t: return t
    if 'allOf' in s: return {'allOf':[summarize_schema(x, depth+1) for x in s['allOf']]}
    if 'oneOf' in s: return {'oneOf':[summarize_schema(x, depth+1) for x in s['oneOf']]}
    return s

ops = [
    'collect_and_seal_sample','configure_capacity','configure_laboratory_acceptance','confirm_handoff',
    'confirm_laboratory_receipt','create_collection_request','create_connection','create_location',
    'create_sample_type','create_user','decline_assignment','edit_active_plan','stream_realtime_events',
    'ingest_presealed_sample','initiate_handoff','merge_journeys','read_journey_plan','read_sample_lifecycle',
    'read_serviceability_snapshot','read_user','record_handling_checkpoint','record_laboratory_exception',
    'list_role_work','read_operations_state','read_sample_state'
]
for p, methods in spec['paths'].items():
    for m, op in methods.items():
        if m.startswith('x-'): continue
        oid = op.get('operationId')
        if oid not in ops: continue
        print('='*80)
        print(f"{m.upper()} {p}  op={oid}")
        if op.get('parameters'):
            for prm in op['parameters']:
                print('  param', prm.get('name'), prm.get('in'), prm.get('required'), summarize_schema(prm.get('schema')))
        if 'requestBody' in op:
            rb = op['requestBody']
            content = rb.get('content',{})
            for ct, cv in content.items():
                print('  req', json.dumps(summarize_schema(cv.get('schema')), default=str)[:2500])
        for code, resp in op.get('responses',{}).items():
            if code in ('401','403','404','500','405'): continue
            content = resp.get('content',{})
            if content:
                for ct, cv in content.items():
                    print(f'  {code}:', json.dumps(summarize_schema(cv.get('schema')), default=str)[:2200])
            else:
                print(f'  {code}: (no content)')
