import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

schemas = spec['components']['schemas']
for name in ['RoleWork','RoleWorkItem','SampleWorkItem','JourneyWorkItem','AssignmentWorkItem',
             'OperationsState','SampleState','SampleLifecycle','JourneyPlan','WorkerJourneyPlan',
             'RequesterJourneyPlan','Location','LocationFunctionStates','LocationFunction',
             'Capacity','TimelineEntry','AuditEntry','AuditSearchResult','ServiceabilityRegion',
             'JourneyStop','JourneyLeg','OperationsLocation','OperationsConnection','RealtimeEvent',
             'ErrorEnvelope','Role']:
    print('='*80)
    print(name)
    print(json.dumps(schemas[name], indent=2)[:3500])

print('\n\n===== remaining ops we have not dumped =====')
ops_done = set()
need = ['accept_assignment','authenticate_user','cancel_journey','check_serviceability',
        'record_worker_location','report_disruption','reroute_journey','search_audit_trail',
        'select_active_role','set_connection_status','set_location_function_status',
        'set_location_status','set_worker_availability','split_journey','read_ui_bootstrap',
        'update_assignment_progress','update_location','update_sample_type','update_user_access',
        'system_readiness']

def summarize_schema(s, depth=0):
    if s is None: return None
    if '$ref' in s: return s['$ref'].split('/')[-1]
    t = s.get('type')
    if t == 'object':
        props = {k: summarize_schema(v, depth+1) for k,v in s.get('properties',{}).items()}
        out = {'props':props}
        if s.get('required'): out['required']=s['required']
        return out
    if t == 'array':
        return [summarize_schema(s.get('items'), depth+1)]
    if 'enum' in s:
        return f"{t or 'enum'}{s['enum']}"
    if t: return t
    if 'allOf' in s: return {'allOf':[summarize_schema(x, depth+1) for x in s['allOf']]}
    if 'oneOf' in s: return {'oneOf':[summarize_schema(x, depth+1) for x in s['oneOf']]}
    return s

for p, methods in spec['paths'].items():
    for m, op in methods.items():
        if m.startswith('x-'): continue
        oid = op.get('operationId')
        if oid not in need: continue
        print('='*80)
        print(f"{m.upper()} {p}  op={oid}")
        if op.get('parameters'):
            for prm in op['parameters']:
                print('  param', prm.get('name'), prm.get('in'), prm.get('required'), summarize_schema(prm.get('schema')))
        if 'requestBody' in op:
            rb = op['requestBody']
            content = rb.get('content',{})
            for ct, cv in content.items():
                print('  req', json.dumps(summarize_schema(cv.get('schema')), default=str)[:2500])
        for code, resp in op.get('responses',{}).items():
            if code in ('401','403','404','500','405'): continue
            content = resp.get('content',{})
            if content:
                for ct, cv in content.items():
                    print(f'  {code}:', json.dumps(summarize_schema(cv.get('schema')), default=str)[:2200])
            else:
                print(f'  {code}: (no content)')
