            rb = op['requestBody']
            content = rb.get('content',{})
            for ct, cv in content.items():
                print('  req', json.dumps(summarize_schema(cv.get('schema')), default=str)[:2500])
        for code, resp in op.get('responses',{}).items():
            if code in ('401','403','404','500','405'): continue
            content = resp.get('content',{})
            if content:
                for ct, cv in content.items():
                    print(f'  {code}:', json.dumps(summarize_schema(cv.get('schema')), default=str)[:3000])
            else:
                print(f'  {code}: (no content)')

print('\n\n===== create_user response =====')
op = spec['paths']['/api/create-user']['post']
print(json.dumps(summarize_schema(op['responses']['201']['content']['application/json']['schema']), default=str)[:2000])
print('req', json.dumps(summarize_schema(op['requestBody']['content']['application/json']['schema']), default=str)[:2000])
