   387		if presealed {
   388			// registrar currently holds it; skip collection assignment
   389			_, _ = tx.ExecContext(ctx, `UPDATE samples SET current_holder_id = $1, sealed = TRUE WHERE sample_id = $2`, registrarID, sampleID)
