   344	func (st *Store) evaluateServiceability(ctx context.Context, origin Coordinate, originType, originNodeID, typeID string, requestedAt, deadline, earliest, latest time.Time) (*svcResult, error) {
   345		styp, err := st.loadSampleType(ctx, typeID)
   346		if err != nil {
   347			return nil, errJSON("not_found", "sample type not found", http.StatusNotFound)
   348		}
   349		var version int
   350		_ = st.PG.QueryRowContext(ctx, `SELECT COALESCE(MAX(version),1) FROM serviceability_snapshots`).Scan(&version)
   351		needsCooled := styp.RequiresCooled
   352		route, reason := st.findRoute(ctx, origin.Latitude, origin.Longitude, originType, originNodeID, typeID, needsCooled, deadline, earliest)
   353		res := &svcResult{Reason: reason, ServiceabilityVersion: version, Route: route}
   354		if reason != "serviceable" {
   355			res.Serviceable = false
   356			return res, nil
   357		}
   358		if !st.checkCapacityForRoute(ctx, route, needsCooled) {
   359			res.Serviceable = false
   360			res.Reason = "insufficient_capacity"
   361			return res, nil
   362		}
   363		res.Serviceable = true
   364		res.TargetLaboratoryID = route.Laboratory
   365		res.EstimatedArrivalAt = earliest.Add(time.Duration(route.TotalMinutes) * time.Minute)
   366		return res, nil
   367	}
