   699		}
   700		allowed := map[string]bool{"worker": true, "node": true, "route": true, "laboratory": true, "capacity": true}
   701		if !allowed[req.ResourceType] {
   702			writeErr(w, http.StatusBadRequest, "invalid_resource_type", "invalid resource type")
   703			return
