   717			}
   718			if hit {
   719				replayIdempotent(w, status, body)
   720				return
   721			}
   722		}
   723		id := newUUID()
   724		// mark resource unavailable
   725		switch req.ResourceType {
   726		case "worker":
   727			_, _ = st.PG.ExecContext(ctx, `UPDATE users SET available = FALSE WHERE user_id = $1`, req.ResourceID)
   728		case "node", "laboratory":
   729			_, _ = st.PG.ExecContext(ctx, `UPDATE locations SET active = FALSE WHERE location_id = $1`, req.ResourceID)
   730			st.bumpNetwork(ctx, nil)
   731		case "route":
   732			_, _ = st.PG.ExecContext(ctx, `UPDATE connections SET active = FALSE WHERE connection_id = $1`, req.ResourceID)
   733			st.bumpNetwork(ctx, nil)
   734		}
   735		// find affected unfinished journeys
   736		affected := []string{}
   737		var rows *sql.Rows
   738		switch req.ResourceType {
   739		case "worker":
   740			rows, _ = st.PG.QueryContext(ctx, `
   741				SELECT DISTINCT journey_id FROM assignments
   742				WHERE (worker_id = $1 OR offered_worker_id = $1) AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   743		case "node", "laboratory":
   744			rows, _ = st.PG.QueryContext(ctx, `
   745				SELECT DISTINCT journey_id FROM assignments
   746				WHERE (from_location_id = $1 OR to_location_id = $1 OR node_id = $1 OR laboratory_id = $1)
   747				  AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   748		case "route":
   749			rows, _ = st.PG.QueryContext(ctx, `
   750				SELECT DISTINCT a.journey_id FROM assignments a
   751				JOIN connections c ON (c.from_location_id = a.from_location_id AND c.to_location_id = a.to_location_id)
   752				WHERE c.connection_id = $1 AND a.status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   753		case "capacity":
   754			rows, _ = st.PG.QueryContext(ctx, `
   755				SELECT DISTINCT journey_id FROM capacity_reservations WHERE resource_id = $1 AND active = TRUE`, req.ResourceID)
   756		}
   757		if rows != nil {
   758			affected, _ = scanStrings(rows)
   759		}
   760		replan := "not_required"
   761		if len(affected) > 0 {
   762			replan = "completed"
   763			for _, jid := range affected {
   764				_, rs, err := st.replanJourney(ctx, jid)
   765				if err != nil || rs == "failed" || rs == "expired" {
   766					if rs == "expired" {
   767						replan = "expired"
   768					} else if replan != "expired" {
   769						replan = "failed"
   770					}
   771				}
   772			}
   773		}
   774		_, _ = st.PG.ExecContext(ctx, `
   775			INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at, replan_status)
   776			VALUES ($1,$2,$3,$4,$5,$6)`, id, req.ResourceType, req.ResourceID, req.Reason, occurredAt, replan)
   777		st.audit(ctx, sess, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]any{"replanStatus": replan})
   778		out := map[string]any{"disruptionId": id, "replanStatus": replan}
