   191	func decodeB64URL(s string) (string, error) {
   192		s = strings.TrimSpace(s)
   193		if m := len(s) % 4; m != 0 {
   194			s += strings.Repeat("=", 4-m)
   195		}
   196		b, err := b64URLDecode(s)
   197		if err != nil {
   198			return "", err
   199		}
   200		return string(b), nil
   201	}
