   476			"exceptions":  exceptions,
   477			"journeys":    journeys,
   478			"filters":     filters,
   479			"generatedAt": formatTime(now),
   480		}, nil
   481	}
   482	
   483	func jsonRaw(b []byte) any {
   484		if len(b) == 0 || string(b) == "null" {
   485			return nil
   486		}
   487		var v any
   488		if err := json.Unmarshal(b, &v); err != nil {
   489			return string(b)
   490		}
   491		return v
   492	}
