    81					return
    82				}
    83			case <-ticker.C:
    84				_ = c.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
    85				if err := c.conn.WriteMessage(websocket.PingMessage, nil); err != nil {
    86					return
    87				}
    88			}
    89		}
    90	}
    91	
    92	func (st *Store) replayAndListen(c *wsClient) {
    93		defer close(c.send)
    94		cursor := c.since
    95		// initial replay
    96		st.pushEvents(c, &cursor)
    97		ticker := time.NewTicker(1 * time.Second)
    98		defer ticker.Stop()
    99		for {
   100			select {
   101			case <-ticker.C:
   102				if err := st.pushEvents(c, &cursor); err != nil {
   103					return
   104				}
   105			}
   106		}
   107	}
   108	
   109	func (st *Store) pushEvents(c *wsClient, cursor *int64) error {
   110		rows, err := st.PG.Query(`
   111			SELECT id, type, entity_type, entity_id, payload, created_at
   112			FROM realtime_events
   113			WHERE id > $1
   114			  AND (audience_role IS NULL OR audience_role = $2)
   115			ORDER BY id ASC
   116			LIMIT 200`, *cursor, c.sess.ActiveRole)
   117		if err != nil {
   118			return err
   119		}
   120		defer rows.Close()
   121		for rows.Next() {
   122			var id int64
   123			var typ, et, eid string
   124			var payload []byte
   125			var created time.Time
   126			if err := rows.Scan(&id, &typ, &et, &eid, &payload, &created); err != nil {
   127				continue
   128			}
   129			var p map[string]any
   130			_ = json.Unmarshal(payload, &p)
   131			if p == nil {
   132				p = map[string]any{}
   133			}
   134			evt := map[string]any{
   135				"id":         id,
   136				"type":       typ,
   137				"entityType": et,
   138				"entityId":   eid,
   139				"payload":    p,
   140				"createdAt":  formatTime(created),
   141			}
   142			b, _ := json.Marshal(evt)
   143			select {
   144			case c.send <- b:
   145				*cursor = id
   146			default:
   147				return errJSON("internal_error", "slow consumer", 500)
   148			}
   149		}
   150		return nil
   151	}
   152	
   153	func (st *Store) wsAuthMiddleware(next http.Handler) http.Handler {
   154		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
   155			// allow unauthenticated ready; for /api/events try multiple token sources
   156			if r.URL.Path == "/api/events" {
   157				token := bearerFromWS(r, websocket.Subprotocols(r))
   158				if token == "" {
   159					// if this is a websocket upgrade without token, reject
   160					if strings.Contains(strings.ToLower(r.Header.Get("Upgrade")), "websocket") {
   161						writeErr(w, http.StatusUnauthorized, "unauthorized", "unauthorized")
   162						return
   163					}
   164				} else {
   165					sess, err := st.loadSession(r.Context(), token)
   166					if err != nil {
   167						writeAPIError(w, err)
   168						return
   169					}
   170					ctx := contextWithSession(r, sess)
   171					next.ServeHTTP(w, r.WithContext(ctx))
   172					return
   173				}
   174			}
   175			st.authMiddleware(next).ServeHTTP(w, r)
   176		})
   177	}
   178	
   179	func contextWithSession(r *http.Request, sess *Session) context.Context {
   180		return context.WithValue(r.Context(), sessionKey, sess)
   181	}
