   557	func (st *Store) reserveCapacity(ctx context.Context, tx *sql.Tx, resourceID, journeyID, sampleID string, cooled bool, units int) error {
   558		var capu, resu, ccap, cres int
   559		err := tx.QueryRowContext(ctx, `
   560			SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
   561			FROM capacity_pools WHERE resource_id = $1 FOR UPDATE`, resourceID).
   562			Scan(&capu, &resu, &ccap, &cres)
   563		if err == sql.ErrNoRows {
   564			// unlimited if not configured
   565			_, _ = tx.ExecContext(ctx, `
   566				INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   567				VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   568			return nil
   569		}
   570		if err != nil {
   571			return err
   572		}
   573		if cooled {
   574			if ccap > 0 && cres+units > ccap {
   575				return errJSON("cooled_capacity_exhausted", "cooled capacity exhausted", http.StatusConflict)
   576			}
   577			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = cooled_reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   578		} else {
   579			if capu > 0 && resu+units > capu {
   580				return errJSON("capacity_exhausted", "capacity exhausted", http.StatusConflict)
   581			}
   582			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   583		}
   584		if err != nil {
   585			return err
   586		}
   587		_, err = tx.ExecContext(ctx, `
   588			INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   589			VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   590		return err
