   593	func (st *Store) releaseJourneyCapacity(ctx context.Context, tx *sql.Tx, journeyID string) {
   594		rows, err := tx.QueryContext(ctx, `
   595			SELECT reservation_id, resource_id, cooled, units FROM capacity_reservations
   596			WHERE journey_id = $1 AND active = TRUE`, journeyID)
   597		if err != nil {
   598			return
   599		}
   600		type resv struct {
   601			id, resource string
   602			cooled       bool
   603			units        int
   604		}
   605		var list []resv
   606		for rows.Next() {
   607			var r resv
   608			if err := rows.Scan(&r.id, &r.resource, &r.cooled, &r.units); err == nil {
   609				list = append(list, r)
   610			}
   611		}
   612		rows.Close()
   613		for _, r := range list {
   614			if r.cooled {
   615				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = GREATEST(cooled_reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   616			} else {
   617				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = GREATEST(reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   618			}
   619			_, _ = tx.ExecContext(ctx, `UPDATE capacity_reservations SET active = FALSE WHERE reservation_id = $1`, r.id)
   620		}
   621	}
