    13		var req struct {
    14			Username string `json:"username"`
    15			Password string `json:"password"`
    16		}
    17		if err := decodeJSON(r, &req); err != nil {
    18			writeAPIError(w, err)
    19			return
    20		}
    21		ctx := r.Context()
    22		var userID, hash string
    23		var active bool
    24		err := st.PG.QueryRowContext(ctx, `SELECT user_id, password_hash, active FROM users WHERE username = $1`, req.Username).
    25			Scan(&userID, &hash, &active)
    26		if err == sql.ErrNoRows || !checkPassword(hash, req.Password) || !active {
    27			st.writeAudit(ctx, "", "", "authenticate_user", "user", req.Username, false, map[string]any{"reason": "invalid_credentials"})
    28			writeErr(w, http.StatusUnauthorized, "invalid_credentials", "invalid credentials")
    29			return
    30		}
    31		if err != nil {
    32			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
    33			return
    34		}
    35		roles, err := st.loadRoles(ctx, userID)
    36		if err != nil {
    37			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
    38			return
    39		}
    40		token := newToken()
    41		activeRole := ""
    42		if len(roles) == 1 {
    43			activeRole = roles[0]
    44		}
    45		_, err = st.PG.ExecContext(ctx, `INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,$3)`, token, userID, activeRole)
    46		if err != nil {
    47			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
    48			return
    49		}
    50		st.writeAudit(ctx, userID, activeRole, "authenticate_user", "user", userID, true, map[string]any{"username": req.Username})
    51		_, _ = st.writeTimeline(ctx, nil, "", "", "", "authenticate_user", userID, activeRole, "user", userID, true, map[string]any{"username": req.Username})
    52		writeData(w, http.StatusOK, map[string]any{
    53			"sessionToken": token,
    54			"userId":       userID,
    55			"roles":        roles,
    56			"activeRole":   activeRole,
    57		})
    58	}
