   147				VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
   148				id, req.Username, hash, req.Email, req.FullName, req.Phone, req.Active, loc); err != nil {
   149				return err
   150			}
   151			for _, role := range uniqStrings(req.Roles) {
