   153					return err
   154				}
   155			}
   156			for _, q := range uniqStrings(req.Qualifications) {
   157				if _, err := tx.ExecContext(ctx, `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2)`, id, q); err != nil {
   158					return err
   159				}
   160			}
   161			for _, c := range req.Certifications {
