   180				writeAPIError(w, e)
   181				return
   182			}
   183			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   184			return
   185		}
   186		data, _ := st.userPayload(ctx, id)
   187		st.audit(ctx, sess, "create_user", "user", id, true, map[string]any{"username": req.Username})
   188		writeData(w, http.StatusCreated, data)
   189	}
