   395		var sealed bool
   396		var holder, target, recvLab sql.NullString
   397		var sealedAt, recvAt, locAt sql.NullTime
   398		var lat, lng sql.NullFloat64
   399		var exc []byte
   400		err := st.PG.QueryRowContext(ctx, `
   401			SELECT request_id, requester_id, sample_type_id, status, sealed, sealed_at, current_holder_id,
   402			       target_laboratory_id, received_laboratory_id, received_at, serviceability, serviceability_reason,
   403			       latest_lat, latest_lng, location_recorded_at, exception
   404			FROM samples WHERE sample_id = $1`, sampleID).
   405			Scan(&requestID, &requesterID, &typeID, &status, &sealed, &sealedAt, &holder, &target, &recvLab, &recvAt,
   406				&svc, &svcReason, &lat, &lng, &locAt, &exc)
