   423			FROM collection_requests WHERE request_id = $1`, requestID).
   424			Scan(&originLat, &originLng, &originType, &originNode, &requested, &deadline, &earliest, &latest)
   425	
   426		now := time.Now().UTC()
   427		var rec *time.Time
   428		if locAt.Valid {
