   439				excObj = m
   440			}
   441		}
   442		var journeyID sql.NullString
   443		_ = st.PG.QueryRowContext(ctx, `
   444			SELECT js.journey_id FROM journey_samples js
   445			JOIN journeys j ON j.journey_id = js.journey_id
   446			WHERE js.sample_id = $1 AND j.active = TRUE
   447			ORDER BY j.plan_version DESC LIMIT 1`, sampleID).Scan(&journeyID)
   448	
   449		return map[string]any{
   450			"sampleId":             sampleID,
   451			"requestId":            requestID,
   452			"status":               status,
   453			"currentHolderId":      nullStr(holder),
   454			"latestCoordinate":     coord,
   455			"locationRecordedAt":   formatTimePtr(rec),
   456			"locationStale":        isLocationStale(rec, now),
   457			"sealed":               sealed,
   458			"serviceability":       svc,
   459			"serviceabilityReason": svcReason,
   460			"targetLaboratoryId":   nullStr(target),
   461			"receivedLaboratoryId": nullStr(recvLab),
   462			"exception":            excObj,
   463			"journeyId":            nullStr(journeyID),
   464			"origin":               Coordinate{Latitude: originLat, Longitude: originLng},
   465			"originType":           originType,
   466			"deliveryDeadline":     formatTime(deadline),
   467		}, nil
   468	}
