   304	func (st *Store) checkCapacityForRoute(ctx context.Context, route *plannedRoute, cooled bool) bool {
   305		if route == nil {
   306			return false
   307		}
   308		check := func(id string) bool {
   309			c := st.getCapacity(ctx, id)
   310			if cooled {
   311				if c.CooledCapacityUnits > 0 && c.CooledAvailableUnits < 1 {
   312					return false
   313				}
   314			} else {
   315				if c.CapacityUnits > 0 && c.AvailableUnits < 1 {
   316					return false
   317				}
   318			}
   319			return true
   320		}
   321		if !check(route.CollectionNode) {
   322			return false
   323		}
   324		if !check(route.Laboratory) {
   325			return false
   326		}
   327		for _, h := range route.Hops {
   328			if !check(h.ConnID) {
   329				return false
   330			}
   331		}
   332		return true
   333	}
