   153	func (st *Store) wsAuthMiddleware(next http.Handler) http.Handler {
   154		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
   155			// allow unauthenticated ready; for /api/events try multiple token sources
   156			if r.URL.Path == "/api/events" {
   157				token := bearerFromWS(r, websocket.Subprotocols(r))
   158				if token == "" {
   159					// if this is a websocket upgrade without token, reject
   160					if strings.Contains(strings.ToLower(r.Header.Get("Upgrade")), "websocket") {
   161						writeErr(w, http.StatusUnauthorized, "unauthorized", "unauthorized")
   162						return
   163					}
   164				} else {
   165					sess, err := st.loadSession(r.Context(), token)
   166					if err != nil {
   167						writeAPIError(w, err)
   168						return
   169					}
   170					ctx := contextWithSession(r, sess)
   171					next.ServeHTTP(w, r.WithContext(ctx))
   172					return
   173				}
   174			}
   175			st.authMiddleware(next).ServeHTTP(w, r)
   176		})
   177	}
   178	
   179	func contextWithSession(r *http.Request, sess *Session) context.Context {
   180		return context.WithValue(r.Context(), sessionKey, sess)
   181	}
