   390			hash := hashRequest("merge", req.TargetJourneyID, itoa(req.ExpectedPlanVersion))
   391			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "merge", hash)
   392			if err != nil {
   393				writeAPIError(w, err)
   394				return
   395			}
   396			if hit {
   397				replayIdempotent(w, status, body)
   398				return
   399			}
   400		}
   401		if _, err := st.expectPlanVersion(ctx, req.TargetJourneyID, req.ExpectedPlanVersion); err != nil {
   402			writeAPIError(w, err)
   403			return
   404		}
   405		// validate compatibility of samples
   406		if err := st.validateMerge(ctx, req.TargetJourneyID, req.SourceJourneyIDs); err != nil {
   407			writeAPIError(w, err)
   408			return
   409		}
   410		var newVersion int
   411		err := st.tx(ctx, func(tx *sql.Tx) error {
   412			v, err := st.bumpPlan(ctx, tx, req.TargetJourneyID)
   413			if err != nil {
   414				return err
   415			}
   416			newVersion = v
   417			for _, src := range req.SourceJourneyIDs {
   418				sids, _ := st.journeySampleIDs(ctx, src)
   419				for _, sid := range sids {
   420					_, _ = tx.ExecContext(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.TargetJourneyID, sid)
   421					_, _ = tx.ExecContext(ctx, `
   422						UPDATE assignments SET journey_id = $1
   423						WHERE journey_id = $2 AND sample_id = $3 AND status NOT IN ('completed','delivered','cancelled')`,
   424						req.TargetJourneyID, src, sid)
   425				}
   426				_, _ = tx.ExecContext(ctx, `UPDATE journeys SET active = FALSE, status = 'replaced' WHERE journey_id = $1`, src)
   427			}
   428			_, _ = tx.ExecContext(ctx, `UPDATE journeys SET route_mode = 'batched' WHERE journey_id = $1`, req.TargetJourneyID)
   429			return nil
   430		})
   431		if err != nil {
   432			writeAPIError(w, err)
   433			return
   434		}
   435		st.audit(ctx, sess, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]any{"sources": req.SourceJourneyIDs})
   436		out := map[string]any{"journeyId": req.TargetJourneyID, "planVersion": newVersion}
   437		if req.IdempotencyKey != "" {
