    10	func (st *Store) checkIdempotency(ctx context.Context, userID, key, operation, reqHash string) (hit bool, status int, body []byte, err error) {
    11		if key == "" {
    12			return false, 0, nil, errJSON("idempotency_required", "idempotency key required", http.StatusBadRequest)
    13		}
    14		var storedHash string
    15		var storedStatus int
    16		var storedBody []byte
    17		qerr := st.PG.QueryRowContext(ctx, `
    18			SELECT request_hash, status_code, response_body FROM idempotency_keys
    19			WHERE key = $1`, key).Scan(&storedHash, &storedStatus, &storedBody)
    20		if qerr == sql.ErrNoRows {
    21			return false, 0, nil, nil
    22		}
    23		if qerr != nil {
    24			return false, 0, nil, qerr
    25		}
    26		if storedHash != reqHash {
    27			return false, 0, nil, errJSON("idempotency_conflict", "idempotency conflict", http.StatusConflict)
    28		}
    29		return true, storedStatus, storedBody, nil
    30	}
    31	
    32	func (st *Store) saveIdempotency(ctx context.Context, userID, key, operation, reqHash string, status int, data any) {
    33		b, _ := json.Marshal(map[string]any{"data": data})
    34		_, _ = st.PG.ExecContext(ctx, `
    35			INSERT INTO idempotency_keys (key, user_id, operation, request_hash, status_code, response_body)
    36			VALUES ($1,$2,$3,$4,$5,$6)
    37			ON CONFLICT (key) DO NOTHING`, key, userID, operation, reqHash, status, b)
    38	}
    39	
    40	func replayIdempotent(w http.ResponseWriter, status int, body []byte) {
    41		w.Header().Set("Content-Type", "application/json")
    42		w.WriteHeader(status)
    43		_, _ = w.Write(body)
    44	}
    45	
    46	func hashRequest(parts ...string) string {
    47		return hashIdem(joinParts(parts))
    48	}
    49	
    50	func joinParts(parts []string) string {
    51		out := ""
    52		for i, p := range parts {
    53			if i > 0 {
    54				out += "|"
    55			}
    56			out += p
    57		}
    58		return out
    59	}
