   340	func (st *Store) reserveCapacity(ctx context.Context, tx *sql.Tx, resourceID, journeyID, sampleID string, cooled bool, units int) error {
   341		var capu, resu, ccap, cres int
   342		err := tx.QueryRowContext(ctx, `
   343			SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
   344			FROM capacity_pools WHERE resource_id = $1 FOR UPDATE`, resourceID).
   345			Scan(&capu, &resu, &ccap, &cres)
   346		if err == sql.ErrNoRows {
   347			// unlimited if not configured
   348			_, _ = tx.ExecContext(ctx, `
   349				INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   350				VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   351			return nil
   352		}
   353		if err != nil {
   354			return err
   355		}
   356		if cooled {
   357			if ccap > 0 && cres+units > ccap {
   358				return errJSON("cooled_capacity_exhausted", "cooled capacity exhausted", http.StatusConflict)
   359			}
   360			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = cooled_reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   361		} else {
   362			if capu > 0 && resu+units > capu {
   363				return errJSON("capacity_exhausted", "capacity exhausted", http.StatusConflict)
   364			}
   365			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   366		}
   367		if err != nil {
   368			return err
   369		}
   370		_, err = tx.ExecContext(ctx, `
   371			INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   372			VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   373		return err
   374	}
