import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)

# remaining ops that were clipped
for oid in ['ingest_presealed_sample','initiate_handoff','merge_journeys','record_handling_checkpoint','record_laboratory_exception','record_worker_location','report_disruption','reroute_journey','search_audit_trail','read_serviceability_snapshot','read_user']:
    for path, methods in spec['paths'].items():
        for m, op in methods.items():
            if op.get('operationId')==oid:
                print('\n##', oid, m.upper(), path)
                if 'requestBody' in op:
                    rb = op['requestBody']
                    content = rb.get('content',{}).get('application/json',{})
                    print(' req', json.dumps(content.get('schema'), indent=2)[:2000])
                for code, resp in op.get('responses',{}).items():
                    if code.startswith('2'):
                        c = resp.get('content',{}).get('application/json',{})
                        print(' ', code, json.dumps(c.get('schema'), indent=2)[:2000])

print('\n==== ALL SUCCESS CODES ====')
for path, methods in spec['paths'].items():
    for m, op in methods.items():
        codes = [c for c in op.get('responses',{}) if c.startswith('2') or c=='101']
        print(f"{op.get('operationId'):40} {m.upper():6} {path:45} {codes}")
