   266			       s.location_recorded_at, s.sealed, s.serviceability, s.target_laboratory_id, s.exception,
   267			       st.name
   268			FROM samples s JOIN sample_types st ON st.sample_type_id = s.sample_type_id
   269			ORDER BY s.created_at DESC LIMIT 500`)
   270		if err != nil {
   271			return nil, err
