   237			writeAPIError(w, err)
   238			return
   239		}
   240		filters := ""
   241		if r.Method == http.MethodPost && r.ContentLength > 0 {
   242			var body struct {
   243				Filters string `json:"filters"`
   244			}
   245			if err := decodeJSON(r, &body); err != nil {
   246				writeAPIError(w, err)
   247				return
   248			}
   249			filters = body.Filters
   250		}
   251		data, err := st.buildOperationsState(r.Context(), filters)
   252		if err != nil {
   253			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   254			return
   255		}
   256		writeData(w, http.StatusOK, data)
   257	}
   258	
   259	func (st *Store) buildOperationsState(ctx context.Context, filters string) (map[string]any, error) {
   260		now := time.Now().UTC()
   261		st.expireOffers(ctx)
   262	
   263		samples := []map[string]any{}
   264		srows, err := st.PG.QueryContext(ctx, `
   265			SELECT s.sample_id, s.request_id, s.status, s.current_holder_id, s.latest_lat, s.latest_lng,
   266			       s.location_recorded_at, s.sealed, s.serviceability, s.target_laboratory_id, s.exception,
   267			       st.name
   268			FROM samples s JOIN sample_types st ON st.sample_type_id = s.sample_type_id
   269			ORDER BY s.created_at DESC LIMIT 500`)
   270		if err != nil {
   271			return nil, err
   272		}
   273		for srows.Next() {
   274			var sid, rid, status, svc, typeName string
   275			var holder, target sql.NullString
   276			var lat, lng sql.NullFloat64
   277			var locAt sql.NullTime
   278			var sealed bool
   279			var exc []byte
   280			if err := srows.Scan(&sid, &rid, &status, &holder, &lat, &lng, &locAt, &sealed, &svc, &target, &exc, &typeName); err != nil {
   281				continue
   282			}
   283			var rec *time.Time
   284			if locAt.Valid {
   285				rec = &locAt.Time
   286			}
   287			var coord any
   288			if lat.Valid && lng.Valid {
   289				coord = Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
   290			}
   291			samples = append(samples, map[string]any{
   292				"sampleId":           sid,
   293				"requestId":          rid,
   294				"status":             status,
   295				"currentHolderId":    nullStr(holder),
   296				"latestCoordinate":   coord,
   297				"locationRecordedAt": formatTimePtr(rec),
   298				"locationStale":      isLocationStale(rec, now),
   299				"sealed":             sealed,
   300				"serviceability":     svc,
   301				"targetLaboratoryId": nullStr(target),
   302				"sampleTypeName":     typeName,
   303			})
   304		}
   305		srows.Close()
   306	
   307		workers := []map[string]any{}
   308		wrows, err := st.PG.QueryContext(ctx, `
   309			SELECT u.user_id, u.username, u.full_name, u.available, u.capacity_units,
   310			       u.latest_lat, u.latest_lng, u.location_recorded_at, u.assigned_location_id
   311			FROM users u
   312			WHERE EXISTS (
   313			  SELECT 1 FROM user_roles ur WHERE ur.user_id = u.user_id
   314			    AND ur.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team')
   315			)`)
   316		if err == nil {
   317			defer wrows.Close()
   318			for wrows.Next() {
   319				var uid, uname, fname string
   320				var avail bool
   321				var cap int
   322				var lat, lng sql.NullFloat64
   323				var locAt sql.NullTime
   324				var assigned sql.NullString
   325				if err := wrows.Scan(&uid, &uname, &fname, &avail, &cap, &lat, &lng, &locAt, &assigned); err != nil {
   326					continue
   327				}
   328				roles, _ := st.loadRoles(ctx, uid)
   329				var rec *time.Time
   330				if locAt.Valid {
   331					rec = &locAt.Time
   332				}
   333				var coord any
   334				if lat.Valid && lng.Valid {
   335					coord = Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
   336				}
   337				open := 0
   338				_ = st.PG.QueryRowContext(ctx, `
   339					SELECT COUNT(*) FROM assignments
   340					WHERE (worker_id = $1 OR offered_worker_id = $1)
   341					  AND status IN ('offered','accepted','in_progress','pending','at_pickup','picked_up','in_transit','arrived')`, uid).Scan(&open)
   342				workers = append(workers, map[string]any{
   343					"userId":             uid,
   344					"username":           uname,
   345					"fullName":           fname,
   346					"roles":              roles,
   347					"available":          avail,
   348					"capacityUnits":      cap,
   349					"openAssignments":    open,
   350					"latestCoordinate":   coord,
   351					"locationRecordedAt": formatTimePtr(rec),
   352					"locationStale":      isLocationStale(rec, now),
   353					"assignedLocationId": nullStr(assigned),
   354				})
   355			}
   356		}
   357	
   358		locations := []map[string]any{}
   359		lrows, err := st.PG.QueryContext(ctx, `
   360			SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active,
   361			       fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory
   362			FROM locations`)
   363		if err == nil {
   364			defer lrows.Close()
   365			for lrows.Next() {
   366				var id, name string
   367				var lat, lng, cov float64
   368				var handling int
   369				var active bool
   370				var f LocationFunctions
   371				if err := lrows.Scan(&id, &name, &lat, &lng, &cov, &handling, &active, &f.CollectionPoint, &f.TransferPoint, &f.Hub, &f.Laboratory); err != nil {
   372					continue
   373				}
   374				cap := st.getCapacity(ctx, id)
   375				locations = append(locations, map[string]any{
   376					"locationId":      id,
   377					"name":            name,
   378					"coordinate":      Coordinate{Latitude: lat, Longitude: lng},
   379					"coverageKm":      cov,
   380					"handlingMinutes": handling,
   381					"active":          active,
   382					"functions":       f,
   383					"capacity":        cap,
   384				})
   385			}
   386		}
   387	
   388		connections := []map[string]any{}
   389		crows, err := st.PG.QueryContext(ctx, `
   390			SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active
   391			FROM connections`)
   392		if err == nil {
   393			defer crows.Close()
   394			for crows.Next() {
   395				var id, from, to string
   396				var minutes int
   397				var cost float64
   398				var cooled, active bool
   399				if err := crows.Scan(&id, &from, &to, &minutes, &cost, &cooled, &active); err != nil {
   400					continue
   401				}
   402				cap := st.getCapacity(ctx, id)
   403				connections = append(connections, map[string]any{
   404					"connectionId":   id,
   405					"fromLocationId": from,
   406					"toLocationId":   to,
   407					"travelMinutes":  minutes,
   408					"costUnits":      cost,
   409					"cooled":         cooled,
   410					"active":         active,
   411					"capacity":       cap,
   412				})
   413			}
   414		}
   415	
   416		exceptions := []map[string]any{}
   417		erows, err := st.PG.QueryContext(ctx, `
   418			SELECT sample_id, status, exception FROM samples
   419			WHERE status IN ('exception','expired','unserviceable') OR exception IS NOT NULL
   420			ORDER BY created_at DESC LIMIT 200`)
   421		if err == nil {
   422			defer erows.Close()
   423			for erows.Next() {
   424				var sid, status string
   425				var exc []byte
   426				if err := erows.Scan(&sid, &status, &exc); err != nil {
   427					continue
   428				}
   429				item := map[string]any{"sampleId": sid, "status": status}
   430				if len(exc) > 0 {
   431					item["exception"] = jsonRaw(exc)
   432				}
   433				exceptions = append(exceptions, item)
   434			}
   435		}
   436	
   437		journeys := []map[string]any{}
   438		jrows, err := st.PG.QueryContext(ctx, `
   439			SELECT journey_id, plan_version, route_mode, status, estimated_delivery_at, valid, replan_status
   440			FROM journeys WHERE active = TRUE ORDER BY created_at DESC LIMIT 200`)
   441		if err == nil {
   442			defer jrows.Close()
   443			for jrows.Next() {
   444				var jid, mode, status string
   445				var version int
   446				var eta sql.NullTime
   447				var valid bool
   448				var replan sql.NullString
   449				if err := jrows.Scan(&jid, &version, &mode, &status, &eta, &valid, &replan); err != nil {
   450					continue
   451				}
   452				sids, _ := st.journeySampleIDs(ctx, jid)
   453				item := map[string]any{
   454					"journeyId":   jid,
   455					"planVersion": version,
   456					"routeMode":   mode,
   457					"status":      status,
   458					"valid":       valid,
   459					"sampleIds":   sids,
   460				}
   461				if eta.Valid {
   462					item["estimatedDeliveryAt"] = formatTime(eta.Time)
   463				}
   464				if replan.Valid && replan.String != "" {
   465					item["replanStatus"] = replan.String
   466				}
   467				journeys = append(journeys, item)
   468			}
   469		}
   470	
   471		return map[string]any{
   472			"samples":     samples,
   473			"workers":     workers,
   474			"locations":   locations,
   475			"connections": connections,
   476			"exceptions":  exceptions,
   477			"journeys":    journeys,
   478			"filters":     filters,
   479			"generatedAt": formatTime(now),
   480		}, nil
   481	}
   482	
   483	func jsonRaw(b []byte) any {
   484		if len(b) == 0 || string(b) == "null" {
   485			return nil
   486		}
   487		var v any
   488		if err := json.Unmarshal(b, &v); err != nil {
   489			return string(b)
   490		}
   491		return v
   492	}
