    84	func (st *Store) loadTimelineForSample(ctx context.Context, sampleID string) ([]TimelineEntry, error) {
    85		rows, err := st.PG.QueryContext(ctx, `
    86			SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
    87			FROM timeline_events
    88			WHERE sample_id = $1 OR entity_id = $1
    89			ORDER BY event_id ASC`, sampleID)
    90		if err != nil {
    91			return nil, err
    92		}
    93		defer rows.Close()
    94		return scanTimeline(rows)
