    96	
    97	func (st *Store) loadTimelineForEntity(ctx context.Context, entityType, entityID string) ([]TimelineEntry, error) {
    98		rows, err := st.PG.QueryContext(ctx, `
    99			SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
   100			FROM timeline_events
   101			WHERE (entity_type = $1 AND entity_id = $2) OR assignment_id::text = $2 OR journey_id::text = $2
   102			ORDER BY event_id ASC`, entityType, entityID)
   103		if err != nil {
   104			return nil, err
   105		}
   106		defer rows.Close()
   107		return scanTimeline(rows)
