   130		if payload == nil {
   131			payload = map[string]any{}
   132		}
   133		b, _ := json.Marshal(payload)
   134		_, _ = st.PG.ExecContext(ctx, `
   135			INSERT INTO realtime_events (type, entity_type, entity_id, payload, audience_role)
   136			VALUES ($1,$2,$3,$4, NULLIF($5,''))`, typ, entityType, entityID, b, audience)
   137	}
