   530	func (st *Store) handleEvents(w http.ResponseWriter, r *http.Request) {
   531		sess := sessionFrom(r.Context())
   532		since := int64(0)
   533		if q := r.URL.Query().Get("since"); q != "" {
   534			var n int64
   535			if _, err := parseInt64(q, &n); err == nil {
   536				since = n
   537			}
   538		}
   539		upgrade := strings.Contains(strings.ToLower(r.Header.Get("Upgrade")), "websocket")
   540		if upgrade {
   541			st.handleWSEvents(w, r, sess, since)
   542			return
   543		}
   544		ctx := r.Context()
   545		rows, err := st.PG.QueryContext(ctx, `
   546			SELECT id, type, entity_type, entity_id, payload, created_at, audience_role
   547			FROM realtime_events
   548			WHERE id > $1
   549			  AND (audience_role IS NULL OR audience_role = $2)
   550			ORDER BY id ASC
   551			LIMIT 500`, since, sess.ActiveRole)
   552		if err != nil {
   553			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   554			return
   555		}
   556		defer rows.Close()
   557		events := []map[string]any{}
   558		var cursor int64 = since
   559		for rows.Next() {
   560			var id int64
   561			var typ, et, eid string
   562			var payload []byte
   563			var created time.Time
   564			var aud sql.NullString
   565			if err := rows.Scan(&id, &typ, &et, &eid, &payload, &created, &aud); err != nil {
   566				continue
   567			}
   568			var p map[string]any
   569			_ = json.Unmarshal(payload, &p)
   570			if p == nil {
   571				p = map[string]any{}
   572			}
   573			events = append(events, map[string]any{
   574				"id":         id,
   575				"type":       typ,
   576				"entityType": et,
   577				"entityId":   eid,
   578				"payload":    p,
   579				"createdAt":  formatTime(created),
   580			})
   581			cursor = id
   582		}
   583		writeData(w, http.StatusOK, map[string]any{"events": events, "cursor": cursor})
   584	}
