   410	func (st *Store) reserveCapacity(ctx context.Context, tx *sql.Tx, resourceID, journeyID, sampleID string, cooled bool, units int) error {
   411		var capu, resu, ccap, cres int
   412		err := tx.QueryRowContext(ctx, `
   413			SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
   414			FROM capacity_pools WHERE resource_id = $1 FOR UPDATE`, resourceID).
   415			Scan(&capu, &resu, &ccap, &cres)
   416		if err == sql.ErrNoRows {
   417			// unlimited if not configured
   418			_, _ = tx.ExecContext(ctx, `
   419				INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   420				VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   421			return nil
   422		}
   423		if err != nil {
   424			return err
   425		}
   426		if cooled {
   427			if ccap > 0 && cres+units > ccap {
   428				return errJSON("cooled_capacity_exhausted", "cooled capacity exhausted", http.StatusConflict)
   429			}
   430			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = cooled_reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   431		} else {
   432			if capu > 0 && resu+units > capu {
   433				return errJSON("capacity_exhausted", "capacity exhausted", http.StatusConflict)
   434			}
   435			_, err = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = reserved_units + $1 WHERE resource_id = $2`, units, resourceID)
   436		}
   437		if err != nil {
   438			return err
   439		}
   440		_, err = tx.ExecContext(ctx, `
   441			INSERT INTO capacity_reservations (resource_id, journey_id, sample_id, cooled, units, active)
   442			VALUES ($1,$2,$3,$4,$5,TRUE)`, resourceID, journeyID, sampleID, cooled, units)
   443		return err
   444	}
