   446	func (st *Store) releaseJourneyCapacity(ctx context.Context, tx *sql.Tx, journeyID string) {
   447		rows, err := tx.QueryContext(ctx, `
   448			SELECT reservation_id, resource_id, cooled, units FROM capacity_reservations
   449			WHERE journey_id = $1 AND active = TRUE`, journeyID)
   450		if err != nil {
   451			return
   452		}
   453		type resv struct {
   454			id, resource string
   455			cooled       bool
   456			units        int
   457		}
   458		var list []resv
   459		for rows.Next() {
   460			var r resv
   461			if err := rows.Scan(&r.id, &r.resource, &r.cooled, &r.units); err == nil {
   462				list = append(list, r)
   463			}
   464		}
   465		rows.Close()
   466		for _, r := range list {
   467			if r.cooled {
   468				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = GREATEST(cooled_reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   469			} else {
   470				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = GREATEST(reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   471			}
   472			_, _ = tx.ExecContext(ctx, `UPDATE capacity_reservations SET active = FALSE WHERE reservation_id = $1`, r.id)
   473		}
   474	}
