   212	func matchStatus(filter, status string, terminal bool) bool {
   213		if filter == "" {
   214			return true
   215		}
   216		switch filter {
   217		case "current":
   218			return !terminal
   219		case "past", "completed":
   220			return terminal
   221		default:
   222			return status == filter
   223		}
