    39	func (st *Store) reoffer(ctx context.Context, asgID, kind, sampleID, journeyID, nodeID, labID, exclude string) {
    40		loc := nodeID
    41		if loc == "" {
    42			loc = labID
    43		}
    44		qual := ""
    45		if kind == KindCollection {
    46			_ = st.PG.QueryRowContext(ctx, `
    47				SELECT st.required_qualification
    48				FROM samples s JOIN sample_types st ON st.sample_type_id = s.sample_type_id
    49				WHERE s.sample_id = $1`, sampleID).Scan(&qual)
    50		}
    51		_ = st.tx(ctx, func(tx *sql.Tx) error {
    52			next := st.pickWorkerTx(ctx, tx, kind, loc, qual, exclude)
    53			if next == "" {
    54				_, _ = tx.ExecContext(ctx, `
    55					UPDATE assignments SET status = 'pending', offered_worker_id = NULL, offer_expires_at = NULL
    56					WHERE assignment_id = $1`, asgID)
    57				// flag exception if collection/lab assignment has been waiting too long
    58				var created time.Time
    59				_ = tx.QueryRowContext(ctx, `SELECT created_at FROM assignments WHERE assignment_id = $1`, asgID).Scan(&created)
    60				if time.Since(created) > noWorkerWait {
    61					exc, _ := json.Marshal(map[string]any{
    62						"reason": "no_qualified_worker",
    63						"code":   "no_qualified_worker",
    64					})
    65					_, _ = tx.ExecContext(ctx, `UPDATE samples SET status = $1, exception = $2 WHERE sample_id = $3 AND status NOT IN ('received','cancelled')`,
    66						SampleException, exc, sampleID)
    67				}
    68				return nil
    69			}
    70			_, _ = tx.ExecContext(ctx, `
    71				UPDATE assignments SET status = 'offered', offered_worker_id = $1, offer_expires_at = $2, worker_id = NULL
    72				WHERE assignment_id = $3`, next, time.Now().Add(offerTTL), asgID)
    73			return nil
    74		})
    75		st.emitEvent(ctx, "assignment_offered", "assignment", asgID, map[string]any{"sampleId": sampleID}, "")
    76	}
