   408	func (st *Store) handleEvents(w http.ResponseWriter, r *http.Request) {
   409		sess := sessionFrom(r.Context())
   410		since := int64(0)
   411		if q := r.URL.Query().Get("since"); q != "" {
   412			var n int64
   413			if _, err := parseInt64(q, &n); err == nil {
   414				since = n
   415			}
   416		}
   417		upgrade := strings.Contains(strings.ToLower(r.Header.Get("Upgrade")), "websocket")
   418		if upgrade {
   419			st.handleWSEvents(w, r, sess, since)
   420			return
   421		}
   422		ctx := r.Context()
   423		rows, err := st.PG.QueryContext(ctx, `
   424			SELECT id, type, entity_type, entity_id, payload, created_at, audience_role
   425			FROM realtime_events
   426			WHERE id > $1
   427			  AND (audience_role IS NULL OR audience_role = $2)
   428			ORDER BY id ASC
   429			LIMIT 500`, since, sess.ActiveRole)
   430		if err != nil {
   431			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   432			return
   433		}
   434		defer rows.Close()
   435		events := []map[string]any{}
   436		var cursor int64 = since
   437		for rows.Next() {
   438			var id int64
   439			var typ, et, eid string
   440			var payload []byte
   441			var created time.Time
   442			var aud sql.NullString
   443			if err := rows.Scan(&id, &typ, &et, &eid, &payload, &created, &aud); err != nil {
   444				continue
   445			}
   446			var p map[string]any
   447			_ = json.Unmarshal(payload, &p)
   448			if p == nil {
   449				p = map[string]any{}
   450			}
   451			events = append(events, map[string]any{
   452				"id":         id,
   453				"type":       typ,
   454				"entityType": et,
   455				"entityId":   eid,
   456				"payload":    p,
   457				"createdAt":  formatTime(created),
   458			})
   459			cursor = id
   460		}
   461		writeData(w, http.StatusOK, map[string]any{"events": events, "cursor": cursor})
   462	}
   463	
   464	func parseInt64(s string, dest *int64) (int, error) {
   465		var n int64
   466		for _, c := range s {
   467			if c < '0' || c > '9' {
   468				return 0, errJSON("invalid_json", "invalid", 400)
   469			}
   470			n = n*10 + int64(c-'0')
   471		}
   472		*dest = n
   473		return 0, nil
   474	}
