   367		sess := sessionFrom(r.Context())
   368		if err := sess.requireAny(RoleAdministrator, RoleDispatcher, RoleNode, RoleLab); err != nil {
   369			writeAPIError(w, err)
   370			return
   371		}
   372		var req struct {
   373			ResourceID          string `json:"resourceId"`
   374			CapacityUnits       int    `json:"capacityUnits"`
   375			CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
   376		}
   377		if err := decodeJSON(r, &req); err != nil {
   378			writeAPIError(w, err)
   379			return
   380		}
   381		if req.CapacityUnits < 0 {
   382			writeErr(w, http.StatusBadRequest, "invalid_capacity", "invalid capacity")
   383			return
   384		}
   385		cooled := 0
   386		if req.CooledCapacityUnits != nil {
   387			if *req.CooledCapacityUnits < 0 {
   388				writeErr(w, http.StatusBadRequest, "invalid_capacity", "invalid capacity")
   389				return
   390			}
   391			cooled = *req.CooledCapacityUnits
   392		}
   393		ctx := r.Context()
   394		// node/lab workers may only configure their assigned location
   395		if sess.ActiveRole == RoleNode || sess.ActiveRole == RoleLab {
   396			if !sess.AssignedLoc.Valid || sess.AssignedLoc.String != req.ResourceID {
   397				writeErr(w, http.StatusForbidden, "forbidden", "forbidden")
   398				return
   399			}
   400		}
   401		var reserved, cooledReserved int
   402		err := st.PG.QueryRowContext(ctx, `
   403			SELECT reserved_units, cooled_reserved_units FROM capacity_pools WHERE resource_id = $1`, req.ResourceID).
   404			Scan(&reserved, &cooledReserved)
   405		if err == sql.ErrNoRows {
   406			_, _ = st.PG.ExecContext(ctx, `
   407				INSERT INTO capacity_pools (resource_id, resource_kind, capacity_units, cooled_capacity_units)
   408				VALUES ($1, 'unknown', $2, $3)`, req.ResourceID, req.CapacityUnits, cooled)
   409		} else if err != nil {
   410			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   411			return
   412		} else {
   413			if req.CapacityUnits < reserved || cooled < cooledReserved {
   414				writeErr(w, http.StatusConflict, "capacity_reserved", "capacity reserved")
   415				return
   416			}
   417			_, err = st.PG.ExecContext(ctx, `
   418				UPDATE capacity_pools SET capacity_units = $1, cooled_capacity_units = $2 WHERE resource_id = $3`,
   419				req.CapacityUnits, cooled, req.ResourceID)
   420			if err != nil {
   421				writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   422				return
   423			}
   424		}
   425		st.bumpNetwork(ctx, nil)
   426		st.audit(ctx, sess, "configure_capacity", "capacity", req.ResourceID, true, map[string]any{
   427			"capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cooled,
   428		})
   429		writeData(w, http.StatusOK, map[string]any{
   430			"resourceId":          req.ResourceID,
   431			"capacityUnits":       req.CapacityUnits,
   432			"cooledCapacityUnits": cooled,
