   738	func (st *Store) latestSnapshot(ctx context.Context) (map[string]any, error) {
   739		var version, revision int
   740		var status string
   741		var computed time.Time
   742		var payload []byte
   743		err := st.PG.QueryRowContext(ctx, `
   744			SELECT version, status, computed_at, network_revision, payload
   745			FROM serviceability_snapshots ORDER BY version DESC LIMIT 1`).
   746			Scan(&version, &status, &computed, &revision, &payload)
   747		if err != nil {
   748			return nil, err
   749		}
   750		var p struct {
   751			Regions                    []map[string]any `json:"regions"`
   752			ActiveCollectionPointCount int              `json:"activeCollectionPointCount"`
   753		}
   754		_ = json.Unmarshal(payload, &p)
   755		if p.Regions == nil {
   756			p.Regions = []map[string]any{}
   757		}
   758		return map[string]any{
   759			"version":                    version,
   760			"status":                     "complete",
   761			"computedAt":                 formatTime(computed),
