   318	func itoa(n int) string {
   319		if n == 0 {
   320			return "0"
   321		}
   322		var b [12]byte
   323		i := len(b)
   324		for n > 0 {
   325			i--
   326			b[i] = byte('0' + n%10)
   327			n /= 10
   328		}
   329		return string(b[i:])
   330	}
