   556			rows, _ = st.PG.QueryContext(ctx, `
   557				SELECT DISTINCT journey_id FROM assignments
   558				WHERE (worker_id = $1 OR offered_worker_id = $1) AND status NOT IN ('completed','delivered','cancelled')`, req.ResourceID)
   559		case "node", "laboratory":
