   376	func (st *Store) releaseJourneyCapacity(ctx context.Context, tx *sql.Tx, journeyID string) {
   377		rows, err := tx.QueryContext(ctx, `
   378			SELECT reservation_id, resource_id, cooled, units FROM capacity_reservations
   379			WHERE journey_id = $1 AND active = TRUE`, journeyID)
   380		if err != nil {
   381			return
   382		}
   383		type resv struct {
   384			id, resource string
   385			cooled       bool
   386			units        int
   387		}
   388		var list []resv
   389		for rows.Next() {
   390			var r resv
   391			if err := rows.Scan(&r.id, &r.resource, &r.cooled, &r.units); err == nil {
   392				list = append(list, r)
   393			}
   394		}
   395		rows.Close()
   396		for _, r := range list {
   397			if r.cooled {
   398				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = GREATEST(cooled_reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   399			} else {
   400				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = GREATEST(reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   401			}
   402			_, _ = tx.ExecContext(ctx, `UPDATE capacity_reservations SET active = FALSE WHERE reservation_id = $1`, r.id)
   403		}
   404	}
