   691				if hop.ToID == route.Laboratory {
   692					stopType = "dropoff"
   693				}
   694				if _, err := tx.ExecContext(ctx, `
   695					INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
   696					VALUES ($1,$2,$3,$4,$5,0)`, journeyID, hop.ToID, stopType, seq, t); err != nil {
   697					return err
   698				}
