    47	func (st *Store) handleWSEvents(w http.ResponseWriter, r *http.Request, sess *Session, since int64) {
    48		// extract token from subprotocol if middleware already authenticated via header
    49		hdr := http.Header{}
    50		requested := websocket.Subprotocols(r)
    51		chosen := []string{}
    52		for _, p := range requested {
    53			if p == "lab-logistics-v1" || strings.HasPrefix(p, "bearer.") {
    54				chosen = append(chosen, p)
    55			}
    56		}
    57		if len(chosen) > 0 {
    58			hdr.Set("Sec-WebSocket-Protocol", strings.Join(chosen, ", "))
    59		}
    60		conn, err := upgrader.Upgrade(w, r, hdr)
    61		if err != nil {
    62			return
    63		}
    64		c := &wsClient{conn: conn, sess: sess, send: make(chan []byte, 32), since: since}
    65		go c.writePump()
    66		st.replayAndListen(c)
    67	}
    68	
    69	func (c *wsClient) writePump() {
    70		defer c.conn.Close()
    71		ticker := time.NewTicker(25 * time.Second)
    72		defer ticker.Stop()
    73		for {
    74			select {
    75			case msg, ok := <-c.send:
    76				if !ok {
    77					return
    78				}
    79				_ = c.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
    80				if err := c.conn.WriteMessage(websocket.TextMessage, msg); err != nil {
    81					return
    82				}
    83			case <-ticker.C:
    84				_ = c.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
    85				if err := c.conn.WriteMessage(websocket.PingMessage, nil); err != nil {
    86					return
    87				}
    88			}
    89		}
    90	}
