   443	func (st *Store) validateMerge(ctx context.Context, target string, sources []string) error {
   444		type meta struct {
   445			typeID, container string
   446			cooled, batch     bool
   447			incompat          []string
   448		}
   449		load := func(jid string) []meta {
   450			rows, err := st.PG.QueryContext(ctx, `
   451				SELECT s.sample_type_id, st.container_type, st.requires_cooled_route, st.batching_allowed
   452				FROM journey_samples js
   453				JOIN samples s ON s.sample_id = js.sample_id
   454				JOIN sample_types st ON st.sample_type_id = s.sample_type_id
   455				WHERE js.journey_id = $1`, jid)
   456			if err != nil {
   457				return nil
   458			}
   459			defer rows.Close()
   460			var out []meta
   461			for rows.Next() {
   462				var m meta
   463				if err := rows.Scan(&m.typeID, &m.container, &m.cooled, &m.batch); err == nil {
   464					m.incompat, _ = st.loadIncompat(ctx, m.typeID)
   465					out = append(out, m)
   466				}
   467			}
   468			return out
   469		}
   470		all := load(target)
   471		for _, s := range sources {
   472			all = append(all, load(s)...)
   473		}
   474		for i := 0; i < len(all); i++ {
   475			if !all[i].batch {
   476				return errJSON("incompatible_batch", "incompatible batch", http.StatusConflict)
   477			}
   478			for j := i + 1; j < len(all); j++ {
   479				if all[i].container != all[j].container {
   480					return errJSON("incompatible_container", "incompatible container", http.StatusConflict)
   481				}
   482				if all[i].cooled != all[j].cooled {
   483					return errJSON("incompatible_temperature", "incompatible temperature", http.StatusConflict)
   484				}
   485				if containsStr(all[i].incompat, all[j].typeID) || containsStr(all[j].incompat, all[i].typeID) {
   486					return errJSON("incompatible_sample_types", "incompatible sample types", http.StatusConflict)
   487				}
   488			}
   489		}
   490		return nil
   491	}
