   709			LaboratoryID   string `json:"laboratoryId"`
   710			ReceivedAt     string `json:"receivedAt"`
   711			IdempotencyKey string `json:"idempotencyKey"`
   712		}
   713		if err := decodeJSON(r, &req); err != nil {
   714			writeAPIError(w, err)
   715			return
   716		}
   717		receivedAt, err := parseTime(req.ReceivedAt, "invalid_time")
   718		if err != nil {
   719			writeAPIError(w, err)
   720			return
   721		}
   722		ctx := r.Context()
   723		if req.IdempotencyKey != "" {
   724			hash := hashRequest("lab_receipt", req.SampleID, req.LaboratoryID)
   725			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "lab_receipt", hash)
   726			if err != nil {
   727				writeAPIError(w, err)
   728				return
   729			}
   730			if hit {
   731				replayIdempotent(w, status, body)
   732				return
   733			}
   734		}
   735		var status string
   736		var deadline time.Time
   737		err = st.PG.QueryRowContext(ctx, `
   738			SELECT s.status, r.delivery_deadline
   739			FROM samples s JOIN collection_requests r ON r.request_id = s.request_id
   740			WHERE s.sample_id = $1`, req.SampleID).Scan(&status, &deadline)
   741		if err == sql.ErrNoRows {
   742			writeErr(w, http.StatusNotFound, "not_found", "not found")
   743			return
   744		}
   745		if status == SampleReceived {
   746			out := map[string]any{"sampleId": req.SampleID, "status": SampleReceived}
   747			writeData(w, http.StatusOK, out)
   748			return
   749		}
   750		final := SampleReceived
   751		var exc any
   752		if receivedAt.After(deadline) {
   753			final = SampleExpired
   754			b, _ := json.Marshal(map[string]any{"reason": "missed_delivery_deadline"})
   755			exc = b
   756		}
   757		_, err = st.PG.ExecContext(ctx, `
   758			UPDATE samples SET status = $1, received_laboratory_id = $2, received_at = $3, current_holder_id = $4, exception = COALESCE($5, exception)
   759			WHERE sample_id = $6`, final, req.LaboratoryID, receivedAt, sess.UserID, exc, req.SampleID)
   760		if err != nil {
   761			writeErr(w, http.StatusInternalServerError, "internal_error", "internal error")
   762			return
   763		}
   764		_, _ = st.PG.ExecContext(ctx, `
   765			UPDATE assignments SET status = 'completed', completed_at = $1
   766			WHERE sample_id = $2 AND kind = 'laboratory' AND status NOT IN ('cancelled','completed')`, receivedAt, req.SampleID)
   767		_, _ = st.PG.ExecContext(ctx, `
   768			UPDATE journeys SET status = 'completed'
   769			WHERE journey_id IN (SELECT journey_id FROM journey_samples WHERE sample_id = $1) AND active = TRUE`, req.SampleID)
   770		st.audit(ctx, sess, "confirm_laboratory_receipt", "sample", req.SampleID, true, map[string]any{"laboratoryId": req.LaboratoryID})
   771		_, _ = st.writeTimeline(ctx, nil, req.SampleID, "", "", "confirm_laboratory_receipt", sess.UserID, sess.ActiveRole, "sample", req.SampleID, true, map[string]any{"status": final})
   772		st.emitEvent(ctx, "sample_received", "sample", req.SampleID, map[string]any{"status": final}, "")
   773		out := map[string]any{"sampleId": req.SampleID, "status": final}
   774		if req.IdempotencyKey != "" {
