   780	func (st *Store) handleRecordLabException(w http.ResponseWriter, r *http.Request) {
   781		sess := sessionFrom(r.Context())
   782		if err := sess.requireAny(RoleLab, RoleAdministrator, RoleDispatcher); err != nil {
   783			writeAPIError(w, err)
