   788			LaboratoryID   string `json:"laboratoryId"`
   789			Reason         string `json:"reason"`
   790			ObservedAt     string `json:"observedAt"`
   791			IdempotencyKey string `json:"idempotencyKey"`
   792		}
   793		if err := decodeJSON(r, &req); err != nil {
   794			writeAPIError(w, err)
   795			return
   796		}
   797		if req.Reason == "" {
   798			writeErr(w, http.StatusBadRequest, "invalid_reason", "invalid reason")
   799			return
   800		}
   801		observedAt, err := parseTime(req.ObservedAt, "invalid_time")
   802		if err != nil {
   803			writeAPIError(w, err)
   804			return
   805		}
   806		ctx := r.Context()
   807		if req.IdempotencyKey != "" {
   808			hash := hashRequest("lab_exc", req.SampleID, req.Reason)
   809			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "lab_exc", hash)
   810			if err != nil {
   811				writeAPIError(w, err)
   812				return
   813			}
   814			if hit {
   815				replayIdempotent(w, status, body)
   816				return
   817			}
   818		}
   819		var exists int
   820		_ = st.PG.QueryRowContext(ctx, `SELECT COUNT(*) FROM samples WHERE sample_id = $1`, req.SampleID).Scan(&exists)
   821		if exists == 0 {
   822			writeErr(w, http.StatusNotFound, "not_found", "not found")
   823			return
   824		}
   825		id := newUUID()
   826		_, _ = st.PG.ExecContext(ctx, `
   827			INSERT INTO exceptions (exception_id, sample_id, laboratory_id, reason, observed_at)
   828			VALUES ($1,$2,$3,$4,$5)`, id, req.SampleID, req.LaboratoryID, req.Reason, observedAt)
   829		exc, _ := json.Marshal(map[string]any{"reason": req.Reason, "laboratoryId": req.LaboratoryID})
   830		_, _ = st.PG.ExecContext(ctx, `UPDATE samples SET status = $1, exception = $2 WHERE sample_id = $3`, SampleException, exc, req.SampleID)
   831		st.audit(ctx, sess, "record_laboratory_exception", "sample", req.SampleID, true, map[string]any{"reason": req.Reason})
   832		_, _ = st.writeTimeline(ctx, nil, req.SampleID, "", "", "record_laboratory_exception", sess.UserID, sess.ActiveRole, "sample", req.SampleID, true, map[string]any{"reason": req.Reason})
   833		out := map[string]any{"exceptionId": id, "status": SampleException}
   834		if req.IdempotencyKey != "" {
   835			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "lab_exc", hashRequest("lab_exc", req.SampleID, req.Reason), http.StatusCreated, out)
   836		}
   837		writeData(w, http.StatusCreated, out)
   838	}

