with open("/workspace/contracts/openapi.contract.json") as f:
    spec = json.load(f)

for name in ["TimelineEntry","RealtimeEvent","ServiceabilityRegion","Capacity",
             "Location","OperationsLocation","OperationsConnection","LocationFunctionStates",
             "ErrorEnvelope","Certification"]:
    print(f"\n==== {name} ====")
    print(json.dumps(spec["components"]["schemas"][name], indent=2)[:2500])

print("\n==== remaining OperationsState ====")
print(json.dumps(spec["components"]["schemas"]["OperationsState"], indent=2)[3500:])

# dump each path's request/response
print("\n==== OPERATION DETAILS ====")
for p, methods in spec["paths"].items():
    for m, op in methods.items():
        if m.startswith("x-"): continue
        print(f"\n## {op.get('operationId')} {m.upper()} {p}")
        print("  tags:", op.get("tags"))
        print("  security:", op.get("security"))
        if "parameters" in op:
            for prm in op["parameters"]:
                print("  param:", prm.get("name"), prm.get("in"), prm.get("required"), prm.get("schema",{}).get("type"))
        if "requestBody" in op:
            content = op["requestBody"].get("content", {})
            for ct, body in content.items():
                sch = body.get("schema", {})
                print("  requestBody required:", op["requestBody"].get("required"), "schema keys:", list(sch.get("properties",{}).keys()) if "properties" in sch else sch)
                if "required" in sch:
                    print("    required fields:", sch["required"])
        for code, resp in op.get("responses", {}).items():
            content = resp.get("content", {})
            for ct, body in content.items():
                sch = body.get("schema", {})
                if "$ref" in sch:
                    print(f"  {code}: {sch['$ref']}")
                elif "properties" in sch:
                    print(f"  {code}: keys={list(sch['properties'].keys())} required={sch.get('required')} addl={sch.get('additionalProperties')}")
                else:
                    print(f"  {code}: {json.dumps(sch)[:300]}")
