   197	func (st *Store) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
   198		sess := sessionFrom(r.Context())
   199		if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
   200			writeAPIError(w, err)
   201			return
   202		}
   203		var req struct {
   204			JourneyID            string         `json:"journeyId"`
   205			ExpectedPlanVersion  int            `json:"expectedPlanVersion"`
   206			ChangeType           string         `json:"changeType"`
   207			Changes              map[string]any `json:"changes"`
   208			IdempotencyKey       string         `json:"idempotencyKey"`
   209		}
   210		if err := decodeJSON(r, &req); err != nil {
   211			writeAPIError(w, err)
   212			return
   213		}
   214		allowed := map[string]bool{"reroute": true, "reassign": true, "reschedule": true, "split": true, "merge": true, "cancel": true}
   215		if !allowed[req.ChangeType] {
   216			writeErr(w, http.StatusBadRequest, "invalid_change_type", "invalid change type")
   217			return
   218		}
   219		ctx := r.Context()
   220		if req.IdempotencyKey != "" {
   221			hash := hashRequest("edit", req.JourneyID, req.ChangeType, itoa(req.ExpectedPlanVersion))
   222			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "edit", hash)
   223			if err != nil {
   224				writeAPIError(w, err)
   225				return
   226			}
   227			if hit {
   228				replayIdempotent(w, status, body)
   229				return
   230			}
   231		}
   232		if _, err := st.expectPlanVersion(ctx, req.JourneyID, req.ExpectedPlanVersion); err != nil {
   233			writeAPIError(w, err)
   234			return
   235		}
   236		var newVersion int
   237		err := st.tx(ctx, func(tx *sql.Tx) error {
   238			v, err := st.bumpPlan(ctx, tx, req.JourneyID)
   239			if err != nil {
   240				return err
   241			}
   242			newVersion = v
   243			// apply limited changes without rewriting completed work
   244			if req.ChangeType == "cancel" {
   245				_, _ = tx.ExecContext(ctx, `
   246					UPDATE assignments SET status = 'cancelled'
   247					WHERE journey_id = $1 AND status NOT IN ('completed','delivered','cancelled')`, req.JourneyID)
   248				_, _ = tx.ExecContext(ctx, `UPDATE journeys SET status = 'cancelled' WHERE journey_id = $1`, req.JourneyID)
   249				st.releaseJourneyCapacity(ctx, tx, req.JourneyID)
   250			}
   251			if req.ChangeType == "reassign" {
   252				if asg, ok := req.Changes["assignmentId"].(string); ok {
   253					if worker, ok := req.Changes["workerId"].(string); ok {
   254						var status string
   255						_ = tx.QueryRowContext(ctx, `SELECT status FROM assignments WHERE assignment_id = $1`, asg).Scan(&status)
   256						if status == AssignCompleted || status == AssignDelivered || status == AssignCancelled {
   257							return errJSON("completed_work_immutable", "completed work cannot be rewritten", http.StatusConflict)
   258						}
   259						_, _ = tx.ExecContext(ctx, `
   260							UPDATE assignments SET worker_id = $1, offered_worker_id = $1, status = 'offered',
   261							  offer_expires_at = $2 WHERE assignment_id = $3`, worker, time.Now().Add(offerTTL), asg)
   262					}
   263				}
   264			}
   265			return nil
   266		})
   267		if err != nil {
   268			writeAPIError(w, err)
   269			return
   270		}
   271		st.audit(ctx, sess, "edit_active_plan", "journey", req.JourneyID, true, map[string]any{"changeType": req.ChangeType, "planVersion": newVersion})
   272		_, _ = st.writeTimeline(ctx, nil, "", req.JourneyID, "", "edit_active_plan", sess.UserID, sess.ActiveRole, "journey", req.JourneyID, true, map[string]any{"changeType": req.ChangeType})
   273		out := map[string]any{"journeyId": req.JourneyID, "planVersion": newVersion, "status": "updated"}
   274		if req.IdempotencyKey != "" {
   275			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "edit", hashRequest("edit", req.JourneyID, req.ChangeType, itoa(req.ExpectedPlanVersion)), http.StatusOK, out)
   276		}
   277		writeData(w, http.StatusOK, out)
   278	}
