   280	func (st *Store) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
   281		sess := sessionFrom(r.Context())
   282		if err := sess.requireAny(RoleAdministrator, RoleDispatcher); err != nil {
   283			writeAPIError(w, err)
   284			return
   285		}
   286		var req struct {
   287			JourneyID           string   `json:"journeyId"`
   288			ExpectedPlanVersion int      `json:"expectedPlanVersion"`
   289			SampleIDs           []string `json:"sampleIds"`
   290			IdempotencyKey      string   `json:"idempotencyKey"`
   291		}
   292		if err := decodeJSON(r, &req); err != nil {
   293			writeAPIError(w, err)
   294			return
   295		}
   296		if len(req.SampleIDs) == 0 {
   297			writeErr(w, http.StatusBadRequest, "invalid_split", "invalid split")
   298			return
   299		}
   300		ctx := r.Context()
   301		if req.IdempotencyKey != "" {
   302			hash := hashRequest("split", req.JourneyID, itoa(req.ExpectedPlanVersion))
   303			hit, status, body, err := st.checkIdempotency(ctx, sess.UserID, req.IdempotencyKey, "split", hash)
   304			if err != nil {
   305				writeAPIError(w, err)
   306				return
   307			}
   308			if hit {
   309				replayIdempotent(w, status, body)
   310				return
   311			}
   312		}
   313		if _, err := st.expectPlanVersion(ctx, req.JourneyID, req.ExpectedPlanVersion); err != nil {
   314			writeAPIError(w, err)
   315			return
   316		}
   317		newJourneyID := newUUID()
   318		var newVersion int
   319		err := st.tx(ctx, func(tx *sql.Tx) error {
   320			v, err := st.bumpPlan(ctx, tx, req.JourneyID)
   321			if err != nil {
   322				return err
   323			}
   324			newVersion = v
   325			var mode, status string
   326			var eta sql.NullTime
   327			var cost float64
   328			_ = tx.QueryRowContext(ctx, `SELECT route_mode, status, estimated_delivery_at, total_cost_units FROM journeys WHERE journey_id = $1`, req.JourneyID).
   329				Scan(&mode, &status, &eta, &cost)
   330			if _, err := tx.ExecContext(ctx, `
   331				INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, valid, active)
   332				VALUES ($1,$2,1,$3,$4,$5,$6,TRUE,TRUE)`, newJourneyID, req.JourneyID, mode, status, eta, cost); err != nil {
   333				return err
   334			}
   335			for _, sid := range req.SampleIDs {
   336				if _, err := tx.ExecContext(ctx, `DELETE FROM journey_samples WHERE journey_id = $1 AND sample_id = $2`, req.JourneyID, sid); err != nil {
   337					return err
   338				}
   339				if _, err := tx.ExecContext(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2)`, newJourneyID, sid); err != nil {
   340					return err
   341				}
   342				// copy unfinished assignments
   343				if _, err := tx.ExecContext(ctx, `
   344					UPDATE assignments SET journey_id = $1
   345					WHERE journey_id = $2 AND sample_id = $3 AND status NOT IN ('completed','delivered','cancelled')`,
   346					newJourneyID, req.JourneyID, sid); err != nil {
   347					return err
   348				}
   349			}
   350			return nil
   351		})
   352		if err != nil {
   353			writeAPIError(w, err)
   354			return
   355		}
   356		st.audit(ctx, sess, "split_journey", "journey", req.JourneyID, true, map[string]any{"newJourneyId": newJourneyID})
   357		out := map[string]any{
   358			"journeyId":    req.JourneyID,
   359			"planVersion":  newVersion,
   360			"newJourneyId": newJourneyID,
   361		}
   362		if req.IdempotencyKey != "" {
   363			st.saveIdempotency(ctx, sess.UserID, req.IdempotencyKey, "split", hashRequest("split", req.JourneyID, itoa(req.ExpectedPlanVersion)), http.StatusOK, out)
   364		}
   365		writeData(w, http.StatusOK, out)
   366	}
