   268	func (st *Store) pickWorkerTx(ctx context.Context, tx *sql.Tx, kind, locationID, qualification, exclude string) string {
   269		role := RoleDelivery
   270		switch kind {
   271		case KindCollection:
   272			role = RoleCollection
   273		case KindNode:
   274			role = RoleNode
   275		case KindLaboratory:
   276			role = RoleLab
   277		}
   278		q := `
   279			SELECT u.user_id
   280			FROM users u
   281			JOIN user_roles ur ON ur.user_id = u.user_id AND ur.role = $1
   282			WHERE u.active = TRUE AND u.available = TRUE`
   283		args := []any{role}
   284		idx := 2
   285		if locationID != "" && (kind == KindNode || kind == KindLaboratory) {
   286			q += ` AND u.assigned_location_id = $` + itoa(idx)
   287			args = append(args, locationID)
   288			idx++
   289		}
   290		if qualification != "" && kind == KindCollection {
   291			q += ` AND EXISTS (SELECT 1 FROM user_qualifications q WHERE q.user_id = u.user_id AND q.qualification = $` + itoa(idx) + `)`
   292			args = append(args, qualification)
   293			idx++
   294		}
   295		if exclude != "" {
   296			q += ` AND u.user_id <> $` + itoa(idx)
   297			args = append(args, exclude)
   298			idx++
   299		}
   300		// fair: fewer open assignments, then older last_assigned, then fewer recent declines
   301		q += `
   302			ORDER BY
   303			  (SELECT COUNT(*) FROM assignments a WHERE (a.worker_id = u.user_id OR a.offered_worker_id = u.user_id)
   304			     AND a.status IN ('offered','accepted','in_progress','pending','at_pickup','picked_up','in_transit','arrived')),
   305			  CASE WHEN u.last_decline_at IS NOT NULL AND u.last_decline_at > now() - interval '2 hours'
   306			       THEN u.decline_count ELSE 0 END,
   307			  COALESCE(u.last_assigned_at, '1970-01-01'::timestamptz),
   308			  u.user_id
   309			LIMIT 1`
   310		var id string
   311		if err := tx.QueryRowContext(ctx, q, args...).Scan(&id); err != nil {
   312			return ""
   313		}
   314		_, _ = tx.ExecContext(ctx, `UPDATE users SET last_assigned_at = now() WHERE user_id = $1`, id)
   315		return id
   316	}
   317	
   318	func itoa(n int) string {
   319		if n == 0 {
   320			return "0"
   321		}
   322		var b [12]byte
   323		i := len(b)
   324		for n > 0 {
   325			i--
   326			b[i] = byte('0' + n%10)
   327			n /= 10
   328		}
   329		return string(b[i:])
   330	}
