   444	func itoa(n int) string {
   445		if n == 0 {
   446			return "0"
   447		}
   448		var b [12]byte
   449		i := len(b)
   450		for n > 0 {
   451			i--
   452			b[i] = byte('0' + n%10)
   453			n /= 10
   454		}
   455		return string(b[i:])
   456	}
