   687	func (st *Store) releaseJourneyCapacity(ctx context.Context, tx *sql.Tx, journeyID string) {
   688		rows, err := tx.QueryContext(ctx, `
   689			SELECT reservation_id, resource_id, cooled, units FROM capacity_reservations
   690			WHERE journey_id = $1 AND active = TRUE`, journeyID)
   691		if err != nil {
