   369	func (st *Store) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
   370		sess := sessionFrom(r.Context())
   371		if err := sess.requireAny(RoleRequester, RoleAdministrator, RoleDispatcher); err != nil {
   372			writeAPIError(w, err)
   373			return
   374		}
   375		var req struct {
   376			Origin               Coordinate `json:"origin"`
   377			OriginType           string     `json:"originType"`
   378			OriginNodeID         string     `json:"originNodeId"`
   379			SampleTypeID         string     `json:"sampleTypeId"`
   380			RequestedAt          string     `json:"requestedAt"`
   381			DeliveryDeadline     string     `json:"deliveryDeadline"`
   382			EarliestCollectionAt string     `json:"earliestCollectionAt"`
   383			LatestCollectionAt   string     `json:"latestCollectionAt"`
   384		}
   385		if err := decodeJSON(r, &req); err != nil {
   386			writeAPIError(w, err)
   387			return
   388		}
   389		if !validCoord(req.Origin) {
   390			writeErr(w, http.StatusBadRequest, "invalid_origin", "invalid origin")
   391			return
   392		}
   393		if req.OriginType == "" {
   394			req.OriginType = OriginHome
   395		}
   396		if req.OriginType != OriginHome && req.OriginType != OriginClinic && req.OriginType != OriginNode {
   397			writeErr(w, http.StatusBadRequest, "invalid_origin_type", "invalid origin type")
   398			return
   399		}
   400		requestedAt, err := parseTime(req.RequestedAt, "invalid_time")
   401		if err != nil {
   402			writeAPIError(w, err)
   403			return
   404		}
   405		deadline, err := parseTime(req.DeliveryDeadline, "invalid_deadline")
   406		if err != nil {
   407			writeAPIError(w, err)
   408			return
   409		}
   410		if !deadline.After(requestedAt) {
   411			writeErr(w, http.StatusBadRequest, "invalid_deadline", "invalid deadline")
   412			return
   413		}
   414		earliest := requestedAt
   415		if req.EarliestCollectionAt != "" {
   416			earliest, err = parseTime(req.EarliestCollectionAt, "invalid_collection_window")
   417			if err != nil {
   418				writeAPIError(w, err)
   419				return
   420			}
   421		}
   422		latest := deadline
   423		if req.LatestCollectionAt != "" {
   424			latest, err = parseTime(req.LatestCollectionAt, "invalid_collection_window")
   425			if err != nil {
   426				writeAPIError(w, err)
   427				return
   428			}
   429		}
   430		if latest.Before(earliest) {
   431			writeErr(w, http.StatusBadRequest, "invalid_collection_window", "invalid collection window")
   432			return
   433		}
   434		ctx := r.Context()
   435		res, err := st.evaluateServiceability(ctx, req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, requestedAt, deadline, earliest, latest)
   436		if err != nil {
   437			writeAPIError(w, err)
   438			return
   439		}
   440		out := map[string]any{
   441			"serviceable":           res.Serviceable,
   442			"reason":                res.Reason,
   443			"serviceabilityVersion": res.ServiceabilityVersion,
   444		}
   445		if res.TargetLaboratoryID != "" {
   446			out["targetLaboratoryId"] = res.TargetLaboratoryID
   447		}
   448		if !res.EstimatedArrivalAt.IsZero() {
   449			out["estimatedArrivalAt"] = formatTime(res.EstimatedArrivalAt)
   450		}
   451		st.audit(ctx, sess, "check_serviceability", "serviceability", req.SampleTypeID, true, map[string]any{"reason": res.Reason})
   452		writeData(w, http.StatusOK, out)
   453	}
