   556	func (st *Store) releaseJourneyCapacity(ctx context.Context, tx *sql.Tx, journeyID string) {
   557		rows, err := tx.QueryContext(ctx, `
   558			SELECT reservation_id, resource_id, cooled, units FROM capacity_reservations
   559			WHERE journey_id = $1 AND active = TRUE`, journeyID)
   560		if err != nil {
   561			return
   562		}
   563		type resv struct {
   564			id, resource string
   565			cooled       bool
   566			units        int
   567		}
   568		var list []resv
   569		for rows.Next() {
   570			var r resv
   571			if err := rows.Scan(&r.id, &r.resource, &r.cooled, &r.units); err == nil {
   572				list = append(list, r)
   573			}
   574		}
   575		rows.Close()
   576		for _, r := range list {
   577			if r.cooled {
   578				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET cooled_reserved_units = GREATEST(cooled_reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   579			} else {
   580				_, _ = tx.ExecContext(ctx, `UPDATE capacity_pools SET reserved_units = GREATEST(reserved_units - $1, 0) WHERE resource_id = $2`, r.units, r.resource)
   581			}
   582			_, _ = tx.ExecContext(ctx, `UPDATE capacity_reservations SET active = FALSE WHERE reservation_id = $1`, r.id)
   583		}
   584	}
