    10	func (st *Store) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
    11		sess := sessionFrom(r.Context())
    12		if err := sess.requireActiveRole(); err != nil {
    13			writeAPIError(w, err)
    14			return
    15		}
    16		journeyID := r.PathValue("journeyId")
    17		if r.Method == http.MethodPost {
    18			var body struct {
    19				JourneyID string `json:"journeyId"`
    20			}
    21			if err := decodeJSON(r, &body); err != nil {
    22				writeAPIError(w, err)
    23				return
    24			}
    25			if body.JourneyID != "" {
    26				journeyID = body.JourneyID
    27			}
    28		}
    29		payload, err := st.journeyPlanPayload(r.Context(), sess, journeyID)
    30		if err != nil {
    31			writeAPIError(w, err)
    32			return
    33		}
    34		writeData(w, http.StatusOK, payload)
    35	}
    36	
    37	func (st *Store) journeyPlanPayload(ctx context.Context, sess *Session, journeyID string) (map[string]any, error) {
    38		var parent sql.NullString
    39		var version int
    40		var mode, status string
    41		var eta sql.NullTime
    42		var cost float64
    43		var capUsed, capAvail int
    44		var valid bool
    45		var replan sql.NullString
    46		err := st.PG.QueryRowContext(ctx, `
    47			SELECT parent_journey_id, plan_version, route_mode, status, estimated_delivery_at,
    48			       total_cost_units, capacity_used, capacity_available, valid, replan_status
    49			FROM journeys WHERE journey_id = $1`, journeyID).
    50			Scan(&parent, &version, &mode, &status, &eta, &cost, &capUsed, &capAvail, &valid, &replan)
    51		if err == sql.ErrNoRows {
    52			return nil, errJSON("not_found", "not found", http.StatusNotFound)
    53		}
    54		if err != nil {
    55			return nil, err
    56		}
    57	
    58		sampleIDs, _ := st.journeySampleIDs(ctx, journeyID)
    59		if sess.ActiveRole == RoleRequester {
    60			ok := false
    61			for _, sid := range sampleIDs {
    62				if st.canSeeSample(ctx, sess, sid) {
    63					ok = true
    64					break
    65				}
    66			}
    67			if !ok {
    68				return nil, errJSON("forbidden", "forbidden", http.StatusForbidden)
    69			}
    70		}
    71	
    72		stops := []map[string]any{}
    73		srows, err := st.PG.QueryContext(ctx, `
    74			SELECT stop_id, location_id, stop_type, sequence, estimated_at, dwell_minutes
    75			FROM journey_stops WHERE journey_id = $1 ORDER BY sequence`, journeyID)
    76		if err == nil {
    77			defer srows.Close()
    78			for srows.Next() {
    79				var sid, lid, stype string
    80				var seq, dwell int
    81				var est time.Time
    82				if err := srows.Scan(&sid, &lid, &stype, &seq, &est, &dwell); err == nil {
    83					stops = append(stops, map[string]any{
    84						"stopId":        sid,
    85						"locationId":    lid,
    86						"stopType":      stype,
    87						"sequence":      seq,
    88						"estimatedAt":   formatTime(est),
    89						"dwellMinutes":  dwell,
    90					})
    91				}
    92			}
    93		}
    94	
    95		assignments := []map[string]any{}
    96		arows, err := st.PG.QueryContext(ctx, `
    97			SELECT assignment_id, kind, status, from_location_id, to_location_id, worker_id, offered_worker_id, sequence
    98			FROM assignments WHERE journey_id = $1 ORDER BY sequence`, journeyID)
    99		if err == nil {
   100			defer arows.Close()
   101			for arows.Next() {
   102				var aid, kind, astatus string
   103				var from, to, worker, offered sql.NullString
   104				var seq int
   105				if err := arows.Scan(&aid, &kind, &astatus, &from, &to, &worker, &offered, &seq); err == nil {
   106					item := map[string]any{
   107						"assignmentId": aid,
   108						"kind":         kind,
   109						"status":       astatus,
   110						"sequence":     seq,
   111					}
   112					if from.Valid {
   113						item["fromLocationId"] = from.String
   114					}
   115					if to.Valid {
   116						item["toLocationId"] = to.String
   117					}
   118					if worker.Valid {
   119						item["workerId"] = worker.String
   120					} else if offered.Valid {
   121						item["workerId"] = offered.String
   122					}
   123					assignments = append(assignments, item)
   124				}
   125			}
   126		}
   127	
   128		// hide extra assignment details for delivery partners
   129		if sess.ActiveRole == RoleDelivery {
   130			filtered := []map[string]any{}
   131			for _, a := range assignments {
   132				wid, _ := a["workerId"].(string)
   133				if wid == sess.UserID {
   134					filtered = append(filtered, a)
   135				}
   136			}
   137			assignments = filtered
   138		}
   139	
   140		var etaVal any
   141		if eta.Valid {
   142			etaVal = formatTime(eta.Time)
   143		}
   144		out := map[string]any{
   145			"journeyId":           journeyID,
   146			"planVersion":         version,
   147			"routeMode":           mode,
   148			"status":              status,
   149			"estimatedDeliveryAt": etaVal,
   150			"totalCostUnits":      cost,
   151			"capacityUsed":        capUsed,
   152			"capacityAvailable":   capAvail,
   153			"valid":               valid,
   154			"stops":               stops,
   155			"assignments":         assignments,
   156			"sampleIds":           sampleIDs,
   157		}
   158		if parent.Valid {
   159			out["parentJourneyId"] = parent.String
   160		}
   161		if replan.Valid && replan.String != "" {
   162			out["replanStatus"] = replan.String
   163		}
   164		return out, nil
   165	}
   166	
   167	func (st *Store) journeySampleIDs(ctx context.Context, journeyID string) ([]string, error) {
   168		rows, err := st.PG.QueryContext(ctx, `SELECT sample_id FROM journey_samples WHERE journey_id = $1`, journeyID)
   169		if err != nil {
   170			return []string{}, err
   171		}
   172		return scanStrings(rows)
   173	}
   174	
   175	func (st *Store) expectPlanVersion(ctx context.Context, journeyID string, expected int) (int, error) {
   176		var current int
   177		err := st.PG.QueryRowContext(ctx, `SELECT plan_version FROM journeys WHERE journey_id = $1`, journeyID).Scan(&current)
   178		if err == sql.ErrNoRows {
   179			return 0, errJSON("not_found", "not found", http.StatusNotFound)
   180		}
   181		if err != nil {
   182			return 0, err
   183		}
   184		if current != expected {
   185			return current, errJSON("plan_version_conflict", "plan version conflict", http.StatusConflict)
   186		}
   187		return current, nil
   188	}
   189	
   190	func (st *Store) bumpPlan(ctx context.Context, tx *sql.Tx, journeyID string) (int, error) {
   191		var v int
   192		err := tx.QueryRowContext(ctx, `
   193			UPDATE journeys SET plan_version = plan_version + 1 WHERE journey_id = $1 RETURNING plan_version`, journeyID).Scan(&v)
   194		return v, err
   195	}

