   464	func parseInt64(s string, dest *int64) (int, error) {
   465		var n int64
   466		for _, c := range s {
   467			if c < '0' || c > '9' {
   468				return 0, errJSON("invalid_json", "invalid", 400)
   469			}
   470			n = n*10 + int64(c-'0')
   471		}
   472		*dest = n
   473		return 0, nil
   474	}
