    69	func (c *wsClient) writePump() {
    70		defer c.conn.Close()
    71		ticker := time.NewTicker(25 * time.Second)
    72		defer ticker.Stop()
    73		for {
    74			select {
    75			case msg, ok := <-c.send:
    76				if !ok {
    77					return
    78				}
    79				_ = c.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
    80				if err := c.conn.WriteMessage(websocket.TextMessage, msg); err != nil {
    81					return
    82				}
    83			case <-ticker.C:
    84				_ = c.conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
    85				if err := c.conn.WriteMessage(websocket.PingMessage, nil); err != nil {
    86					return
    87				}
    88			}
    89		}
