   586	func parseInt64(s string, dest *int64) (int, error) {
   587		var n int64
   588		for _, c := range s {
   589			if c < '0' || c > '9' {
   590				return 0, errJSON("invalid_json", "invalid", 400)
   591			}
   592			n = n*10 + int64(c-'0')
   593		}
   594		*dest = n
   595		return 0, nil
   596	}

